def tabbar_html(path, signed_in):
    here = tabbar_section(path)
    links = []
    for key, label, href, icon in TABBAR_SECTIONS:
        if key == "you" and not signed_in:
            href = "/login"
        mark = PLUS_MARK_SVG if key in PLUS_KEYS else ""
        links.append(f'<a href="{href}" data-tab="{key}" class="{"on" if key == here else ""}" aria-label="{label}">'
                     f'{icon}{mark}<span>{label}</span></a>')
    return (TABBAR_STYLE + f'<nav class="tabbar" data-here="{here or ""}" aria-label="Sections">' + "".join(links)
            + '</nav>' + TABBAR_SCRIPT)


# Registered AFTER the compressor on purpose. Flask runs after_request
# handlers in reverse registration order, so this one runs first and the
# footer is part of the body by the time it is gzipped -- the other way
# round would append plain text after a compressed stream.
@app.after_request
def _append_footer(response):
    """Puts the policy links on every page.

    Done here rather than in forty templates: a link that exists only in
    Settings is invisible to anyone without an account, and an App Store
    reviewer arrives signed out. Appended at the end of the document --
    these pages have no explicit </body>, so trailing content lands in
    the body where it belongs."""
    try:
        if (response.direct_passthrough
                or response.status_code >= 300
                or response.mimetype != "text/html"
                or "Content-Encoding" in response.headers):
            return response
        body = response.get_data(as_text=True)
        # A page that somehow already has one, and the footer's own
        # pages, are left alone.
        if 'footer class="site"' in body:
            return response
        try:
            signed_in = bool(current_user.is_authenticated)
        except Exception:
            signed_in = False
        response.set_data(body + SITE_FOOTER + tabbar_html(request.path, signed_in))
    except Exception:
        # A footer is never worth a 500.
        pass
    return response

# ---------------- Accounts: database ----------------

DATABASE_URL = os.environ.get("DATABASE_URL", "")


_db_pool = None
_db_pool_lock = threading.Lock()
DB_POOL_MAX = int(os.environ.get("DB_POOL_MAX", "10"))


def _get_db_pool():
    """Lazily creates the connection pool on first real use (DATABASE_URL
    can be empty in local/dev/test runs, and importing this module must
    never fail just because Postgres isn't configured)."""
    global _db_pool
    if _db_pool is None:
        with _db_pool_lock:
            if _db_pool is None:
                _db_pool = psycopg2.pool.ThreadedConnectionPool(
                    1, DB_POOL_MAX, DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor,
                )
    return _db_pool


class _PooledConnection:
    """Every one of this file's many get_db() call sites already follows
    `conn = get_db(); try: ... finally: conn.close()` -- opening a brand
    new TCP+TLS connection to Postgres for every single query (the old
    behavior) was a real, avoidable chunk of every page's load time,
    multiplied by how many self-healing checks (ensure_schedule_synced,
    get_season_stats, get_schedule_for_team_week, ...) a single request
    can now trigger. This wraps a pooled connection so `.close()` hands
    it back to the pool instead of tearing it down -- none of those
    existing call sites need to change. Rolling back before returning it
    clears any uncommitted/aborted transaction state first, which is
    exactly what closing a raw connection without a prior commit()
    already did -- so this preserves today's behavior, it doesn't change
    it, while actually reusing the underlying connection.

    A raw psycopg2 connection tolerates being close()d more than once --
    it's a harmless no-op. Returning the SAME connection to a pool twice
    is not: the pool can't find it the second time and raises, and if
    that ever happened right after a legitimate first return, a second
    caller could receive it from getconn() while the code that "closed"
    it the first time still thinks it owns it. close() here is made
    idempotent (and never lets a pool-level error escape to break a
    request) specifically so this wrapper is at least as forgiving as
    the raw connection it replaces."""
    __slots__ = ("_conn", "_pool", "_returned")

    def __init__(self, conn, pool):
        self._conn = conn
        self._pool = pool
        self._returned = False

    def close(self):
        if self._returned:
            return
        self._returned = True
        try:
            self._conn.rollback()
        except Exception:
            # A dead/broken connection (the rollback itself failed) must
            # not go back into circulation for the next borrower to trip
            # over -- tell the pool to actually discard it instead.
            try:
                self._pool.putconn(self._conn, close=True)
            except Exception:
                pass
            return
        try:
            self._pool.putconn(self._conn)
        except Exception:
            pass

    def __getattr__(self, name):
        return getattr(self._conn, name)


DB_CHECKOUT_TRIES = 3


def _connection_alive(conn):
    """One trivial round trip. A pooled connection that sat through the
    database going to sleep (Neon suspends after five idle minutes) or
    through a network blip looks open from here and is dead on the other
    end; only asking it finds out. The cost is a millisecond or two per
    checkout, against an error page for the first reader back."""
    try:
        if getattr(conn, "closed", 0):
            return False
        with conn.cursor() as cur:
            cur.execute("SELECT 1")
            cur.fetchone()
        conn.rollback()
        return True
    except Exception:
        return False


def get_db():
    """A pooled connection -- see _PooledConnection's docstring -- that
    has just answered a query, so a stale one is replaced before a
    request ever sees it. Falls back to a plain unpooled connection if
    the pool can't be created (e.g. a malformed DATABASE_URL), so a
    pool-specific failure doesn't take down every DB-using route that
    already worked before pooling existed."""
    try:
        pool = _get_db_pool()
    except Exception:
        return psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)
    for _ in range(DB_CHECKOUT_TRIES):
        conn = pool.getconn()
        if _connection_alive(conn):
            return _PooledConnection(conn, pool)
        # Dead: hand it back closed so the pool makes a fresh one next.
        try:
            pool.putconn(conn, close=True)
        except Exception:
            pass
    return psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)


def init_db():
    if not DATABASE_URL:
        return
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS users (
                    id SERIAL PRIMARY KEY,
                    email TEXT UNIQUE,
                    password_hash TEXT,
                    username TEXT UNIQUE NOT NULL,
                    oauth_provider TEXT,
                    oauth_sub TEXT,
                    referral_code TEXT,
                    newsletter_opt_in BOOLEAN DEFAULT TRUE,
                    is_member BOOLEAN DEFAULT FALSE,
                    created_at TIMESTAMP DEFAULT NOW(),
                    UNIQUE (oauth_provider, oauth_sub)
                );
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS votes (
                    id SERIAL PRIMARY KEY,
                    sleeper_id TEXT NOT NULL,
                    player_name TEXT,
                    position TEXT,
                    label TEXT NOT NULL CHECK (label IN ('start', 'bench', 'cut')),
                    user_id INTEGER REFERENCES users(id),
                    created_at TIMESTAMP DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_votes_sleeper_id ON votes (sleeper_id);")
            cur.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_users_username_lower ON users (lower(username));")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_stats (
                    sleeper_id TEXT NOT NULL,
                    season INTEGER NOT NULL,
                    week INTEGER NOT NULL,
                    fpts REAL DEFAULT 0,
                    off_snp INTEGER DEFAULT 0,
                    tm_off_snp INTEGER DEFAULT 0,
                    updated_at TIMESTAMP DEFAULT NOW(),
                    PRIMARY KEY (sleeper_id, season, week)
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_player_stats_lookup ON player_stats (sleeper_id, season);")
            # get_season_stats -- the single most-called query in the app
            # now that matchup grading pulls it for the current season,
            # last season, and (for head-to-head history) up to 6 seasons
            # back -- filters on season ALONE. Neither the primary key
            # nor idx_player_stats_lookup above are usable for that (both
            # lead with sleeper_id), so every one of those calls was
            # doing a full sequential scan of a table that only grows.
            cur.execute("CREATE INDEX IF NOT EXISTS idx_player_stats_season ON player_stats (season);")
            # Receptions. Every scoring format on this site differs from
            # PPR only in what a catch is worth, so the stored PPR figure
            # plus this one number rescores a whole season exactly --
            # no second source, no re-deriving points from raw stats.
            cur.execute("ALTER TABLE player_stats ADD COLUMN IF NOT EXISTS rec REAL DEFAULT 0;")
            # The whole stat line, as Sleeper sent it. Streaks needs
            # every game's passing, rushing, receiving, kicking and
            # tackling figures, and until now the sync kept four numbers
            # from a dict of sixty and threw the rest away. JSONB rather
            # than sixty columns because Sleeper's key set is not ours to
            # freeze: a stat they add simply appears, one they rename
            # simply stops being read.
            cur.execute("ALTER TABLE player_stats ADD COLUMN IF NOT EXISTS stats JSONB;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS sleeper_username TEXT;")
            # Rankings defaults. Format and mode were URL parameters only,
            # so every visit started on 1QB dynasty regardless of the
            # league anyone actually plays in.
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pref_format TEXT;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pref_mode TEXT;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pref_scoring TEXT;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pref_theme TEXT;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS pref_accent TEXT;")
            # StreakPros+ billing. The old is_member flag stays as a hand-set
            # complimentary switch; everything Stripe reports lives here.
            for col in ("stripe_customer_id TEXT", "stripe_subscription_id TEXT", "plan TEXT",
                        "member_status TEXT", "access_until TIMESTAMP", "current_period_end TIMESTAMP",
                        "cancel_at_period_end BOOLEAN DEFAULT FALSE",
                        "founding_member BOOLEAN DEFAULT FALSE", "plan_updated_at TIMESTAMP"):
                cur.execute(f"ALTER TABLE users ADD COLUMN IF NOT EXISTS {col};")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_users_stripe_customer ON users (stripe_customer_id);")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_users_stripe_subscription ON users (stripe_subscription_id);")
            # Every Stripe event id and Checkout session id applied so far:
            # a redelivery, or the success page racing the webhook, is a no-op.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS processed_stripe_events (
                    event_id TEXT PRIMARY KEY,
                    processed_at TIMESTAMP DEFAULT NOW()
                );
            """)
            # Rating Draft picks: one row per slot, keyed on the NFL day.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS draft_entries (
                    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                    draft_day DATE NOT NULL,
                    season INTEGER NOT NULL,
                    week INTEGER NOT NULL,
                    slot INTEGER NOT NULL,
                    sleeper_id TEXT NOT NULL,
                    multiplier REAL NOT NULL,
                    boost REAL NOT NULL,
                    event_id TEXT,
                    submitted_at TIMESTAMP DEFAULT NOW(),
                    updated_at TIMESTAMP DEFAULT NOW(),
                    PRIMARY KEY (user_id, draft_day, slot)
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_draft_entries_day ON draft_entries (draft_day);")
            # Player contracts, one row per active OverTheCap contract,
            # posted by the contracts job (see /api/sync-contracts).
            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_contracts (
                    key TEXT PRIMARY KEY,
                    gsis_id TEXT,
                    name_key TEXT,
                    position TEXT,
                    data JSONB NOT NULL,
                    source_stamp TEXT,
                    updated_at TIMESTAMP DEFAULT NOW()
                );
            """)
            # Avatars live apart from users because load_user does a
            # SELECT * on that row for every single request -- putting
            # image bytes there would drag a picture through every page
            # load on the site.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS user_avatars (
                    user_id INTEGER PRIMARY KEY REFERENCES users(id),
                    image BYTEA NOT NULL,
                    mimetype TEXT NOT NULL,
                    updated_at TIMESTAMP DEFAULT NOW()
                );
            """)
            # A counter on the users row, so a page can build a
            # cache-busting avatar URL without reading the image.
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_version INTEGER DEFAULT 0;")
            # When the username was last changed, so the cooldown has
            # something to measure from. NULL means never changed.
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS username_changed_at TIMESTAMP;")
            # Which alerts an account wants. NULL means never chosen,
            # which reads as on (see User.__init__) -- newsletter_opt_in
            # remains the master switch the unsubscribe link throws.
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS alert_lineup BOOLEAN;")
            cur.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS alert_waivers BOOLEAN;")
            # One row per alert actually sent. This is what stops the
            # hourly job emailing the same reader the same warning
            # twenty times before kickoff: the row is claimed BEFORE the
            # message goes out, so two runs overlapping cannot both
            # send, and it is released again if the send fails so a
            # provider outage costs a delay rather than the alert.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS sent_alerts (
                    user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
                    kind       TEXT NOT NULL,
                    dedupe_key TEXT NOT NULL,
                    sent_at    TIMESTAMP DEFAULT NOW(),
                    PRIMARY KEY (user_id, kind, dedupe_key)
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_sent_alerts_when ON sent_alerts (sent_at);")
            # Reset tokens are stored HASHED. A raw token in the table is
            # a password-equivalent secret sitting in plain text, and a
            # leaked backup would hand over every account with one open.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS password_resets (
                    token_hash TEXT PRIMARY KEY,
                    user_id    INTEGER NOT NULL REFERENCES users(id),
                    created_at TIMESTAMP NOT NULL DEFAULT NOW(),
                    expires_at TIMESTAMP NOT NULL,
                    used_at    TIMESTAMP
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_password_resets_user ON password_resets (user_id);")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS synced_leagues (
                    user_id INTEGER REFERENCES users(id),
                    league_id TEXT NOT NULL,
                    PRIMARY KEY (user_id, league_id)
                );
            """)
            cur.execute("""
                CREATE TABLE IF NOT EXISTS nfl_schedule (
                    espn_event_id TEXT PRIMARY KEY,
                    season INTEGER NOT NULL,
                    week INTEGER NOT NULL,
                    season_type INTEGER NOT NULL DEFAULT 2,
                    kickoff TIMESTAMP,
                    home_team TEXT NOT NULL,
                    away_team TEXT NOT NULL,
                    home_score INTEGER,
                    away_score INTEGER,
                    status TEXT,
                    updated_at TIMESTAMP DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nfl_schedule_season_week ON nfl_schedule (season, week);")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nfl_schedule_home_team ON nfl_schedule (season, home_team);")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_nfl_schedule_away_team ON nfl_schedule (season, away_team);")
            cur.execute("""
                CREATE TABLE IF NOT EXISTS referee_games (
                    espn_event_id TEXT PRIMARY KEY,
                    season INTEGER NOT NULL,
                    week INTEGER NOT NULL,
                    referee_name TEXT,
                    officials_json JSONB,
                    home_team TEXT NOT NULL,
                    away_team TEXT NOT NULL,
                    home_score INTEGER,
                    away_score INTEGER,
                    home_penalties INTEGER,
                    home_penalty_yards INTEGER,
                    away_penalties INTEGER,
                    away_penalty_yards INTEGER,
                    updated_at TIMESTAMP DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_referee_games_referee ON referee_games (referee_name);")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_referee_games_season ON referee_games (season);")
            # One row per player, holding the injury designation we last
            # saw and the one before it. Sleeper publishes only the
            # CURRENT designation -- "Out -> Active" is not a thing you
            # can fetch, it is a thing you have to have been watching
            # for. This table is the watching.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_injury_state (
                    sleeper_id      TEXT PRIMARY KEY,
                    status          TEXT,
                    previous_status TEXT,
                    changed_at      TIMESTAMP DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_injury_state_changed "
                        "ON player_injury_state (changed_at DESC);")
            # Roster moves, watched exactly the way designations are:
            # Sleeper's dump carries each player's current team, so a
            # signing, a release and a trade are all just that field
            # changing. A player off every roster is stored as 'NR', not
            # NULL, so that NULL keeps one meaning only: never seen. That
            # is what makes "NR -> KC" and "CHI -> NR" reportable without
            # the first fill reading as two thousand signings.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_team_state (
                    sleeper_id    TEXT PRIMARY KEY,
                    team          TEXT,
                    previous_team TEXT,
                    changed_at    TIMESTAMP DEFAULT NOW()
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_team_state_changed "
                        "ON player_team_state (changed_at DESC);")
            # FantasyCalc publishes only today's value, so a rise or a
            # fall exists only if someone wrote yesterday's down. One row
            # per player per format per mode per day; the Rankings page
            # reads the row from a week back and reports the difference.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS player_value_history (
                    sleeper_id    TEXT NOT NULL,
                    num_qbs       INTEGER NOT NULL,
                    dynasty       BOOLEAN NOT NULL,
                    num_teams     INTEGER NOT NULL DEFAULT 12,
                    day           DATE NOT NULL,
                    value         INTEGER,
                    overall_rank  INTEGER,
                    position_rank INTEGER,
                    PRIMARY KEY (sleeper_id, num_qbs, dynasty, num_teams, day)
                );
            """)
            cur.execute("CREATE INDEX IF NOT EXISTS idx_value_history_day "
                        "ON player_value_history (num_qbs, dynasty, num_teams, day);")
            # Sportsbook lines for this week's props, from The Odds API
            # when a key is configured. Kept in the database so a restart
            # never re-spends the request quota re-fetching what was
            # already fetched, and so the warm ping can measure "how old
            # is what we have" against a real timestamp.
            cur.execute("""
                CREATE TABLE IF NOT EXISTS prop_lines (
                    season      INTEGER NOT NULL,
                    week        INTEGER NOT NULL,
                    sleeper_id  TEXT NOT NULL,
                    prop        TEXT NOT NULL,
                    line        REAL NOT NULL,
                    over_price  INTEGER,
                    under_price INTEGER,
                    book        TEXT NOT NULL,
                    fetched_at  TIMESTAMP DEFAULT NOW(),
                    PRIMARY KEY (season, week, sleeper_id, prop)
                );
            """)
        conn.commit()
    finally:
        conn.close()


if DATABASE_URL:
    init_db()

