login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = "login"


class User(UserMixin):
    def __init__(self, row):
        self.id = str(row["id"])
        self.email = row["email"]
        self.username = row["username"]
        # Billing. is_member is the computed answer (see has_mycalc_plus);
        # the column of the same name is a hand-set complimentary flag.
        self.comped = bool(row.get("is_member"))
        self.plan = row.get("plan") or "none"
        self.member_status = row.get("member_status") or ""
        self.access_until = row.get("access_until")
        self.current_period_end = row.get("current_period_end")
        self.cancel_at_period_end = bool(row.get("cancel_at_period_end"))
        self.founding_member = bool(row.get("founding_member"))
        self.stripe_customer_id = row.get("stripe_customer_id")
        self.stripe_subscription_id = row.get("stripe_subscription_id")
        self.is_member = has_mycalc_plus(row)
        self.sleeper_username = row.get("sleeper_username")
        self.pref_format = row.get("pref_format") or "1qb"
        self.pref_mode = row.get("pref_mode") or "dynasty"
        self.pref_scoring = row.get("pref_scoring") or DEFAULT_SCORING
        self.pref_theme = normalize_theme(row.get("pref_theme"))
        self.pref_accent = normalize_accent(row.get("pref_accent"))
        self.avatar_version = row.get("avatar_version") or 0
        self.username_changed_at = row.get("username_changed_at")
        self.newsletter_opt_in = bool(row.get("newsletter_opt_in"))
        # Alerts default ON for an account that has never chosen: an
        # account made before these existed has NULL in both columns,
        # and a reader who synced a league wants to be told his starter
        # is out. The unsubscribe link still turns everything off.
        self.alert_lineup = row.get("alert_lineup") is not False
        self.alert_waivers = row.get("alert_waivers") is not False


@login_manager.user_loader
def load_user(user_id):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM users WHERE id = %s", (user_id,))
            row = cur.fetchone()
            return User(row) if row else None
    finally:
        conn.close()


def username_valid(u):
    return bool(u) and 1 <= len(u) <= 20 and re.fullmatch(r"[A-Za-z0-9_]+", u)


def username_available(u):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM users WHERE lower(username) = lower(%s)", (u,))
            return cur.fetchone() is None
    finally:
        conn.close()


def get_synced_league_ids(user_id):
    """None means the user has never made a selection yet -- show the
    picker. A saved selection always has at least one league (the picker
    requires picking at least one before it submits)."""
    if not DATABASE_URL:
        return None
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT league_id FROM synced_leagues WHERE user_id = %s", (user_id,))
            rows = cur.fetchall()
            if not rows:
                return None
            return {r["league_id"] for r in rows}
    finally:
        conn.close()


def set_synced_league_ids(user_id, league_ids):
    if not DATABASE_URL:
        return
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM synced_leagues WHERE user_id = %s", (user_id,))
            if league_ids:
                psycopg2.extras.execute_values(
                    cur, "INSERT INTO synced_leagues (user_id, league_id) VALUES %s",
                    [(user_id, lid) for lid in league_ids],
                )
        conn.commit()
    finally:
        conn.close()

