@app.route("/api/check-username")
def api_check_username():
    u = request.args.get("u", "").strip()
    if not username_valid(u):
        return jsonify({"available": False, "reason": "invalid"})
    if not username_available(u):
        return jsonify({"available": False, "reason": "taken"})
    return jsonify({"available": True, "reason": None})


# --- sending mail --------------------------------------------------------
#
# Plain SMTP through the standard library, so this adds no dependency and
# works with whatever provider gets pointed at it -- Resend, SendGrid,
# Postmark, SES, Fastmail, all of them speak SMTP.
#
# Nothing is configured here. Set these five and mail starts sending; set
# none and the app keeps working, the reset flow still answers the same
# way it always does, and the link is written to the log instead of an
# inbox so it is recoverable rather than lost.
SMTP_HOST = os.environ.get("SMTP_HOST")
SMTP_PORT = _safe_int(os.environ.get("SMTP_PORT"), 587)
SMTP_USER = os.environ.get("SMTP_USER")
SMTP_PASSWORD = os.environ.get("SMTP_PASSWORD")
# Still the old domain on purpose: this is only the fallback for an
# unset variable, and sending from streakpros.com before Resend has
# verified it means every password reset and alert bounces. Render's
# MAIL_FROM is the switch, flipped once Resend says Verified.
MAIL_FROM = os.environ.get("MAIL_FROM") or "no-reply@fantasyfootballcalc.com"
MAIL_FROM_NAME = os.environ.get("MAIL_FROM_NAME") or "StreakPros"
# Where links in an email point. Behind a proxy the request's own host is
# whatever the proxy said it was, which is not something to build a
# password-reset link out of.
# Likewise: the fallback stays on the domain that is serving today, so
# a missing variable cannot put a dead link in an email. Render's
# SITE_URL moves to https://streakpros.com once DNS and TLS are live.
SITE_URL = (os.environ.get("SITE_URL") or "https://fantasyfootballcalc.com").rstrip("/")


def mail_configured():
    return bool(SMTP_HOST and MAIL_FROM)


def send_email(to_address, subject, text_body, html_body=None):
    """True if it went out. False is never fatal to the caller -- a page
    that depends on mail having been delivered is a page that breaks
    every time a mail provider has a bad minute."""
    return send_email_reason(to_address, subject, text_body, html_body)[0]


def send_email_reason(to_address, subject, text_body, html_body=None):
    """(sent, reason). The reason is what a diagnostic needs: "it didn't
    work" is not something anyone can act on, and the mail server almost
    always says exactly what is wrong."""
    if not to_address:
        return False, "no recipient address"
    if not mail_configured():
        app.logger.warning(
            "email not configured (set SMTP_HOST/SMTP_USER/SMTP_PASSWORD/MAIL_FROM); "
            "would have sent %r to %s", subject, to_address)
        return False, "SMTP_HOST or MAIL_FROM is not set on this server"
    try:
        msg = EmailMessage()
        msg["Subject"] = subject
        msg["From"] = f"{MAIL_FROM_NAME} <{MAIL_FROM}>"
        msg["To"] = to_address
        msg.set_content(text_body)
        if html_body:
            msg.add_alternative(html_body, subtype="html")
        # 465 is implicit TLS; everything else starts plain and upgrades.
        if SMTP_PORT == 465:
            server = smtplib.SMTP_SSL(SMTP_HOST, SMTP_PORT, timeout=15)
        else:
            server = smtplib.SMTP(SMTP_HOST, SMTP_PORT, timeout=15)
        try:
            if SMTP_PORT != 465:
                server.starttls()
            if SMTP_USER:
                server.login(SMTP_USER, SMTP_PASSWORD or "")
            server.send_message(msg)
        finally:
            server.quit()
        return True, None
    except Exception as e:
        app.logger.exception("could not send %r to %s", subject, to_address)
        return False, "%s: %s" % (type(e).__name__, e)


# --- password resets -----------------------------------------------------
PASSWORD_RESET_TTL_HOURS = 2
MIN_PASSWORD_LENGTH = 8


def _hash_reset_token(token):
    return hashlib.sha256(token.encode()).hexdigest()


def create_password_reset(user_id):
    """A fresh single-use token. Any earlier one for this account is
    spent at the same time: asking again should invalidate the link in
    the older email rather than leave two doors open."""
    token = secrets.token_urlsafe(32)
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "UPDATE password_resets SET used_at = NOW() "
                "WHERE user_id = %s AND used_at IS NULL", (int(user_id),))
            cur.execute(
                "INSERT INTO password_resets (token_hash, user_id, expires_at) "
                "VALUES (%s, %s, NOW() + INTERVAL '%s hours')",
                (_hash_reset_token(token), int(user_id), PASSWORD_RESET_TTL_HOURS))
        conn.commit()
    finally:
        conn.close()
    return token


def consume_password_reset(token, new_password):
    """Set the password if the token is good. Returns (ok, message).

    The token is checked and spent inside one transaction, so the same
    link cannot be used twice by two requests arriving together."""
    if not token:
        return False, "That reset link is not valid."
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT user_id FROM password_resets
                   WHERE token_hash = %s AND used_at IS NULL AND expires_at > NOW()
                   FOR UPDATE""",
                (_hash_reset_token(token),))
            row = cur.fetchone()
            if not row:
                return False, "That reset link has expired or has already been used."
            cur.execute("UPDATE password_resets SET used_at = NOW() WHERE token_hash = %s",
                        (_hash_reset_token(token),))
            cur.execute("UPDATE users SET password_hash = %s WHERE id = %s",
                        (generate_password_hash(new_password), row["user_id"]))
            # Every other outstanding link for this account dies with it.
            cur.execute("UPDATE password_resets SET used_at = NOW() "
                        "WHERE user_id = %s AND used_at IS NULL", (row["user_id"],))
        conn.commit()
        return True, None
    except Exception as e:
        app.logger.exception("password reset failed")
        return False, str(e)
    finally:
        conn.close()


def user_by_email(email):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM users WHERE lower(email) = lower(%s)", (email,))
            return cur.fetchone()
    finally:
        conn.close()


# --- unsubscribing ------------------------------------------------------
#
# The link in an email has to work for someone who is not signed in and
# may not remember they have an account, so it carries proof of its own:
# an HMAC over the user id, keyed on the app secret. Nothing to store,
# nothing to expire, and a link cannot be edited to unsubscribe somebody
# else -- changing the id invalidates the signature.
def unsubscribe_token(user_id):
    return hmac.new(app.secret_key.encode(), f"unsub:{user_id}".encode(),
                    hashlib.sha256).hexdigest()[:32]


def unsubscribe_link(user_id):
    return f"{SITE_URL}/unsubscribe?u={user_id}&t={unsubscribe_token(user_id)}"


def _email_footer(user_id):
    """The unsubscribe line every message carries, in both formats.

    CAN-SPAM wants a working opt-out in commercial mail. It goes on
    transactional mail too -- a password reset is not marketing and says
    so, but a reader deciding they want out should never have to work out
    which kind of email they are holding."""
    if not user_id:
        return "", ""
    link = unsubscribe_link(user_id)
    text = ("\n\n--\n"
            "StreakPros\n"
            f"Stop receiving emails: {link}\n"
            f"Privacy policy: {SITE_URL}/privacy")
    # Centred on the same 600px as the card above it, so it reads as the
    # bottom of one message rather than a loose paragraph stuck on after.
    body = (
        f'<div style="background:{EMAIL_BG};padding:0 10px 26px;font-family:{EMAIL_FONT};">'
        f'<table role="presentation" align="center" width="{EMAIL_WIDTH}" cellpadding="0" '
        f'cellspacing="0" border="0" style="width:{EMAIL_WIDTH}px;max-width:100%;margin:0 auto;">'
        f'<tr><td style="padding:14px 20px 0;color:{EMAIL_MUTED};font-size:12px;line-height:1.7;">'
        f'StreakPros<br>'
        f'<a href="{link}" style="color:{EMAIL_MUTED};">Stop receiving emails</a> &middot; '
        f'<a href="{SITE_URL}/privacy" style="color:{EMAIL_MUTED};">Privacy policy</a>'
        f'</td></tr></table></div>')
    return text, body


def send_password_reset_email(row, token):
    link = f"{SITE_URL}/reset-password?token={token}"
    name = row.get("username") or "there"
    text = (
        f"Hi {name},\n\n"
        f"Someone asked to reset the password for your StreakPros "
        f"account. Open this link to choose a new one:\n\n{link}\n\n"
        f"The link works once and expires in {PASSWORD_RESET_TTL_HOURS} hours.\n\n"
        f"If this wasn't you, ignore this email -- your password has not changed.\n\n"
        f"This is an account security email, not a newsletter: it is sent only "
        f"when someone asks to reset this account's password."
    )
    body = (
        f'<p>Hi {html.escape(str(name))},</p>'
        f'<p>Someone asked to reset the password for your StreakPros account. '
        f'Choose a new one here:</p>'
        f'<p><a href="{link}" style="background:#b97a1f;color:#fff8ec;padding:11px 22px;'
        f'border-radius:99px;text-decoration:none;font-weight:700;display:inline-block;">'
        f'Reset your password</a></p>'
        f'<p style="color:#666;font-size:13px;">The link works once and expires in '
        f'{PASSWORD_RESET_TTL_HOURS} hours. If this wasn\'t you, ignore this email '
        f'&mdash; your password has not changed.</p>'
        f'<p style="color:#888;font-size:12px;">This is an account security email, '
        f'not a newsletter: it is sent only when someone asks to reset this '
        f'account\'s password.</p>'
    )
    foot_text, foot_html = _email_footer(row.get("id"))
    sent = send_email(row.get("email"), "Reset your StreakPros password",
                      text + foot_text, body + foot_html)
    if not sent:
        # Recoverable rather than lost: without a mail provider the link
        # is in the log, which is the only place it could safely go. It
        # must never reach the page -- that would let anyone reset any
        # account by typing the address.
        app.logger.warning("password reset link for user %s: %s", row.get("id"), link)
    return sent


# --- changing a username -------------------------------------------------
USERNAME_CHANGE_DAYS = 30


def username_change_allowed_at(changed_at):
    """When the next change is allowed, or None if it is allowed now."""
    if not changed_at:
        return None
    nxt = changed_at + timedelta(days=USERNAME_CHANGE_DAYS)
    return nxt if nxt > datetime.utcnow() else None


# Where signing in or up lands you: game day, not the rankings. A login
# bounced off a gated page still goes back there (?next=).
SIGNED_IN_HOME = "/scores"


@app.route("/signup", methods=["GET", "POST"])
def signup():
    error = None
    if request.method == "POST":
        email = request.form.get("email", "").strip().lower()
        password = request.form.get("password", "")
        username = request.form.get("username", "").strip()
        referral_code = request.form.get("referral_code", "").strip() or None
        newsletter = "newsletter" in request.form
        agreed_tos = "agree_tos" in request.form

        if not email or "@" not in email:
            error = "Enter a valid email address."
        elif len(password) < 8:
            error = "Password must be at least 8 characters."
        elif not username_valid(username):
            error = "Username must be 1-20 letters, numbers, or underscores."
        elif not agreed_tos:
            error = "You must agree to the Terms of Service and Privacy Policy."

        if not error:
            conn = None
            try:
                conn = get_db()
                with conn.cursor() as cur:
                    cur.execute(
                        """INSERT INTO users (email, password_hash, username, referral_code, newsletter_opt_in)
                           VALUES (%s, %s, %s, %s, %s) RETURNING id""",
                        (email, generate_password_hash(password), username, referral_code, newsletter),
                    )
                    new_id = cur.fetchone()["id"]
                conn.commit()
                login_user(User({"id": new_id, "email": email, "username": username, "is_member": False}), remember=True)
                return redirect(SIGNED_IN_HOME)
            except psycopg2.errors.UniqueViolation:
                if conn:
                    conn.rollback()
                error = "That username or email is already taken."
            except Exception as e:
                if conn:
                    conn.rollback()
                error = f"Something went wrong creating your account: {e}"
            finally:
                if conn:
                    conn.close()

    return render_template_string(SIGNUP_HTML, error=error)


@app.route("/login", methods=["GET", "POST"])
def login():
    error = None
    if request.method == "POST":
        identifier = request.form.get("email", "").strip().lower()
        password = request.form.get("password", "")
        try:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT * FROM users WHERE email = %s OR lower(username) = %s",
                        (identifier, identifier),
                    )
                    row = cur.fetchone()
            finally:
                conn.close()
        except Exception as e:
            row = None
            error = f"Couldn't reach the login system: {e}"

        if not error:
            if row and row["password_hash"] and check_password_hash(row["password_hash"], password):
                login_user(User(row), remember=True)
                return redirect(_safe_next() or SIGNED_IN_HOME)
            error = "Incorrect email/username or password."
    return render_template_string(LOGIN_PAGE_HTML, error=error)


# --- profile pictures ----------------------------------------------------
#
# Stored in the database rather than on disk: this runs on an instance
# whose filesystem does not survive a deploy, so a file written there is
# a picture that vanishes the next time the app ships.
#
# Nothing resizes it, because there is no image library here and adding
# one to crop a handful of avatars is not a trade worth making. Instead
# the cap is small enough that an unresized file is still a reasonable
# thing to send, and the browser does the fitting.
# Not a limit anyone should meet. The browser shrinks a picture to a
# square JPEG before uploading it, so a real avatar arrives at a few tens
# of kilobytes whatever came off the camera roll; this is the backstop
# for the case where that did not run, sized to take a full-resolution
# phone photo rather than to turn one away.
AVATAR_MAX_BYTES = 12 * 1024 * 1024
# Read from the bytes, never from the filename or the browser's claim --
# both are just strings the uploader chose.
_AVATAR_SIGNATURES = (
    (b"\x89PNG\r\n\x1a\n", "image/png"),
    (b"\xff\xd8\xff", "image/jpeg"),
    (b"GIF87a", "image/gif"),
    (b"GIF89a", "image/gif"),
)


def sniff_image(data):
    """The real type of an uploaded image, or None if it is not one."""
    if not data:
        return None
    for sig, mime in _AVATAR_SIGNATURES:
        if data.startswith(sig):
            return mime
    # WebP is RIFF....WEBP -- the marker sits past a length field.
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    return None


def save_avatar(user_id, data, mimetype):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """INSERT INTO user_avatars (user_id, image, mimetype, updated_at)
                   VALUES (%s, %s, %s, NOW())
                   ON CONFLICT (user_id) DO UPDATE
                   SET image = EXCLUDED.image, mimetype = EXCLUDED.mimetype,
                       updated_at = NOW()""",
                (int(user_id), psycopg2.Binary(data), mimetype))
            cur.execute(
                "UPDATE users SET avatar_version = COALESCE(avatar_version, 0) + 1 "
                "WHERE id = %s RETURNING avatar_version", (int(user_id),))
            row = cur.fetchone()
        conn.commit()
        return (row or {}).get("avatar_version") or 1
    finally:
        conn.close()


def delete_avatar(user_id):
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM user_avatars WHERE user_id = %s", (int(user_id),))
            # Bumped on removal too, so a browser holding the old picture
            # under a long cache is asked for a URL it has never seen.
            cur.execute(
                "UPDATE users SET avatar_version = COALESCE(avatar_version, 0) + 1 "
                "WHERE id = %s RETURNING avatar_version", (int(user_id),))
            row = cur.fetchone()
        conn.commit()
        return (row or {}).get("avatar_version") or 1
    finally:
        conn.close()


def get_avatar(user_id):
    if not DATABASE_URL:
        return None
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT image, mimetype FROM user_avatars WHERE user_id = %s",
                        (int(user_id),))
            row = cur.fetchone()
            return (bytes(row["image"]), row["mimetype"]) if row else None
    except Exception:
        return None
    finally:
        conn.close()


@app.route("/avatar/<int:user_id>")
def avatar_image(user_id):
    """Served under a ?v= that changes on every upload, which is what
    lets the response be cached for a year and still update the instant
    someone changes their picture."""
    found = get_avatar(user_id)
    if not found:
        return redirect("/favicon.svg")
    data, mimetype = found
    resp = make_response(data)
    resp.headers["Content-Type"] = mimetype
    resp.headers["Cache-Control"] = "public, max-age=31536000, immutable"
    return resp


# Which screens Settings is made of, in the order they are listed.
# (key, label) -- the summary beside each is computed per reader below.
# --- StreakPros+ billing (Stripe) --------------------------------------------
#
# One paid tier, two ways to buy it: a monthly subscription, or a season
# pass paid once. Stripe Checkout takes the card on Stripe's own page;
# the webhook at /api/stripe-webhook is what grants and revokes access.
# The success page applies the same grant from the retrieved session so
# a buyer sees "you're in" without waiting on webhook delivery -- both
# paths are idempotent on the Checkout session id, so whichever lands
# second is a no-op.
#
# Nothing here is fatal at import. A missing key logs a loud warning and
# turns the pricing page's buttons into "not open yet" rather than taking
# the site down with it, because every push deploys live and the keys
# are added by hand in Render after the code ships.

STRIPE_API_VERSION = "2026-08-26.dahlia"
STRIPE_SECRET_KEY = os.environ.get("STRIPE_SECRET_KEY", "")
STRIPE_PUBLISHABLE_KEY = os.environ.get("STRIPE_PUBLISHABLE_KEY", "")
STRIPE_WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET", "")
STRIPE_PRICES = {
    "monthly": os.environ.get("STRIPE_PRICE_MONTHLY", ""),
    "season": os.environ.get("STRIPE_PRICE_SEASON", ""),
    "founding": os.environ.get("STRIPE_PRICE_FOUNDING", ""),
    # The $1 one-time price the trial charges on day one. Optional:
    # without it the trial offer is simply not shown.
    "trial": os.environ.get("STRIPE_PRICE_TRIAL", ""),
}
PLAN_MODES = {"monthly": "subscription", "season": "payment", "founding": "payment", "trial": "subscription"}
PLAN_NAMES = {"monthly": "StreakPros+ Monthly", "season": "StreakPros+ Season Pass",
              "founding": "StreakPros+ Founding Season Pass", "trial": "StreakPros+ Monthly"}
# Display only. Stripe charges the price object; these just have to
# agree with it on the pricing page.
PLAN_PRICES = {"monthly": "$6.99", "season": "$29.99", "founding": "$19.99", "trial": "$1"}
# The trial: $1 today for TRIAL_DAYS days of Monthly, then the monthly
# price unless cancelled first. First-time members only.
TRIAL_DAYS = 3
# The gate is a switch, off until the owner has watched a real purchase
# land. Off, every page behaves exactly as before billing existed (the
# sign-in gates only); on, the StreakPros+ pages ask for the plan.
PAYWALL = (os.environ.get("PAYWALL") or "").strip().lower() in ("1", "true", "yes", "on")
# Last day the founding price is on sale, inclusive, Central time.
FOUNDING_CUTOFF = os.environ.get("FOUNDING_CUTOFF") or "2026-10-04"
# A season pass runs through the end of February: the league year turns
# over in March, and so does the pass.
SEASON_PASS_END_MONTH_DAY = (2, 28)
CENTRAL_TZ = ZoneInfo("America/Chicago")
# past_due keeps access: Stripe retries the card for weeks before it
# gives up, and customer.subscription.deleted is the real end signal.
MEMBER_STATUSES_WITH_ACCESS = ("active", "trialing", "past_due")
STREAK_FREE_ROWS = 3
FREE_LEAGUE_LIMIT = 1


def billing_missing():
    """Names of the Stripe variables not set on this server. The founding
    price is optional: without it the launch offer simply isn't shown."""
    checks = (("STRIPE_SECRET_KEY", STRIPE_SECRET_KEY),
              ("STRIPE_WEBHOOK_SECRET", STRIPE_WEBHOOK_SECRET),
              ("STRIPE_PRICE_MONTHLY", STRIPE_PRICES["monthly"]),
              ("STRIPE_PRICE_SEASON", STRIPE_PRICES["season"]))
    return [name for name, val in checks if not val]


def billing_configured():
    return not billing_missing()


def trial_open():
    return billing_configured() and bool(STRIPE_PRICES["trial"]) and bool(STRIPE_PRICES["monthly"])


def trial_eligible(user):
    """First-time members only: a guest, or an account that has never
    held a plan or a subscription. One trial per customer is also what
    Stripe enforces on the customer record; this keeps the button honest."""
    if user is None or not getattr(user, "is_authenticated", True):
        return True
    if getattr(user, "is_member", False):
        return False
    if getattr(user, "stripe_subscription_id", None):
        return False
    return (getattr(user, "plan", "none") or "none") == "none" and not (getattr(user, "member_status", "") or "")


if billing_missing():
    app.logger.warning("StreakPros+ checkout is not open on this server: set %s in the environment",
                       ", ".join(billing_missing()))


def _stripe():
    """The client, keyed and pinned. Set on every call rather than once
    at import so a test can swap the key and so a key added later takes
    effect on the next request."""
    stripe.api_key = STRIPE_SECRET_KEY
    stripe.api_version = STRIPE_API_VERSION
    return stripe


def founding_window_open(today=None):
    """The launch price is on sale through FOUNDING_CUTOFF, Central time,
    and only while a founding price exists to sell."""
    if not STRIPE_PRICES["founding"]:
        return False
    try:
        cutoff = date.fromisoformat(FOUNDING_CUTOFF)
    except ValueError:
        return False
    today = today or datetime.now(CENTRAL_TZ).date()
    return today <= cutoff


def founding_cutoff_label():
    try:
        return date.fromisoformat(FOUNDING_CUTOFF).strftime("%B %-d")
    except ValueError:
        return ""


def season_pass_end(when=None):
    """When a pass bought at `when` stops: Feb 28, 23:59:59 Central, of
    the year this season ends in. Returned as naive UTC, which is how
    the users table keeps every other timestamp."""
    when = when or datetime.now(timezone.utc)
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    local = when.astimezone(CENTRAL_TZ)
    year = local.year + 1 if local.month >= 3 else local.year
    month, day = SEASON_PASS_END_MONTH_DAY
    end_local = datetime(year, month, day, 23, 59, 59, tzinfo=CENTRAL_TZ)
    return end_local.astimezone(timezone.utc).replace(tzinfo=None)


def has_mycalc_plus(row, now=None):
    """The one access check, on a users row. Everything that gates a page
    goes through here, so there is exactly one place the rules live."""
    if not row:
        return False
    if row.get("is_member"):
        return True  # set by hand in the database: a complimentary account
    plan = row.get("plan") or "none"
    now = now or datetime.utcnow()
    if plan == "monthly":
        return (row.get("member_status") or "") in MEMBER_STATUSES_WITH_ACCESS
    if plan in ("season", "founding"):
        until = row.get("access_until")
        return until is not None and now < until
    return False


def viewer_has_plus():
    return bool(current_user.is_authenticated and getattr(current_user, "is_member", False))


def plus_unlocked(open_before=False):
    """Whether the viewer gets a StreakPros+ page in full. With the gate off,
    a page keeps whatever it asked for before billing existed: sign-in
    (Rankings, Matchups, League Manager) or nothing at all (Streaks,
    open_before=True). With it on, the plan is the key."""
    if PAYWALL:
        return viewer_has_plus()
    return open_before or bool(current_user.is_authenticated)


def gate_kind():
    """Which card covers a locked page: a guest is asked to sign up, a
    free account is asked for the plan."""
    return "plus" if current_user.is_authenticated else "signup"


def _central_date(dt):
    """A stored naive-UTC timestamp, as the date a reader in the US would
    call it."""
    if not dt:
        return ""
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(CENTRAL_TZ).strftime("%-d %b %Y")


def plan_summary(user, now=None):
    """What to tell the account holder about their plan."""
    now = now or datetime.utcnow()
    plan = getattr(user, "plan", None) or "none"
    status = getattr(user, "member_status", None) or ""
    until = getattr(user, "access_until", None)
    period_end = getattr(user, "current_period_end", None)
    out = {"plan": plan, "active": bool(getattr(user, "is_member", False)), "label": "Free",
           "detail": "", "status": status, "manage": False, "past_due": False,
           "founding": bool(getattr(user, "founding_member", False)),
           "comped": bool(getattr(user, "comped", False)),
           "has_customer": bool(getattr(user, "stripe_customer_id", None))}
    if plan == "monthly":
        out["manage"] = out["has_customer"]
        if status in MEMBER_STATUSES_WITH_ACCESS:
            out["label"] = PLAN_NAMES["monthly"]
            if getattr(user, "cancel_at_period_end", False):
                out["detail"] = f"Ends {_central_date(period_end)}" if period_end else "Ends at the end of this period"
            elif status == "past_due":
                out["detail"] = "Last payment failed"
                out["past_due"] = True
            else:
                out["detail"] = f"Renews {_central_date(period_end)}" if period_end else "Active"
        else:
            out["detail"] = "Monthly plan ended"
    elif plan in ("season", "founding"):
        if until and now < until:
            out["label"] = PLAN_NAMES["season"] + (" (Founding)" if plan == "founding" else "")
            out["detail"] = f"Through {_central_date(until)}"
        else:
            out["detail"] = f"Season Pass ended {_central_date(until)}" if until else "Season Pass ended"
    if out["comped"] and out["label"] == "Free":
        out["label"] = "StreakPros+"
        out["detail"] = "Complimentary"
    return out


def _plain(obj):
    """A Stripe object as a plain dict. The library's objects stopped
    being dicts in v15; everything below reads with .get, so the
    conversion happens once, at the boundary."""
    if hasattr(obj, "to_dict") and not isinstance(obj, dict):
        obj = obj.to_dict()
    if isinstance(obj, dict):
        return {k: _plain(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_plain(v) for v in obj]
    return obj


def _obj_id(value):
    """Stripe sends related objects as an id, or expanded as the object.
    Either way, the id."""
    if isinstance(value, dict):
        return value.get("id")
    return value or None


def _period_end(sub):
    """current_period_end lives on the subscription in older API versions
    and on its items in newer ones."""
    if not isinstance(sub, dict):
        return None
    ts = sub.get("current_period_end")
    if not ts:
        items = ((sub.get("items") or {}).get("data") or [])
        ts = items[0].get("current_period_end") if items else None
    return datetime.utcfromtimestamp(int(ts)) if ts else None


def _session_user_id(sess):
    meta = sess.get("metadata") or {}
    raw = meta.get("app_user_id") or sess.get("client_reference_id")
    try:
        return int(raw)
    except (TypeError, ValueError):
        return None


def _users_set(cur, user_id, **fields):
    """UPDATE users SET ... for the billing columns. Column names come
    from this file, never from a request."""
    cols = ", ".join(f"{k} = %s" for k in fields)
    cur.execute(f"UPDATE users SET {cols}, plan_updated_at = NOW() WHERE id = %s",
                (*fields.values(), user_id))


def _claim(cur, key):
    """True the first time a key is seen. Webhook event ids and Checkout
    session ids both go through here, so a redelivered event or a success
    page that raced the webhook changes nothing the second time."""
    cur.execute("INSERT INTO processed_stripe_events (event_id) VALUES (%s) ON CONFLICT DO NOTHING", (key,))
    return cur.rowcount == 1


def _session_email(sess):
    details = sess.get("customer_details") or {}
    email = details.get("email") or sess.get("customer_email") or ""
    email = email.strip().lower()
    return email if "@" in email else ""


def _account_for_email(cur, email):
    """(user_id, created). The account already using this email, or a
    new one named from it: no password yet, that comes from the link in
    the welcome email."""
    cur.execute("SELECT id FROM users WHERE lower(email) = lower(%s)", (email,))
    row = cur.fetchone()
    if row:
        return row["id"], False
    base = re.sub(r"[^A-Za-z0-9_]", "", email.split("@")[0])[:15] or "user"
    username, suffix = base, 1
    while not username_available(username):
        suffix += 1
        username = f"{base}{suffix}"
    cur.execute("INSERT INTO users (email, username) VALUES (%s, %s) RETURNING id", (email, username))
    return cur.fetchone()["id"], True


def _welcome_later(user_id):
    """After the account's row is committed: a set-your-password link,
    by email. Not before -- the token row points at the account."""
    def _run():
        try:
            row = None
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT * FROM users WHERE id = %s", (user_id,))
                    row = cur.fetchone()
            finally:
                conn.close()
            if row and row.get("email"):
                send_welcome_email(row, create_password_reset(user_id))
        except Exception:
            app.logger.exception("welcome email for user %s failed", user_id)
    return _run


def send_welcome_email(row, token):
    link = f"{SITE_URL}/reset-password?token={token}"
    name = row.get("username") or "there"
    text = (
        f"Hi {name},\n\n"
        f"Thanks for joining StreakPros+. Your StreakPros account was made "
        f"from this email address when you paid. Choose a password here so you can "
        f"sign in on any device:\n\n{link}\n\n"
        f"The link works once and expires in {PASSWORD_RESET_TTL_HOURS} hours; you can "
        f"ask for another from the sign-in page any time.\n\n"
        f"Your username is {name}. Manage your plan under Settings > StreakPros+.\n"
    )
    body = (
        f'<p>Hi {html.escape(str(name))},</p>'
        f'<p>Thanks for joining StreakPros+. Your StreakPros account was made from '
        f'this email address when you paid. Choose a password so you can sign in on any device:</p>'
        f'<p><a href="{link}" style="background:#b97a1f;color:#fff8ec;padding:11px 22px;'
        f'border-radius:99px;text-decoration:none;font-weight:700;display:inline-block;">'
        f'Set your password</a></p>'
        f'<p style="color:#666;font-size:13px;">The link works once and expires in '
        f'{PASSWORD_RESET_TTL_HOURS} hours; you can ask for another from the sign-in page any time. '
        f'Your username is <b>{html.escape(str(name))}</b>. Manage your plan under Settings &rsaquo; StreakPros+.</p>'
    )
    return send_email(row["email"], "Welcome to StreakPros+: set your password", text, body)


def _grant_from_session(cur, sess):
    """Give an account what its completed Checkout session bought.
    Returns {"result", "user_id", "created", "after"}: `after` is work
    for once the row is committed (a welcome email), or None."""
    out = {"result": "", "user_id": None, "created": False, "after": None}
    user_id = _session_user_id(sess)
    if not user_id and (sess.get("metadata") or {}).get("guest") == "1":
        email = _session_email(sess)
        if not email:
            out["result"] = "no-email"
            return out
        if not _claim(cur, "cs:" + str(sess.get("id"))):
            out["result"] = "already"
            return out
        user_id, created = _account_for_email(cur, email)
        out["created"] = created
        if created:
            out["after"] = _welcome_later(user_id)
    elif not user_id:
        out["result"] = "no-user"
        return out
    elif not _claim(cur, "cs:" + str(sess.get("id"))):
        out["result"] = "already"
        return out
    out["user_id"] = user_id
    customer = _obj_id(sess.get("customer"))
    if customer:
        cur.execute("UPDATE users SET stripe_customer_id = COALESCE(stripe_customer_id, %s) WHERE id = %s",
                    (customer, user_id))
    meta = sess.get("metadata") or {}
    if sess.get("mode") == "subscription":
        sub = sess.get("subscription")
        sub_id = _obj_id(sub)
        period_end = _period_end(sub) if isinstance(sub, dict) else None
        if sub_id and period_end is None and STRIPE_SECRET_KEY:
            try:
                period_end = _period_end(_plain(_stripe().Subscription.retrieve(sub_id)))
            except Exception:
                period_end = None
        status = "trialing" if meta.get("trial") == "1" else "active"
        _users_set(cur, user_id, plan="monthly", member_status=status, stripe_subscription_id=sub_id,
                   cancel_at_period_end=False, current_period_end=period_end)
        out["result"] = "granted"
        return out
    if sess.get("payment_status") not in ("paid", "no_payment_required"):
        out["result"] = "unpaid"
        return out
    plan = meta.get("plan") if meta.get("plan") in ("season", "founding") else "season"
    fields = dict(plan=plan, member_status="active", access_until=season_pass_end(),
                  stripe_subscription_id=None, cancel_at_period_end=False, current_period_end=None)
    if plan == "founding":
        fields["founding_member"] = True
    _users_set(cur, user_id, **fields)
    out["result"] = "granted"
    return out


def apply_checkout_session(sess):
    """The success page's path to the same grant the webhook makes."""
    if not DATABASE_URL:
        return {"result": "no-database", "user_id": None, "created": False, "after": None}
    conn = get_db()
    try:
        with conn.cursor() as cur:
            out = _grant_from_session(cur, sess)
        conn.commit()
    finally:
        conn.close()
    if callable(out.get("after")):
        threading.Thread(target=out["after"], daemon=True).start()
    return out


def _find_user_for_subscription(cur, sub):
    meta = sub.get("metadata") or {}
    try:
        if meta.get("app_user_id"):
            return int(meta["app_user_id"])
    except (TypeError, ValueError):
        pass
    if sub.get("id"):
        cur.execute("SELECT id FROM users WHERE stripe_subscription_id = %s", (sub["id"],))
        row = cur.fetchone()
        if row:
            return row["id"]
    customer = _obj_id(sub.get("customer"))
    if customer:
        cur.execute("SELECT id FROM users WHERE stripe_customer_id = %s", (customer,))
        row = cur.fetchone()
        if row:
            return row["id"]
    return None


def _on_checkout_completed(cur, sess):
    return _grant_from_session(cur, sess).get("after")


def _on_subscription_updated(cur, sub):
    user_id = _find_user_for_subscription(cur, sub)
    if not user_id:
        return
    fields = dict(member_status=sub.get("status") or "", stripe_subscription_id=sub.get("id"),
                  cancel_at_period_end=bool(sub.get("cancel_at_period_end")),
                  current_period_end=_period_end(sub))
    # A subscription never overrides a season pass that is still running;
    # it takes over the moment the pass ends.
    cur.execute("SELECT plan, access_until FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone() or {}
    pass_live = (row.get("plan") in ("season", "founding") and row.get("access_until")
                 and datetime.utcnow() < row["access_until"])
    if not pass_live:
        fields["plan"] = "monthly"
    _users_set(cur, user_id, **fields)


def _on_subscription_deleted(cur, sub):
    user_id = _find_user_for_subscription(cur, sub)
    if not user_id:
        return
    _users_set(cur, user_id, member_status="canceled", cancel_at_period_end=False,
               current_period_end=_period_end(sub))


def _on_payment_failed(cur, inv):
    """Mark the account past due and tell the person; access stays until
    Stripe gives up on the card and deletes the subscription."""
    sub_id = _obj_id(inv.get("subscription"))
    if not sub_id:
        sub_id = ((inv.get("parent") or {}).get("subscription_details") or {}).get("subscription")
    probe = {"id": sub_id, "customer": inv.get("customer"), "metadata": {}}
    user_id = _find_user_for_subscription(cur, probe)
    if not user_id:
        return None
    cur.execute("SELECT email, username, plan FROM users WHERE id = %s", (user_id,))
    row = cur.fetchone() or {}
    if row.get("plan") != "monthly":
        return None
    _users_set(cur, user_id, member_status="past_due")
    to, name = row.get("email"), row.get("username") or "there"
    if not to:
        return None
    link = SITE_URL + "/settings/plan"
    text = (f"Hi {name},\n\nYour StreakPros+ payment didn't go through. Stripe will retry the card "
            f"over the next few days, and your access continues in the meantime.\n\n"
            f"To update your card now: {link}\n\nIf you meant to cancel, there is nothing to do.\n")

    def _later():
        send_email(to, "Your StreakPros+ payment didn't go through", text)
    return _later


STRIPE_HANDLERS = {
    "checkout.session.completed": _on_checkout_completed,
    "customer.subscription.updated": _on_subscription_updated,
    "customer.subscription.deleted": _on_subscription_deleted,
    "invoice.payment_failed": _on_payment_failed,
}


def handle_stripe_event(event):
    """One verified event, applied once. The event id is claimed inside
    the same transaction as the change, so a handler that fails leaves
    no claim behind and Stripe's retry gets a clean run."""
    etype = event.get("type") or ""
    handler = STRIPE_HANDLERS.get(etype)
    if not handler:
        return "ignored"
    if not DATABASE_URL:
        return "no-database"
    obj = (event.get("data") or {}).get("object") or {}
    after = None
    conn = get_db()
    try:
        with conn.cursor() as cur:
            if not _claim(cur, str(event.get("id"))):
                return "duplicate"
            after = handler(cur, obj)
        conn.commit()
    finally:
        conn.close()
    if callable(after):
        threading.Thread(target=after, daemon=True).start()
    return "handled"


@app.route("/api/stripe-webhook", methods=["POST"])
def stripe_webhook():
    """Stripe's events, verified against the signing secret on the raw
    body. Any 2xx tells Stripe it landed; anything else is retried."""
    if not STRIPE_WEBHOOK_SECRET:
        return jsonify({"ok": False, "error": "STRIPE_WEBHOOK_SECRET is not set"}), 503
    payload = request.get_data()
    sig = request.headers.get("Stripe-Signature", "")
    try:
        event = stripe.Webhook.construct_event(payload, sig, STRIPE_WEBHOOK_SECRET)
    except (ValueError, stripe.SignatureVerificationError):
        return jsonify({"ok": False, "error": "bad signature"}), 400
    result = handle_stripe_event(_plain(event))
    return jsonify({"ok": True, "result": result})


def get_or_create_stripe_customer(user):
    """Exactly one Stripe customer per account, made before Checkout so
    the portal has someone to show."""
    if getattr(user, "stripe_customer_id", None):
        return user.stripe_customer_id
    customer = _stripe().Customer.create(email=user.email or None, name=user.username,
                                         metadata={"app_user_id": str(user.id)})
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("UPDATE users SET stripe_customer_id = COALESCE(stripe_customer_id, %s) WHERE id = %s",
                        (customer["id"], user.id))
        conn.commit()
    finally:
        conn.close()
    user.stripe_customer_id = customer["id"]
    return customer["id"]


def checkout_params(user, plan, customer_id):
    """The Checkout session, as Stripe wants it. Pure, so a test can read
    it without a network. `user` is None for a guest: Stripe collects the
    email, and the account is made from it once the payment lands."""
    trial = plan == "trial"
    bought = "monthly" if trial else plan   # what the account ends up on
    if user is None:
        who = {"plan": bought, "guest": "1"}
    else:
        who = {"app_user_id": str(user.id), "plan": bought}
    if trial:
        who["trial"] = "1"
    # The trial is the monthly subscription with TRIAL_DAYS free, plus
    # the $1 one-time price on the first invoice: $1 today, the monthly
    # price when the trial ends.
    line_items = ([{"price": STRIPE_PRICES["monthly"], "quantity": 1}, {"price": STRIPE_PRICES["trial"], "quantity": 1}]
                  if trial else [{"price": STRIPE_PRICES[plan], "quantity": 1}])
    params = dict(
        mode=PLAN_MODES[plan],
        line_items=line_items,
        metadata=who,
        success_url=SITE_URL + "/billing/success?session_id={CHECKOUT_SESSION_ID}",
        cancel_url=SITE_URL + "/plus",
        allow_promotion_codes=True,
        # Not the merchant-of-record product. Stripe's newer API versions
        # switch Managed Payments on by default, and a session on a
        # product without an eligible tax code is refused outright.
        managed_payments={"enabled": False},
    )
    if user is None:
        # A one-time payment does not make a Customer on its own; the
        # portal and the receipt email both need one.
        if PLAN_MODES[plan] == "payment":
            params["customer_creation"] = "always"
    else:
        params["customer"] = customer_id
        params["client_reference_id"] = str(user.id)
    if PLAN_MODES[plan] == "subscription":
        params["subscription_data"] = {"metadata": who}
        # A 100%-off code (the owner's own test code, a friend's) needs
        # no card at all; Stripe only asks for one if there is a charge.
        params["payment_method_collection"] = "if_required"
        if trial:
            params["subscription_data"]["trial_period_days"] = TRIAL_DAYS
            # The card that pays the $1 is the card that renews; a
            # trial that somehow lost it ends rather than lingering.
            params["subscription_data"]["trial_settings"] = {"end_behavior": {"missing_payment_method": "cancel"}}
            params["payment_method_collection"] = "always"
    else:
        params["payment_intent_data"] = {"metadata": who}
    return params


@app.route("/billing/checkout/<plan>", methods=["POST"])
def billing_checkout(plan):
    """Signed in or not. A guest pays first and gets an account from the
    email on the receipt; nobody has to make one to buy."""
    if plan not in PLAN_MODES:
        return redirect("/plus")
    if plan == "founding" and not founding_window_open():
        return redirect("/plus?notice=founding-closed")
    if not billing_configured() or not STRIPE_PRICES[plan]:
        return redirect("/plus?notice=not-open")
    if viewer_has_plus():
        return redirect("/plus?notice=already")
    if plan == "trial" and not (trial_open() and trial_eligible(current_user if current_user.is_authenticated else None)):
        return redirect("/plus?notice=trial-used")
    try:
        if current_user.is_authenticated:
            customer_id = get_or_create_stripe_customer(current_user)
            sess = _stripe().checkout.Session.create(**checkout_params(current_user, plan, customer_id))
        else:
            sess = _stripe().checkout.Session.create(**checkout_params(None, plan, None))
    except Exception:
        app.logger.exception("Stripe checkout could not be started")
        return redirect("/plus?notice=error")
    return redirect(sess["url"], code=303)


@app.route("/billing/success")
def billing_success():
    """Thank-you page. Applies the grant from the retrieved session too,
    verified server-side with the secret key, so the page can say "you're
    in" without waiting on the webhook.

    Signed in: the session must belong to this account; an id pasted from
    someone else's URL grants nothing. A guest: the account is the one
    made from the receipt email, and the page signs them into it -- but
    only an account this purchase created (no password, no Google
    sign-in). Paying with someone else's email never opens their
    existing account; it just gives it the plan."""
    sid = (request.args.get("session_id") or "").strip()
    result = None
    guest_state = None   # "new" / "existing" / None
    trial_started = False
    if current_user.is_authenticated:
        if sid and billing_configured():
            try:
                sess = _plain(_stripe().checkout.Session.retrieve(sid, expand=["subscription"]))
                if _session_user_id(sess) == int(current_user.id) and sess.get("status") == "complete":
                    result = apply_checkout_session(sess)
                    trial_started = (sess.get("metadata") or {}).get("trial") == "1"
            except Exception:
                app.logger.exception("could not confirm checkout session")
        fresh = load_user(current_user.id) if DATABASE_URL else None
        summary = plan_summary(fresh or current_user)
        return render_template_string(BILLING_SUCCESS_HTML, summary=summary, result=result, guest=None,
                                      trial=trial_started, trial_days=TRIAL_DAYS, monthly_price=PLAN_PRICES["monthly"])
    if not sid or not billing_configured() or not DATABASE_URL:
        return redirect("/plus")
    try:
        sess = _plain(_stripe().checkout.Session.retrieve(sid, expand=["subscription"]))
    except Exception:
        app.logger.exception("could not confirm checkout session")
        return redirect("/plus?notice=error")
    meta = sess.get("metadata") or {}
    email = _session_email(sess)
    if meta.get("guest") != "1" or sess.get("status") != "complete" or not email:
        return redirect("/plus")
    result = apply_checkout_session(sess)
    row = user_by_email(email)
    if not row:
        return redirect("/plus?notice=error")
    fresh_account = not row.get("password_hash") and not row.get("oauth_provider")
    if fresh_account:
        login_user(User(row), remember=True)
        guest_state = "new"
    else:
        guest_state = "existing"
    return render_template_string(BILLING_SUCCESS_HTML, summary=plan_summary(User(row)),
                                  result=result, guest=guest_state, email=email,
                                  trial=(meta.get("trial") == "1"), trial_days=TRIAL_DAYS, monthly_price=PLAN_PRICES["monthly"])


@app.route("/billing/portal", methods=["POST"])
@login_required
def billing_portal():
    """Stripe's own page for cancelling, changing the card and reading
    invoices. The portal's rules are set in the Dashboard, not here."""
    customer_id = getattr(current_user, "stripe_customer_id", None)
    if not customer_id or not billing_configured():
        return redirect("/plus")
    try:
        sess = _stripe().billing_portal.Session.create(customer=customer_id,
                                                       return_url=SITE_URL + "/settings/plan")
    except Exception:
        app.logger.exception("Stripe portal could not be opened")
        return redirect("/settings/plan?error=portal")
    return redirect(sess["url"], code=303)


