@app.route("/api/billing-status")
def api_billing_status():
    """Is billing wired? Which variables are present (never their values),
    the gate switch, the founding window, and how many accounts are on
    each plan."""
    if not _secret_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    out = {"ok": True, "configured": billing_configured(), "missing": billing_missing(),
           "paywall": PAYWALL, "founding_open": founding_window_open(), "founding_cutoff": FOUNDING_CUTOFF,
           "api_version": STRIPE_API_VERSION, "site_url": SITE_URL,
           "prices": {k: bool(v) for k, v in STRIPE_PRICES.items()},
           "plans": {}, "events_processed": 0, "last_event_at": None}
    if DATABASE_URL:
        try:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute("SELECT COALESCE(plan, 'none') AS plan, COALESCE(member_status, '') AS status, "
                                "COUNT(*) AS n FROM users GROUP BY 1, 2")
                    for r in cur.fetchall():
                        out["plans"][f"{r['plan']}:{r['status']}"] = r["n"]
                    cur.execute("SELECT COUNT(*) AS n, MAX(processed_at) AS newest FROM processed_stripe_events")
                    r = cur.fetchone() or {}
                    out["events_processed"] = r.get("n") or 0
                    out["last_event_at"] = str(r["newest"]) if r.get("newest") else None
            finally:
                conn.close()
        except Exception as e:
            out["db_error"] = str(e)
    return jsonify(out)



def _plan_summary_line(user):
    s = plan_summary(user)
    return s["label"] + (" \u00b7 " + s["detail"] if s["detail"] else "")


def _safe_next():
    """A ?next= that stays on this site: a path, never a URL."""
    nxt = request.args.get("next") or ""
    if not nxt.startswith("/") or nxt.startswith("//"):
        return ""
    # The checkout routes only take a POST; a login that was bounced off
    # one lands on the pricing page instead of a 405.
    return "/plus" if nxt.startswith("/billing/") else nxt


SETTINGS_SECTIONS = [
    ("profile", "Profile"),
    ("rankings", "Rankings"),
    ("scoring", "Scoring"),
    ("theme", "Theme"),
    ("leagues", "Leagues"),
    ("plan", "StreakPros+"),
    ("alerts", "Alerts"),
    ("email", "Email"),
    ("account", "Account"),
]
_SECTION_LABELS = dict(SETTINGS_SECTIONS)


def settings_summaries(league_count):
    """What each row on the index says it is currently set to.

    The common reason to open Settings is to check something rather than
    change it, and a row that answers the question without being opened
    saves the trip."""
    fmt = "Superflex" if current_user.pref_format == "superflex" else "1QB"
    mode = "Redraft" if current_user.pref_mode == "redraft" else "Dynasty"
    theme = _label_for(THEMES, getattr(current_user, "pref_theme", None))
    accent = _label_for(ACCENTS, getattr(current_user, "pref_accent", None))
    return {
        "profile": "Picture, username and password",
        "rankings": f"{fmt} \u00b7 {mode}",
        "scoring": scoring_label(normalize_scoring(current_user.pref_scoring)),
        "theme": f"{theme} \u00b7 {accent}",
        "leagues": ("No leagues synced yet" if not league_count
                    else f"{league_count} league{'s' if league_count != 1 else ''} synced"),
        "plan": _plan_summary_line(current_user),
        "alerts": _alerts_summary_line(current_user),
        "email": ("Updates on" if current_user.newsletter_opt_in else "Updates off"),
        "account": current_user.email or "Signed in",
    }


def _alerts_summary_line(user):
    """What the Alerts row says without being opened."""
    # getattr with a default, like every other preference read on this
    # screen: a user object is not always the full row (a fake one in a
    # test, a stale session), and a settings page that raises over a
    # missing checkbox is a 500 where a default would do.
    if not getattr(user, "newsletter_opt_in", True):
        return "Off \u2014 you are unsubscribed"
    on = [label for label, want in (("Lineup", getattr(user, "alert_lineup", True)),
                                    ("Waivers", getattr(user, "alert_waivers", True))) if want]
    return " \u00b7 ".join(on) if on else "Both off"


def _label_for(pairs, key):
    for k, label in pairs:
        if k == key:
            return label
    return pairs[0][1]


@app.route("/settings", methods=["GET", "POST"])
@app.route("/settings/<section>", methods=["GET", "POST"])
@login_required
def settings_page(section=None):
    """Everything about an account that was previously either fixed at
    signup or hidden inside another page.

    The Sleeper username lived only in League Manager, the newsletter
    choice was set once at signup and never again, and the rankings
    format and mode existed only as URL parameters -- so every visit
    began on 1QB dynasty no matter what league you actually play in."""
    # An unknown section is the index, not a 404: a stale bookmark or a
    # typed URL should land somewhere useful rather than on an error.
    if section is not None and section not in _SECTION_LABELS:
        return redirect("/settings")
    back = f"/settings/{section}" if section else "/settings"

    saved = request.args.get("saved") == "1"
    error = None
    if request.method == "POST":
        # Removing a picture is its own button, and nothing else on the
        # form should be touched by it.
        if request.form.get("action") == "remove_avatar":
            try:
                current_user.avatar_version = delete_avatar(current_user.id)
                return redirect(back + "?saved=1")
            except Exception as e:
                error = str(e)

        # Changing the username, and changing the password while signed
        # in, are their own submits: each has its own rules and its own
        # way of failing, and neither should ride along with the rest.
        if request.form.get("action") == "change_username":
            wanted = (request.form.get("new_username") or "").strip()
            blocked_until = username_change_allowed_at(current_user.username_changed_at)
            if blocked_until:
                error = "You can change your username again on %s." % blocked_until.strftime("%-d %B %Y")
            elif wanted.lower() == (current_user.username or "").lower():
                error = "That's already your username."
            elif not username_valid(wanted):
                error = "Username must be 1-20 letters, numbers, or underscores."
            elif not username_available(wanted):
                error = "That username is taken."
            else:
                try:
                    conn = get_db()
                    try:
                        with conn.cursor() as cur:
                            cur.execute(
                                "UPDATE users SET username = %s, username_changed_at = NOW() "
                                "WHERE id = %s RETURNING username_changed_at",
                                (wanted, current_user.id))
                            row = cur.fetchone()
                        conn.commit()
                    finally:
                        conn.close()
                    current_user.username = wanted
                    current_user.username_changed_at = (row or {}).get("username_changed_at")
                    return redirect(back + "?saved=1")
                except Exception as e:
                    error = str(e)

        if not error and request.form.get("action") == "change_password":
            current = request.form.get("current_password") or ""
            new = request.form.get("new_password") or ""
            confirm = request.form.get("confirm_password") or ""
            stored = None
            try:
                conn = get_db()
                try:
                    with conn.cursor() as cur:
                        cur.execute("SELECT password_hash FROM users WHERE id = %s",
                                    (current_user.id,))
                        stored = (cur.fetchone() or {}).get("password_hash")
                finally:
                    conn.close()
            except Exception as e:
                error = str(e)
            if not error:
                if len(new) < MIN_PASSWORD_LENGTH:
                    error = "Password must be at least %d characters." % MIN_PASSWORD_LENGTH
                elif new != confirm:
                    error = "Those two passwords don't match."
                elif stored and not check_password_hash(stored, current):
                    error = "That current password isn't right."
                else:
                    try:
                        conn = get_db()
                        try:
                            with conn.cursor() as cur:
                                cur.execute("UPDATE users SET password_hash = %s WHERE id = %s",
                                            (generate_password_hash(new), current_user.id))
                            conn.commit()
                        finally:
                            conn.close()
                        return redirect(back + "?saved=1")
                    except Exception as e:
                        error = str(e)

        upload = request.files.get("avatar")
        if not error and upload and upload.filename:
            data = upload.read(AVATAR_MAX_BYTES + 1)
            if len(data) > AVATAR_MAX_BYTES:
                error = "That picture is over %d MB, which is larger than any phone takes." % (
                    AVATAR_MAX_BYTES // (1024 * 1024))
            else:
                # The bytes decide what it is. A .png that is really
                # something else is not a picture, whatever it is called.
                mimetype = sniff_image(data)
                if not mimetype:
                    error = "That file doesn't look like an image."
                else:
                    try:
                        current_user.avatar_version = save_avatar(
                            current_user.id, data, mimetype)
                    except Exception as e:
                        error = str(e)

        # Only what this form actually submitted.
        #
        # This block used to read all five preferences off every POST and
        # write all five back. That was survivable while they shared one
        # page and one Save, and became a data-loss bug the moment each
        # got its own screen: the Scoring form posts no pref_format, so
        # .get() returned None, the guard below turned None into "1qb",
        # and saving your scoring format quietly reset a superflex reader
        # to 1QB. A field absent from the form is a field the reader did
        # not touch, so it is left alone.
        updates = {}
        if "sleeper_username" in request.form:
            sleeper = (request.form.get("sleeper_username") or "").strip()
            if len(sleeper) > 64:
                error = "That Sleeper username is too long."
            else:
                updates["sleeper_username"] = sleeper or None
        if "pref_format" in request.form:
            fmt = request.form.get("pref_format")
            updates["pref_format"] = fmt if fmt in ("1qb", "superflex") else "1qb"
        if "pref_mode" in request.form:
            mode = request.form.get("pref_mode")
            updates["pref_mode"] = mode if mode in ("dynasty", "redraft") else "dynasty"
        if "pref_scoring" in request.form:
            updates["pref_scoring"] = normalize_scoring(request.form.get("pref_scoring"))
        # An unticked checkbox submits nothing at all, so it cannot be
        # detected by presence. The form carries a hidden marker to say
        # "this screen owns the newsletter setting", and the checkbox
        # itself then means ticked or not.
        if "newsletter_present" in request.form:
            updates["newsletter_opt_in"] = bool(request.form.get("newsletter_opt_in"))
        # Same marker trick as the newsletter box, for the same reason:
        # an unticked checkbox submits nothing, so the screen has to say
        # it owns the setting.
        if "alerts_present" in request.form:
            updates["alert_lineup"] = bool(request.form.get("alert_lineup"))
            updates["alert_waivers"] = bool(request.form.get("alert_waivers"))

        if updates and not error:
            try:
                assigns = ", ".join(f"{col} = %s" for col in updates)
                conn = get_db()
                try:
                    with conn.cursor() as cur:
                        cur.execute(f"UPDATE users SET {assigns} WHERE id = %s",
                                    (*updates.values(), current_user.id))
                    conn.commit()
                finally:
                    conn.close()
                # Keep the object backing this request in step, so the page
                # that renders next shows what was just saved rather than
                # what it was loaded with.
                for col, value in updates.items():
                    setattr(current_user, col, value)
                return redirect(back + "?saved=1")
            except Exception as e:
                error = str(e)

    leagues = get_synced_league_ids(current_user.id)
    league_count = len(leagues) if leagues else 0
    summaries = settings_summaries(league_count)
    return render_template_string(
        SETTINGS_HTML, saved=saved, error=error, scoring_formats=SCORING_FORMATS,
        themes=THEMES, accents=ACCENTS,
        section=section, section_label=_SECTION_LABELS.get(section, "Settings"),
        sections=[(key, label, summaries.get(key, ""))
                  for key, label in SETTINGS_SECTIONS],
        username_next_change=username_change_allowed_at(current_user.username_changed_at),
        username_cooldown_days=USERNAME_CHANGE_DAYS,
        league_count=league_count, plan=plan_summary(current_user))


def export_account_data(user_id):
    """Everything this account is, as plain data.

    The password hash is deliberately absent: it is the one field whose
    export would only ever help someone attacking the account offline,
    and "your data" does not mean "the thing that protects your data"."""
    out = {
        "exported_at": datetime.utcnow().isoformat() + "Z",
        "account": {}, "synced_leagues": [], "votes": [], "alerts_sent": [], "avatar": None,
    }
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "SELECT id, email, username, oauth_provider, referral_code, "
                "newsletter_opt_in, is_member, created_at, username_changed_at, "
                "pref_format, pref_mode, pref_scoring, pref_theme, pref_accent, "
                "alert_lineup, alert_waivers "
                "FROM users WHERE id = %s", (user_id,))
            row = cur.fetchone() or {}
            out["account"] = {k: (v.isoformat() if hasattr(v, "isoformat") else v)
                              for k, v in dict(row).items()}
            cur.execute("SELECT league_id FROM synced_leagues WHERE user_id = %s",
                        (user_id,))
            out["synced_leagues"] = [r["league_id"] for r in cur.fetchall()]
            cur.execute("SELECT kind, sent_at FROM sent_alerts WHERE user_id = %s "
                        "ORDER BY sent_at", (user_id,))
            out["alerts_sent"] = [{"kind": r["kind"],
                                   "sent_at": r["sent_at"].isoformat() if r["sent_at"] else None}
                                  for r in cur.fetchall()]
            cur.execute("SELECT sleeper_id, player_name, position, label, created_at "
                        "FROM votes WHERE user_id = %s ORDER BY created_at", (user_id,))
            out["votes"] = [
                {**{k: v for k, v in dict(r).items() if k != "created_at"},
                 "created_at": r["created_at"].isoformat() if r.get("created_at") else None}
                for r in cur.fetchall()]
            cur.execute("SELECT mimetype, length(image) AS bytes FROM user_avatars "
                        "WHERE user_id = %s", (user_id,))
            av = cur.fetchone()
            if av:
                # The bytes themselves are downloadable at /avatar/<id>;
                # inlining a megabyte of base64 helps nobody read this.
                out["avatar"] = {"mimetype": av.get("mimetype"),
                                 "bytes": av.get("bytes"),
                                 "download": f"{SITE_URL}/avatar/{user_id}"}
    finally:
        conn.close()
    return out


def delete_account(user_id):
    """Erase the account, for real.

    Everything that identifies the person goes: the row itself, the
    avatar, the synced league list, any live password-reset tokens.

    Start/Bench/Cut votes are kept but unlinked -- their user_id is set
    to NULL. The vote is what the community rankings are built from, and
    once it points at nobody it is no longer personal data; deleting it
    instead would quietly degrade everyone else's rankings to no benefit
    for the person leaving. This is the one thing that survives, which is
    why the confirmation screen says so in as many words.

    All of it in one transaction: a half-deleted account -- avatar gone,
    login still working -- is worse than either outcome."""
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("UPDATE votes SET user_id = NULL WHERE user_id = %s", (user_id,))
            anonymized = cur.rowcount
            cur.execute("DELETE FROM password_resets WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM synced_leagues WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM user_avatars WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM draft_entries WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM sent_alerts WHERE user_id = %s", (user_id,))
            cur.execute("DELETE FROM users WHERE id = %s", (user_id,))
            removed = cur.rowcount
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return {"deleted": bool(removed), "votes_anonymized": anonymized}


@app.route("/api/theme", methods=["POST"])
def api_theme():
    """Save a theme choice.

    Its own endpoint rather than a field on the Settings form, because a
    theme is the one setting whose result you judge by looking at it --
    picking one has to change the page under your hands, not after a
    save and a reload. The page applies the change itself and posts here
    so it survives to the next visit and to another device.

    A guest is answered normally and simply has nothing saved: the
    browser is the only place their choice can live, and the page has
    already put it there."""
    data = request.get_json(silent=True) or request.form or {}
    theme = normalize_theme(data.get("theme"))
    accent = normalize_accent(data.get("accent"))
    try:
        if not current_user.is_authenticated:
            return jsonify({"ok": True, "stored": False,
                            "theme": theme, "accent": accent})
    except Exception:
        return jsonify({"ok": True, "stored": False,
                        "theme": theme, "accent": accent})
    try:
        conn = get_db()
        try:
            with conn.cursor() as cur:
                cur.execute("UPDATE users SET pref_theme = %s, pref_accent = %s "
                            "WHERE id = %s", (theme, accent, current_user.id))
            conn.commit()
        finally:
            conn.close()
        current_user.pref_theme, current_user.pref_accent = theme, accent
        return jsonify({"ok": True, "stored": True,
                        "theme": theme, "accent": accent})
    except Exception as e:
        # The page has already applied it and written localStorage, so a
        # failure here costs the sync, not the change.
        return jsonify({"ok": False, "stored": False, "error": str(e),
                        "theme": theme, "accent": accent}), 500


