@app.route("/unsubscribe")
def unsubscribe_page():
    """One click, from a link in an email, with no sign-in.

    hmac.compare_digest rather than == so a wrong token cannot be found
    one character at a time by timing the responses.

    A bad or edited link is told the same thing a good one is. Whether a
    given address has an account is not something a stranger holding a
    guessed URL gets to learn, and the reader either way ends up
    unsubscribed or already was."""
    raw = request.args.get("u") or ""
    token = request.args.get("t") or ""
    done = False
    try:
        user_id = int(raw)
        if hmac.compare_digest(token, unsubscribe_token(user_id)):
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute("UPDATE users SET newsletter_opt_in = FALSE "
                                "WHERE id = %s", (user_id,))
                conn.commit()
            finally:
                conn.close()
            done = True
    except Exception:
        pass
    return render_template_string(UNSUBSCRIBE_HTML, done=done)


@app.route("/api/news-status")
def api_news_status():
    """Which source answered, for a named player.

    The sandbox this was written in has no outbound access to ESPN, so
    the exact per-athlete news URL could not be confirmed there. This
    reports, from the deployed app, which of the candidate URLs actually
    returned articles and how many -- so "the news is empty" can be
    answered with a reason instead of a guess.

    Secret-protected: it makes an outbound call per hit."""
    if not _secret_ok():
        # Same shape every other secret-protected endpoint refuses with.
        # test_job_endpoint_auth asserts they all match, so that a route
        # cannot quietly grow its own weaker guard.
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    # Team and game news answer here too, so one endpoint covers all
    # three places news now appears.
    team = (request.args.get("team") or "").strip().upper()
    if team:
        _espn_team_news_cache.pop(SLEEPER_TO_ESPN_ABBR.get(team, team), None)
        items = espn_team_news(team)
        cached = _espn_team_news_cache.get(SLEEPER_TO_ESPN_ABBR.get(team, team)) or {}
        return jsonify({"kind": "team", "team": team,
                        "espn_abbr": SLEEPER_TO_ESPN_ABBR.get(team, team),
                        "items": len(items), "url_that_worked": cached.get("url"),
                        "candidate_urls": list(ESPN_TEAM_NEWS_URLS),
                        "sample": items[:2]})
    event = (request.args.get("event") or "").strip()
    if event:
        _espn_game_news_cache.pop(event, None)
        items = espn_game_news(event)
        cached = _espn_game_news_cache.get(event) or {}
        return jsonify({"kind": "game", "event": event, "items": len(items),
                        "url_that_worked": cached.get("url"),
                        "candidate_urls": list(ESPN_GAME_NEWS_URLS),
                        "sample": items[:2]})

    name = (request.args.get("name") or "").strip().lower()
    players = get_all_players()
    hit = None
    for sid, p in players.items():
        full = f"{p.get('first_name','')} {p.get('last_name','')}".strip()
        if full.lower() == name or (name and name in full.lower()):
            hit = (sid, p, full)
            break
    if not hit:
        return jsonify({"error": "no player matched", "name": name}), 404
    sid, p, full = hit
    espn_id = p.get("espn_id")
    _espn_athlete_news_cache.pop(str(espn_id), None)
    per_player = espn_athlete_news(espn_id)
    cached = _espn_athlete_news_cache.get(str(espn_id)) or {}
    league = _league_feed_matches(full, p.get("team"), 3)
    return jsonify({
        "player": full, "sleeper_id": sid, "team": p.get("team"),
        "espn_id": espn_id,
        "espn_id_present": bool(espn_id),
        "per_player_items": len(per_player),
        "url_that_worked": cached.get("url"),
        "candidate_urls": list(ESPN_ATHLETE_NEWS_URLS),
        "league_feed_items": len(league),
        "league_feed_sizes": {"espn": len(get_espn_nfl_news()),
                              "rotowire": len(get_rotowire_nfl_news())},
        "sample": (per_player or league)[:2],
        "sources_credited": [n for n, _ in news_sources_used(per_player or league)],
    })


