@app.route("/settings/export")
@login_required
def export_account():
    """Download everything on this account, as JSON."""
    try:
        data = export_account_data(current_user.id)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    body = json.dumps(data, indent=2, default=str)
    resp = make_response(body)
    resp.headers["Content-Type"] = "application/json"
    stamp = datetime.utcnow().strftime("%Y-%m-%d")
    resp.headers["Content-Disposition"] = (
        f'attachment; filename="streakpros-{current_user.username}-{stamp}.json"')
    # Never cached, never stored by a proxy: this is the whole account.
    resp.headers["Cache-Control"] = "no-store, private"
    return resp


@app.route("/settings/delete", methods=["GET", "POST"])
@login_required
def delete_account_page():
    """Delete this account, permanently.

    Its own screen rather than a button on Settings: this is the one
    action here that cannot be undone by doing it again, and it should
    take a deliberate visit rather than a mis-tap.

    Confirmation is typing the username. A password would be no proof
    for the Google sign-in half of the userbase, who have none, and a
    plain "are you sure" is a reflex rather than a decision."""
    error = None
    if request.method == "POST":
        typed = (request.form.get("confirm_username") or "").strip()
        if typed.lower() != (current_user.username or "").lower():
            error = "That isn't your username, so nothing was deleted."
        else:
            try:
                user_id = current_user.id
                result = delete_account(user_id)
                if not result["deleted"]:
                    error = "That account no longer exists."
                else:
                    logout_user()
                    return redirect("/?deleted=1")
            except Exception as e:
                error = str(e)
    return render_template_string(
        DELETE_ACCOUNT_HTML, error=error,
        league_count=len(get_synced_league_ids(current_user.id) or []))


@app.route("/forgot-password", methods=["GET", "POST"])
def forgot_password():
    """Ask for a reset link.

    The answer is the same whether or not the address has an account. A
    form that says "no such user" is a way to find out who has one."""
    sent = False
    error = None
    if request.method == "POST":
        email = (request.form.get("email") or "").strip().lower()
        if not email or "@" not in email:
            error = "Enter the email address on your account."
        else:
            try:
                row = user_by_email(email)
                if row:
                    send_password_reset_email(row, create_password_reset(row["id"]))
            except Exception:
                # Even a database failure must not change the answer --
                # a slow or broken response for real addresses only is
                # the same leak by another route.
                app.logger.exception("reset request failed for %s", email)
            sent = True
    return render_template_string(FORGOT_PASSWORD_HTML, sent=sent, error=error,
                                  mail_on=mail_configured())


@app.route("/reset-password", methods=["GET", "POST"])
def reset_password():
    token = request.args.get("token") or request.form.get("token") or ""
    error = None
    if request.method == "POST":
        password = request.form.get("password") or ""
        confirm = request.form.get("confirm") or ""
        if len(password) < MIN_PASSWORD_LENGTH:
            error = "Password must be at least %d characters." % MIN_PASSWORD_LENGTH
        elif password != confirm:
            error = "Those two passwords don't match."
        else:
            ok, why = consume_password_reset(token, password)
            if ok:
                return render_template_string(RESET_PASSWORD_HTML, token=token,
                                              error=None, done=True)
            error = why
    return render_template_string(RESET_PASSWORD_HTML, token=token, error=error, done=False)


