@app.route("/auth/google/callback")
def google_callback():
    token = oauth.google.authorize_access_token()
    userinfo = token.get("userinfo") or oauth.google.userinfo()
    email = (userinfo.get("email") or "").lower()
    sub = userinfo.get("sub")

    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT * FROM users WHERE oauth_provider = 'google' AND oauth_sub = %s", (sub,))
            row = cur.fetchone()
            if not row and email:
                # Link to an existing email/password account instead of duplicating
                cur.execute("SELECT * FROM users WHERE email = %s", (email,))
                row = cur.fetchone()
                if row:
                    cur.execute(
                        "UPDATE users SET oauth_provider='google', oauth_sub=%s WHERE id=%s",
                        (sub, row["id"]),
                    )
                    conn.commit()
            if not row:
                base_username = re.sub(r"[^A-Za-z0-9_]", "", email.split("@")[0])[:15] or "user"
                username = base_username
                suffix = 1
                while not username_available(username):
                    suffix += 1
                    username = f"{base_username}{suffix}"
                cur.execute(
                    """INSERT INTO users (email, username, oauth_provider, oauth_sub)
                       VALUES (%s, %s, 'google', %s) RETURNING *""",
                    (email, username, sub),
                )
                row = cur.fetchone()
                conn.commit()
    finally:
        conn.close()

    login_user(User(row), remember=True)
    return redirect(SIGNED_IN_HOME)


def build_portfolio_summary(data, num_qbs=1):
    fc_players = get_fantasycalc_values(num_qbs)["players"]
    pos_totals = {p: 0 for p in POSITIONS}
    exposure = {}
    leagues_count = 0

    for lg in data["leagues"]:
        me = next((t for t in lg["teams"] if t["is_you"]), None)
        if not me:
            continue
        leagues_count += 1
        for pos in POSITIONS:
            for sid, name in me["positions"].get(pos, []):
                val = fc_players.get(sid, {}).get("value", 0)
                pos_totals[pos] += val
                entry = exposure.setdefault(sid, {
                    "sid": sid, "name": name, "position": pos, "shares": 0,
                    "value": val, "photo": player_photo_url(sid),
                })
                entry["shares"] += 1

    total_val = sum(pos_totals.values()) or 1
    pos_pct = [(p, round(100 * pos_totals[p] / total_val, 1)) for p in POSITIONS]
    exposure_list = sorted(exposure.values(), key=lambda x: -x["value"])
    return {"leagues_count": leagues_count, "pos_pct": pos_pct, "exposure": exposure_list[:75]}


@app.route("/league-manager")
def leagues_page():
    username = request.args.get("u", "").strip()
    fmt = request.args.get("fmt", "1qb")
    manage = request.args.get("manage") == "1"
    chosen_param = request.args.getlist("leagues")
    error = None
    data = None
    portfolio = None
    used_saved = False
    picker = None

    if not username and current_user.is_authenticated and current_user.sleeper_username:
        username = current_user.sleeper_username
        used_saved = True

    if username:
        try:
            user_id, display_name, brief = get_leagues_brief(username)

            if current_user.is_authenticated and username != (current_user.sleeper_username or ""):
                conn = get_db()
                try:
                    with conn.cursor() as cur:
                        cur.execute("UPDATE users SET sleeper_username = %s WHERE id = %s", (username, current_user.id))
                    conn.commit()
                    current_user.sleeper_username = username
                finally:
                    conn.close()

            saved_ids = get_synced_league_ids(current_user.id) if current_user.is_authenticated else None

            if manage:
                # Reopen the picker to add/remove leagues -- preselect whatever
                # is currently synced (or currently on-screen, for a guest who
                # has no saved state) rather than starting from scratch.
                preselected = set(chosen_param) if chosen_param else (saved_ids or set())
                picker = {"leagues": brief, "display_name": display_name, "preselected": preselected, "default_all": False}
            elif chosen_param:
                valid_ids = {lg["league_id"] for lg in brief}
                chosen_ids = [lid for lid in chosen_param if lid in valid_ids]
                over_limit = (current_user.is_authenticated and not plus_unlocked()
                              and len(chosen_ids) > FREE_LEAGUE_LIMIT)
                if current_user.is_authenticated and not over_limit:
                    set_synced_league_ids(current_user.id, chosen_ids)
                if over_limit:
                    error = ("Free accounts sync one league. StreakPros+ syncs all of them; "
                             "the plans are under StreakPros+ in the menu.")
                    picker = {"leagues": brief, "display_name": display_name,
                              "preselected": set(chosen_ids), "default_all": False}
                elif not chosen_ids:
                    error = "Pick at least one league to sync."
                    picker = {"leagues": brief, "display_name": display_name, "preselected": set(), "default_all": False}
                else:
                    data = build_leagues_for_user(username, league_ids=set(chosen_ids))
                    portfolio = build_portfolio_summary(data, num_qbs=2 if fmt == "superflex" else 1)
            elif saved_ids is not None:
                data = build_leagues_for_user(username, league_ids=saved_ids)
                portfolio = build_portfolio_summary(data, num_qbs=2 if fmt == "superflex" else 1)
            else:
                # First time we've seen this username with no saved selection --
                # ask which leagues to sync instead of building every one of
                # them up front.
                picker = {"leagues": brief, "display_name": display_name, "preselected": set(), "default_all": True}
        except Exception as e:
            error = str(e)

    return render_template_string(
        HOME_HTML, username=username, data=data, error=error, portfolio=portfolio, fmt=fmt,
        used_saved=used_saved, picker=picker,
    )


@app.route("/league")
def league_detail():
    league_id = request.args.get("league_id", "")
    username = request.args.get("u", "")
    roster_id = request.args.get("roster_id", type=int)
    try:
        detail = build_league_detail(league_id, username, roster_id)
        # Matchup grades are an auth-gated perk (eventually a paid one, once
        # billing exists -- see /matchups) computed here in the route rather
        # than inside build_league_detail, which stays pure/auth-unaware so
        # it's reusable wherever a roster needs building regardless of who's
        # asking. Every grade lookup below hits already-warm caches, so this
        # adds no new I/O for a signed-in visitor.
        if detail.get("mode") == "roster" and current_user.is_authenticated:
            unlocked = plus_unlocked()
            info = get_current_week_info()
            if unlocked:
                ensure_schedule_synced(info["season"])
            for col in detail["columns"].values():
                for p in col["players"]:
                    if not unlocked:
                        # The badge's place is kept, as a link to the plan.
                        p["grade"], p["grade_class"], p["grade_locked"] = None, None, True
                        continue
                    grade = compute_matchup_grade(p["sleeper_id"], info["season"], info["week"])
                    p["grade"] = grade["grade"] if grade else None
                    p["grade_class"] = grade["grade_class"] if grade else None
        return render_template_string(LEAGUE_DETAIL_HTML, detail=detail, username=username, league_id=league_id)
    except Exception as e:
        return f"Error: {e}", 500


@app.route("/player")
def player_detail():
    sid = request.args.get("sid", "")
    num_qbs = request.args.get("numqbs", default=1, type=int)
    username = request.args.get("u", "")
    tab = request.args.get("tab", "general")
    ref = request.args.get("ref", "/rankings")
    all_players = get_all_players()
    p = all_players.get(sid)
    if not p:
        return "Player not found", 404
    fc_players = get_fantasycalc_values(num_qbs)["players"]
    v = fc_players.get(sid, {})
    full_name = f"{p.get('first_name','')} {p.get('last_name','')}".strip()
    adp_data = get_adp_data()

    current_season = int(SEASON)
    # Real career range, derived from years of NFL experience -- capped at
    # 6 seasons. With the per-season week-fetch now parallelized, 6 cold
    # seasons still means ~6 concurrent bursts of 18 requests; much more
    # than that was timing out the page entirely on Render's free tier.
    MAX_CAREER_SEASONS = 6
    years_exp = p.get("years_exp")
    if years_exp is None:
        years_exp = 4
    years_exp = max(0, min(years_exp, MAX_CAREER_SEASONS - 1))
    rookie_season = current_season - years_exp
    available_seasons = list(range(rookie_season, current_season + 1))

    season = request.args.get("season", type=int, default=current_season)
    if season not in available_seasons:
        season = current_season
    season_idx = available_seasons.index(season)
    prev_season = available_seasons[season_idx - 1] if season_idx > 0 else None
    next_season = available_seasons[season_idx + 1] if season_idx < len(available_seasons) - 1 else None

    # Only fetch what the current tab actually needs -- General only ever
    # needs the current season (for the PPG tile, shown on every tab).
    # Log needs whichever specific season is being viewed. Career is the
    # only tab that genuinely needs the full multi-season range. This is
    # the fix for player pages being slow to open from Rankings: every
    # click used to fetch all 6 career seasons regardless of which tab
    # you'd land on, even though General (the default) only needed 1.
    seasons_to_fetch = {current_season}
    if tab == "log":
        seasons_to_fetch.add(season)
    if tab == "career":
        seasons_to_fetch.update(available_seasons)

    season_data = {}
    with ThreadPoolExecutor(max_workers=max(len(seasons_to_fetch), 1)) as executor:
        future_map = {executor.submit(get_season_stats, str(yr)): yr for yr in seasons_to_fetch}
        for future in as_completed(future_map):
            season_data[future_map[future]] = future.result()

    this_season_stats = season_data[season].get(sid, {"games": 0, "fpts": 0.0, "weeks": {}})
    weekly = [{"week": w, "pts": this_season_stats.get("weeks", {}).get(w, 0)} for w in range(1, 19)]
    max_pts = max([w["pts"] for w in weekly] + [1])
    for w in weekly:
        w["pct"] = round(100 * w["pts"] / max_pts, 1) if max_pts else 0

    career_rows = []
    for yr in available_seasons:
        s = season_data.get(yr, {}).get(sid, {"games": 0, "fpts": 0.0})
        finish = get_season_finish_ranks(yr).get(sid, {}) if tab == "career" and s.get("games") else {}
        career_rows.append({
            "season": yr, "games": s.get("games", 0),
            "fpts": round(s.get("fpts", 0), 1) if s.get("games") else None,
            "fpts_per_game": round(s.get("fpts", 0) / s["games"], 1) if s.get("games") else None,
            "overall_finish": finish.get("overall"),
            "position_finish": finish.get("position"),
        })

    current_ppg = round(this_season_stats["fpts"] / this_season_stats["games"], 1) if this_season_stats.get("games") else None

    adp_key = (full_name.lower(), (p.get("position") or "").upper())
    adp = (
        adp_data["by_key"].get(adp_key)
        or adp_data["by_name_only"].get(full_name.lower())
        or adp_data["by_normalized"].get(normalize_name(full_name))
    )

    info = {
        "name": full_name, "photo": player_photo_url(sid),
        "position": p.get("position", "?"), "team": p.get("team") or "Free agent",
        "age": compute_age_decimal(p.get("birth_date")) or p.get("age"), "years_exp": p.get("years_exp"), "college": p.get("college"),
        "height": format_height(p.get("height")), "weight": p.get("weight"),
        "status": p.get("status"), "injury": _injury_badge(p),
        "value": v.get("value"), "position_rank": v.get("position_rank"), "overall_rank": v.get("overall_rank"),
        "redraft_value": v.get("redraft_value"), "tier": rank_tier(v.get("overall_rank")),
        "adp": adp, "ppg": current_ppg,
        "community": get_community_score(sid),
    }
    raw_team = p.get("team")
    depth_chart = get_team_depth_chart(raw_team, all_players)
    # Sleeper carries ESPN's own id for nearly every player, which is
    # what makes per-player news possible at all.
    news = get_player_news(full_name, raw_team, espn_id=p.get("espn_id"))
    return render_template_string(
        PLAYER_HTML, p=info, username=username, sid=sid, num_qbs=num_qbs, tab=tab, ref=ref,
        season=season, prev_season=prev_season, next_season=next_season,
        weekly=weekly, career_rows=career_rows,
        depth_chart=depth_chart, news=news,
        news_sources=news_sources_used(news),
    )


# --- Your Matchup (live) and Lineup (optimizer) ---------------------------
#
# Both read the same three feeds: the league's rosters and users (already
# cached), Sleeper's matchups for the week (their own live points, scored
# by the league's own settings, so the numbers agree with the Sleeper
# app to the decimal), and Sleeper's projections for the week, scored
# here with the league's settings. Game state per NFL team comes from
# the ESPN scoreboard the scores page already polls.

MATCHUP_LIVE_TTL = 20            # Sleeper matchups while games are on
PROJECTIONS_TTL = 1800           # projections move a few times a day
MATCHUP_POLL_MS = 10000
BENCH_SLOTS = ("BN", "IR", "TAXI")
# What each lineup slot takes. Sleeper names the slots this way in
# roster_positions and lists each player's eligible positions in
# fantasy_positions.
SLOT_ELIGIBLE = {
    "QB": ("QB",), "RB": ("RB",), "WR": ("WR",), "TE": ("TE",), "K": ("K",), "DEF": ("DEF",),
    "FLEX": ("RB", "WR", "TE"), "SUPER_FLEX": ("QB", "RB", "WR", "TE"), "REC_FLEX": ("WR", "TE"),
    "WRRB_FLEX": ("RB", "WR"), "DL": ("DL", "DE", "DT"), "LB": ("LB",), "DB": ("DB", "CB", "S"),
    "IDP_FLEX": ("DL", "DE", "DT", "LB", "DB", "CB", "S"),
}
SLOT_LABEL = {"SUPER_FLEX": "SFLEX", "REC_FLEX": "W/T", "WRRB_FLEX": "W/R", "IDP_FLEX": "IDP"}
# Narrow slots fill first, then the flexes from narrow to wide, so the
# best players land where only they fit and the flexes take the best of
# what is left. With slots nested this way that order is optimal.
SLOT_FILL_ORDER = ("QB", "K", "DEF", "TE", "RB", "WR", "DL", "LB", "DB", "REC_FLEX", "WRRB_FLEX", "FLEX", "IDP_FLEX", "SUPER_FLEX")
QUESTIONABLE_FACTOR = 0.85


def get_league_matchups(league_id, week, cache={}):
    """Sleeper's matchups for one league-week: one entry per roster with
    matchup_id, points, starters, starters_points, players_points."""
    data = _cached_get(f"{SLEEPER_BASE}/league/{league_id}/matchups/{int(week)}", cache, ttl=MATCHUP_LIVE_TTL)
    return [m for m in (data or []) if isinstance(m, dict)]


def get_week_projections(season, week, cache={}):
    """{player_id: projected stats} for a week, from Sleeper's projections
    feed, the same host and shape as its stats feed. Empty when it cannot
    be read; the lineup falls back to recent averages then."""
    key = (int(season), int(week))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < PROJECTIONS_TTL:
        return entry["data"]
    out = {}
    try:
        r = requests.get(f"https://api.sleeper.com/projections/nfl/{int(season)}/{int(week)}",
                         params={"season_type": "regular"}, timeout=15)
        if r.status_code == 200:
            data = r.json()
            if isinstance(data, dict):
                data = list(data.values())
            for item in data if isinstance(data, list) else []:
                if not isinstance(item, dict):
                    continue
                pid, stats = item.get("player_id"), item.get("stats")
                if pid and isinstance(stats, dict):
                    out[str(pid)] = stats
    except Exception as e:
        app.logger.warning("projections %s/%s: %s", season, week, e)
    if out or not entry:
        cache[key] = {"data": out, "time": now}
        _cache_trim(cache, CACHE_LIMIT_BOARDS)
        return out
    return entry["data"]


def score_with_settings(stats, scoring_settings):
    """Fantasy points for a stat line under a league's own scoring
    settings. Sleeper keys its scoring settings and its stat lines the
    same way (pass_yd, rec, bonus_rec_te, ...), which is what makes this
    a plain dot product and the same arithmetic the league runs."""
    if not isinstance(stats, dict) or not isinstance(scoring_settings, dict):
        return 0.0
    total = 0.0
    for key, weight in scoring_settings.items():
        v = stats.get(key)
        if isinstance(v, (int, float)) and isinstance(weight, (int, float)) and v and weight:
            total += v * weight
    return round(total, 2)


def live_team_games(season, week):
    """{team abbr: game state} for every game of the week: status,
    period, clock, the opponent, both scores and kickoff."""
    out = {}
    try:
        data = espn_week_scoreboard(season, week) or {}
    except Exception:
        data = {}
    events = data.get("events") if isinstance(data, dict) else data
    for ev in (events or []):
        card = espn_event_to_card(ev) if isinstance(ev, dict) and "competitions" in ev else None
        if not card:
            continue
        for me, them, home in ((card["home"], card["away"], True), (card["away"], card["home"], False)):
            if not me.get("abbr"):
                continue
            out[me["abbr"]] = {
                "status": card["status"], "period": card.get("period"), "clock": card.get("clock"),
                "detail": card.get("status_detail"), "opp": them.get("abbr"), "home": home,
                "score": me.get("score"), "opp_score": them.get("score"), "kickoff": card.get("date"),
                "event_id": card.get("id"),
            }
    return out


def game_fraction_left(state):
    """How much of a game is still to be played, 0..1, from its period
    and clock. Nothing scheduled: 1. Final: 0. Overtime: a little."""
    if not state:
        return 1.0
    status = state.get("status")
    if status == "final":
        return 0.0
    if status != "in_progress":
        return 1.0
    period = _safe_int(state.get("period"), 1) or 1
    clock = str(state.get("clock") or "15:00")
    try:
        m, s = clock.split(":")
        secs = int(m) * 60 + int(s)
    except (ValueError, AttributeError):
        secs = 900
    if period > 4:
        return 0.08
    return max(0.0, min(1.0, ((4 - period) * 900 + min(secs, 900)) / 3600.0))


def _norm_cdf(x):
    return 0.5 * (1.0 + math.erf(x / math.sqrt(2.0)))


def win_probability(mine, theirs):
    """P(my side finishes ahead) from each side's expected finish and how
    much of each is still uncertain. A player's spread is proportional to
    what they have left to play, plus a floor, and independent across
    players. Both sides done: whoever leads."""
    if mine["left_players"] == 0 and theirs["left_players"] == 0:
        if mine["points"] == theirs["points"]:
            return 0.5
        return 1.0 if mine["points"] > theirs["points"] else 0.0
    diff = mine["projected"] - theirs["projected"]
    var = mine["variance"] + theirs["variance"]
    if var <= 0:
        return 1.0 if diff > 0 else (0.0 if diff < 0 else 0.5)
    return round(_norm_cdf(diff / math.sqrt(var)), 3)


def _player_projection(sid, position, projections, scoring_settings, season, week, sched_state, stat_line):
    """Projected points for the week under the league's scoring, and
    where the number came from."""
    proj = projections.get(str(sid))
    if isinstance(proj, dict):
        pts = score_with_settings(proj, scoring_settings)
        if pts:
            return pts, "sleeper"
        # A feed whose keys do not meet this league's settings (an odd
        # scoring key set) still carries Sleeper's own PPR figure.
        if isinstance(proj.get("pts_ppr"), (int, float)) and proj["pts_ppr"]:
            return round(float(proj["pts_ppr"]), 1), "sleeper_ppr"
    if projections:
        # The feed is up and projects nothing for this player. That IS
        # the projection: a backup's average from the weeks he started
        # is not one, and it once put a QB2 ahead of a starter.
        return 0.0, "none"
    # The feed is down: the player's own recent average, in PPR terms,
    # holds a place until it is up.
    recent = _player_recent_games(sid, season, 4)
    if recent and recent.get("avg") is not None:
        return round(float(recent["avg"]), 1), "recent"
    return 0.0, "none"


def _slot_label(slot):
    return SLOT_LABEL.get(slot, slot)


# How much a designation rules a player out, so the stricter of two
# sources wins. Suspended and Not Active sit with Out for a lineup: the
# player does not play, whatever the list is called.
_INJURY_RANK = {"probable": 0, "questionable": 1, "doubtful": 2, "admin": 3, "out": 4}
_BADGE_BY_TITLE = {title: (key, label, tier) for key, (label, title, tier) in INJURY_BADGE.items()}
_espn_injury_sid_cache = {}


def _espn_injury_by_sid(cache=_espn_injury_sid_cache):
    """{sleeper_id: ESPN injury row} for the whole league, TTL 600s.
    ESPN's report is updated through the week; Sleeper's designation
    can lag it by a day -- a QB it still had Questionable on Friday was
    Out on ESPN, and the lineup has to know."""
    now = time.time()
    entry = cache.get("all")
    if entry and now - entry["time"] < 600:
        return entry["data"]
    try:
        _, by_sid = build_injury_statuses()
    except Exception:
        by_sid = entry["data"] if entry else {}
    cache["all"] = {"data": by_sid or {}, "time": now}
    return by_sid or {}


def _merged_injury(p, espn_row):
    """The player's designation for the lineup: the stricter of Sleeper's
    and ESPN's, with what is wrong when either source says."""
    badge = _injury_badge(p)
    row = espn_row if isinstance(espn_row, dict) else {}
    hit = _BADGE_BY_TITLE.get(row.get("status") or "")
    if not hit:
        return badge
    key, label, tier = hit
    if badge and _INJURY_RANK.get(badge["tier"], 0) >= _INJURY_RANK.get(tier, 0):
        return badge
    title = row["status"]
    detail = row.get("detail") or (p.get("injury_body_part") or "").strip()
    if detail:
        title = f"{title} \u2014 {detail}"
    return {"label": label, "title": title, "tier": tier, "is_ir": key == "IR",
            "color": INJURY_TIER_COLOR.get(tier, "var(--ink-muted)"), "source": "espn"}


def _lineup_slots(league):
    return [s for s in (league.get("roster_positions") or []) if s not in BENCH_SLOTS]


def _player_card(sid, all_players, live_games, projections, scoring_settings, season, week, points=None):
    p = all_players.get(sid) or {}
    team = p.get("team")
    state = live_games.get(team) if team else None
    if state is None and team:
        # Not on the live scoreboard: the schedule table says whether
        # that is a bye or a game the feed did not carry.
        try:
            sched = get_schedule_for_team_week(season, week, team)
        except Exception:
            sched = None
        if sched:
            state = {"status": sched.get("status") or "scheduled", "period": None, "clock": None, "detail": None,
                     "opp": sched.get("opponent"), "home": sched.get("home"),
                     "kickoff": sched["kickoff"].isoformat() + "Z" if hasattr(sched.get("kickoff"), "isoformat") else sched.get("kickoff"),
                     "event_id": sched.get("espn_event_id")}
    proj, proj_source = _player_projection(sid, p.get("position"), projections, scoring_settings, season, week, state, None)
    # Where he sits on his club's depth chart. A backup (QB2, RB3, WR4,
    # TE2) is never given a stand-in projection: his average comes from
    # weeks he started, and he is not starting.
    depth = _safe_int(p.get("depth_chart_order"), 0)
    limit = STREAK_DEPTH.get(streak_position_group(p.get("position")))
    backup = bool(limit and depth > limit)
    if backup and proj_source == "recent":
        proj, proj_source = 0.0, "none"
    pts = points if isinstance(points, (int, float)) else None
    frac = game_fraction_left(state) if team else 0.0
    if state is None and team:
        phase = "bye"
        frac = 0.0
    elif state is None:
        phase = "none"
    elif state["status"] == "final":
        phase = "done"
    elif state["status"] == "in_progress":
        phase = "live"
    else:
        phase = "upcoming"
    actual = pts if pts is not None else 0.0
    if phase == "done":
        expected = actual
    elif phase == "live":
        expected = actual + proj * frac
    elif phase == "upcoming":
        expected = proj
    else:
        expected = actual
    return {
        "sid": sid, "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip() or sid,
        "short": f"{(p.get('first_name') or ' ')[0]}. {p.get('last_name', '')}".strip(),
        "position": p.get("position"), "team": team, "photo": player_photo_url(sid),
        "points": round(actual, 2), "proj": round(proj, 1), "proj_source": proj_source,
        "expected": round(expected, 2), "left": round(frac, 3), "phase": phase,
        "game": ({"status": state["status"], "period": state.get("period"), "clock": state.get("clock"),
                  "detail": state.get("detail"), "opp": state.get("opp"), "home": state.get("home"),
                  "kickoff": state.get("kickoff"), "event_id": state.get("event_id")} if state else None),
        "injury": _merged_injury(p, _espn_injury_by_sid().get(sid)),
        "depth": depth or None, "depth_label": f"{p.get('position')}{depth}" if depth and p.get("position") else None, "backup": backup,
        "fantasy_positions": p.get("fantasy_positions") or ([p.get("position")] if p.get("position") else []),
    }


def _side(roster, entry, league, all_players, live_games, projections, scoring, season, week, users):
    """One side of a matchup: the starters in slot order, the bench, the
    totals and what is still to come."""
    slots = _lineup_slots(league)
    starters = list(entry.get("starters") or roster.get("starters") or [])
    spts = entry.get("starters_points") or []
    ppts = entry.get("players_points") or {}
    rows = []
    for i, slot in enumerate(slots):
        sid = starters[i] if i < len(starters) else None
        if not sid or sid in ("0", 0):
            rows.append({"slot": _slot_label(slot), "player": None})
            continue
        pts = spts[i] if i < len(spts) and isinstance(spts[i], (int, float)) else ppts.get(sid)
        rows.append({"slot": _slot_label(slot),
                     "player": _player_card(sid, all_players, live_games, projections, scoring, season, week, pts)})
    bench = []
    for sid in (roster.get("players") or []):
        if sid in starters:
            continue
        bench.append(_player_card(sid, all_players, live_games, projections, scoring, season, week, ppts.get(sid)))
    bench.sort(key=lambda c: -c["points"])
    played = [r["player"] for r in rows if r["player"]]
    points = entry.get("points")
    if not isinstance(points, (int, float)):
        points = sum(c["points"] for c in played)
    projected = sum(c["expected"] for c in played)
    variance = sum((0.6 * c["proj"] * c["left"] + (1.5 if c["left"] > 0 else 0.0)) ** 2 for c in played)
    owner = users.get(roster.get("owner_id"), {})
    return {
        "roster_id": roster.get("roster_id"), "name": owner.get("name") or "Unknown",
        "avatar_url": owner.get("avatar_url"), "points": round(float(points), 2),
        "projected": round(projected, 1), "variance": variance,
        "left_players": sum(1 for c in played if c["left"] > 0),
        "live_players": sum(1 for c in played if c["phase"] == "live"),
        "rows": rows, "bench": bench,
        "record": f"{(roster.get('settings') or {}).get('wins', 0)}-{(roster.get('settings') or {}).get('losses', 0)}",
    }


def build_live_matchup(league, user_id, season, week):
    """The reader's matchup in one league for one week, live: both
    lineups slot by slot with each player's points and game state, the
    totals, the projected finish and the win probability. None when the
    reader has no roster in the league; a side of None when the roster
    has no opponent this week (a bye or the playoffs)."""
    league_id = league["league_id"]
    all_players = get_all_players()
    rosters = get_rosters(league_id) or []
    users = {u["user_id"]: {"name": u.get("display_name", "?"), "avatar_url": sleeper_avatar_url(u.get("avatar"))}
             for u in (get_league_users(league_id) or [])}
    mine = next((r for r in rosters if r.get("owner_id") == user_id), None)
    if mine is None:
        return None
    matchups = get_league_matchups(league_id, week)
    by_roster = {m.get("roster_id"): m for m in matchups}
    my_entry = by_roster.get(mine["roster_id"]) or {"roster_id": mine["roster_id"], "starters": mine.get("starters"), "points": 0}
    opp_entry = None
    if my_entry.get("matchup_id") is not None:
        opp_entry = next((m for m in matchups if m.get("matchup_id") == my_entry["matchup_id"]
                          and m.get("roster_id") != mine["roster_id"]), None)
    opp_roster = next((r for r in rosters if opp_entry and r.get("roster_id") == opp_entry.get("roster_id")), None)
    scoring = league.get("scoring_settings") or {}
    projections = get_week_projections(season, week)
    live_games = live_team_games(season, week)
    me = _side(mine, my_entry, league, all_players, live_games, projections, scoring, season, week, users)
    them = _side(opp_roster, opp_entry, league, all_players, live_games, projections, scoring, season, week, users) if opp_roster else None
    wp = win_probability(me, them) if them else None
    for s in (me, them):
        if s:
            s.pop("variance", None)
    return {
        "league_id": league_id, "league_name": league.get("name") or "League", "season": season, "week": week,
        "me": me, "opp": them, "win_probability": wp,
        "any_live": any(r["player"] and r["player"]["phase"] == "live" for s in (me, them) if s for r in s["rows"]),
        "all_done": all(r["player"] is None or r["player"]["left"] == 0 for s in (me, them) if s for r in s["rows"]),
        "sleeper_url": f"https://sleeper.com/leagues/{league_id}/matchup",
        "updated": datetime.utcnow().isoformat() + "Z",
    }


def optimal_lineup(slots, players):
    """{slot index: player} maximizing projected points, players given
    as cards with 'fantasy_positions' and 'value'. Narrow slots first,
    then the flexes from narrow to wide (see SLOT_FILL_ORDER)."""
    order = sorted(range(len(slots)), key=lambda i: (SLOT_FILL_ORDER.index(slots[i]) if slots[i] in SLOT_FILL_ORDER else 99, i))
    used, out = set(), {}
    for i in order:
        elig = SLOT_ELIGIBLE.get(slots[i], (slots[i],))
        best = None
        for p in players:
            if p["sid"] in used or not any(fp in elig for fp in p["fantasy_positions"]):
                continue
            if best is None or p["value"] > best["value"]:
                best = p
        if best:
            used.add(best["sid"])
            out[i] = best
    return out


def _lineup_value(card):
    """What a player is worth in the lineup this week: what they have
    scored plus what is projected for what is left, less for a
    questionable tag, nothing for out, bye or done-and-empty."""
    inj = card.get("injury") or {}
    tier = inj.get("tier")
    if card["phase"] in ("done",):
        return round(card["points"], 1), "played"
    if card["phase"] == "bye":
        return 0.0, "bye"
    if tier in ("out", "admin") or inj.get("is_ir"):
        return round(card["points"], 1), "out"
    if card["phase"] == "upcoming" and card["proj"] <= 0:
        return 0.0, ("backup" if card.get("backup") else "no_proj")
    if tier == "doubtful":
        return round(card["points"] + 0.25 * card["proj"] * card["left"], 1), "doubtful"
    if tier == "questionable":
        return round(card["points"] + QUESTIONABLE_FACTOR * card["proj"] * card["left"], 1), "questionable"
    return round(card["points"] + card["proj"] * card["left"], 1), "ok"


def _value_tag(card):
    """The short tag next to a player in the lineup and on the bench."""
    note = card.get("value_note")
    inj = card.get("injury") or {}
    if note == "out":
        return (inj.get("title") or "Out").split(" \u2014 ")[0].replace("Injured Reserve", "IR")
    if note in ("questionable", "doubtful", "bye"):
        return note.capitalize()
    if note == "backup":
        return f"{card['depth_label']} on depth chart" if card.get("depth_label") else "Backup"
    if note == "no_proj":
        return "No projection"
    return None


def _why(card, other, slot, grade):
    """One plain sentence for a change: the matchup, the usage, the tag."""
    bits = []
    c = (grade or {}).get("components") or {}
    if c.get("opponent") and c.get("def_rank_most_pts_used"):
        pool = c.get("def_pool_size") or 32
        bits.append(f"{card['team']} face the defence allowing the {ordinal(c['def_rank_most_pts_used'])}-most points to {card['position']}s of {pool}")
    if card.get("snap_pct"):
        bits.append(f"{card['short']} has {card['snap_pct']}% of snaps")
    if card.get("recent_avg") is not None:
        bits.append(f"{card['recent_avg']:.1f} a game over the last {card.get('recent_n', 4)}")
    inj = (other or {}).get("injury") or {}
    if other and inj.get("title"):
        bits.append(f"{other['short']} is {inj['title'].lower()}")
    elif other and other.get("phase") == "bye":
        bits.append(f"{other['short']} is on bye")
    if not bits:
        bits.append(f"{card['short']} projects {card['proj']} to {other['proj'] if other else 0}")
    s = "; ".join(bits)
    return s[0].upper() + s[1:] + "."


def build_lineup_plan(league, user_id, season, week):
    """The reader's best lineup in one league this week against the
    one they have set: the changes to make, each with both players'
    grade, projection and a reason; the lineup after the changes; the
    bench ranked. None without a roster in the league."""
    league_id = league["league_id"]
    all_players = get_all_players()
    rosters = get_rosters(league_id) or []
    mine = next((r for r in rosters if r.get("owner_id") == user_id), None)
    if mine is None:
        return None
    scoring = league.get("scoring_settings") or {}
    projections = get_week_projections(season, week)
    live_games = live_team_games(season, week)
    matchups = get_league_matchups(league_id, week)
    entry = next((m for m in matchups if m.get("roster_id") == mine["roster_id"]), {}) or {}
    ppts = entry.get("players_points") or {}
    season_stats = get_season_stats(season)
    cards = {}
    for sid in (mine.get("players") or []):
        if sid in (mine.get("reserve") or []) or sid in (mine.get("taxi") or []):
            continue
        card = _player_card(sid, all_players, live_games, projections, scoring, season, week, ppts.get(sid))
        card["value"], card["value_note"] = _lineup_value(card)
        card["tag"] = _value_tag(card)
        st = season_stats.get(sid) or {}
        card["snap_pct"] = st.get("snap_pct")
        rec = _player_recent_games(sid, season, 4)
        card["recent_avg"] = rec.get("avg") if rec else None
        card["recent_n"] = rec.get("games") if rec else None
        g = compute_matchup_grade(sid, season, week) if card["position"] in POSITIONS else None
        card["grade"] = g["grade"] if g else None
        card["grade_class"] = g["grade_class"] if g else None
        card["_grade"] = g
        cards[sid] = card
    slots = _lineup_slots(league)
    current = list(entry.get("starters") or mine.get("starters") or [])
    current = [s if s in cards else None for s in current[:len(slots)]] + [None] * max(0, len(slots) - len(current))
    # Sleeper locks a player at his kickoff: a starter whose game has
    # begun stays where he is, and a bench player whose game has begun
    # cannot come in. Only the open slots and the unlocked players are
    # optimized.
    for c in cards.values():
        c["locked"] = c["phase"] in ("live", "done")
    open_idx = [i for i, sid in enumerate(current) if not (sid and cards[sid]["locked"])]
    pool = [c for sid, c in cards.items() if not c["locked"] and sid not in {current[i] for i in range(len(current)) if i not in open_idx}]
    sub = optimal_lineup([slots[i] for i in open_idx], pool)
    best = {i: cards[current[i]] for i in range(len(current)) if i not in open_idx and current[i]}
    best.update({open_idx[j]: p for j, p in sub.items()})
    best_sids = {i: p["sid"] for i, p in best.items()}
    cur_total = sum(cards[s]["value"] for s in current if s)
    best_total = sum(p["value"] for p in best.values())
    # Changes: a player who should start but does not, paired with the
    # one they replace at that slot. Same players in other slots is not
    # a change worth a card.
    cur_set = {s for s in current if s}
    best_set = set(best_sids.values())
    # Each change is named for the slot the NEW player fills, and paired
    # with the player leaving the lineup -- one of his own position when
    # there is one, else the most valuable leaving. Starters who only
    # change slots to make room (an RB sliding from RB to FLEX) are
    # listed as moves, not changes. Naming a change for the slot the
    # leaving player held once read "Start at WR" over a running back.
    slot_of_best = {sid: i for i, sid in best_sids.items()}
    slot_of_cur = {sid: i for i, sid in enumerate(current) if sid}
    entering = sorted((cards[s] for s in best_set - cur_set), key=lambda c: -c["value"])
    leaving = [cards[s] for s in cur_set - best_set]
    moves = [{"sid": s, "short": cards[s]["short"], "from": _slot_label(slots[slot_of_cur[s]]), "to": _slot_label(slots[slot_of_best[s]])}
             for s in sorted(best_set & cur_set, key=lambda s: slot_of_best[s]) if slots[slot_of_best[s]] != slots[slot_of_cur[s]]]
    changes = []
    for new in entering:
        slot = slots[slot_of_best[new["sid"]]]
        if not any(fp in SLOT_ELIGIBLE.get(slot, (slot,)) for fp in new["fantasy_positions"]):
            continue
        same = [c for c in leaving if set(c["fantasy_positions"]) & set(new["fantasy_positions"])]
        old = max(same or leaving, key=lambda c: c["value"]) if leaving else None
        if old:
            leaving.remove(old)
        gain = round(new["value"] - (old["value"] if old else 0.0), 1)
        # A change has to be worth making: a real projected gain, from a
        # player who is actually expected to score.
        if new["value"] <= 0 or gain < 0.5:
            continue
        changes.append({
            "slot": _slot_label(slot), "start": _strip(new), "over": _strip(old) if old else None,
            "over_slot": _slot_label(slots[slot_of_cur[old["sid"]]]) if old else None, "gain": gain,
            "why": _why(new, old, slot, new.get("_grade")),
        })
    changes.sort(key=lambda c: -c["gain"])
    lineup = [{"slot": _slot_label(slot), "player": _strip(best[i]) if i in best else None} for i, slot in enumerate(slots)]
    # The bench lists who could still come in: a bench player whose game
    # has started or finished is not a choice any more.
    bench = sorted((_strip(c) for sid, c in cards.items() if sid not in best_set and not c["locked"]), key=lambda c: -c["value"])
    return {
        "league_id": league_id, "league_name": league.get("name") or "League", "season": season, "week": week,
        "changes": changes, "moves": moves if changes else [], "gain": round(best_total - cur_total, 1),
        "current_total": round(cur_total, 1), "best_total": round(best_total, 1),
        "lineup": lineup, "bench": bench, "sleeper_url": f"https://sleeper.com/leagues/{league_id}/team",
        "projections_available": bool(projections),
        "lineup_set": bool(cur_set),
    }


def _strip(card):
    if not card:
        return None
    return {k: v for k, v in card.items() if not k.startswith("_") and k != "fantasy_positions"}


def _account_leagues_for_pages():
    """(username, sleeper user id, [synced leagues]) for the signed-in
    reader, or (None, None, []) when there is nothing to show."""
    if not current_user.is_authenticated or not current_user.sleeper_username:
        return None, None, []
    username = current_user.sleeper_username
    try:
        user_id, _name = get_user_id(username)
        leagues = get_leagues(user_id, SEASON) or []
    except Exception:
        return username, None, []
    synced = get_synced_league_ids(current_user.id) or set()
    leagues = [lg for lg in leagues if lg.get("league_id") in synced] or []
    return username, user_id, leagues


def _pick_league(leagues):
    want = (request.args.get("league") or "").strip()
    return next((lg for lg in leagues if lg.get("league_id") == want), leagues[0] if leagues else None)


@app.route("/matchup")
def matchup_page():
    """Your matchup, live, in the league you pick."""
    username, user_id, leagues = _account_leagues_for_pages()
    info = get_current_week_info()
    week = request.args.get("week", default=info["week"], type=int)
    season = info["season"]
    league = _pick_league(leagues)
    data, error = None, None
    if league and user_id:
        try:
            data = build_live_matchup(league, user_id, season, week)
            if data is None:
                error = "You don't have a team in that league."
        except Exception as e:
            app.logger.warning("matchup page: %s", e)
            error = "Sleeper didn't answer just now. Try again in a moment."
    return render_template_string(
        MATCHUP_HTML, data=data, error=error, leagues=leagues, league=league, week=week, season=season,
        username=username, poll_ms=MATCHUP_POLL_MS)


@app.route("/api/matchup-live")
def api_matchup_live():
    username, user_id, leagues = _account_leagues_for_pages()
    if not user_id:
        return jsonify({"ok": False, "error": "sign in and sync a league"}), 401
    info = get_current_week_info()
    week = request.args.get("week", default=info["week"], type=int)
    league = _pick_league(leagues)
    if not league:
        return jsonify({"ok": False, "error": "no league"}), 404
    try:
        data = build_live_matchup(league, user_id, info["season"], week)
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 502
    if data is None:
        return jsonify({"ok": False, "error": "no team"}), 404
    return jsonify({"ok": True, "matchup": data})


@app.route("/lineup")
def lineup_page():
    """Who to start this week, and why. StreakPros+ (sign-in while the gate is off)."""
    username, user_id, leagues = _account_leagues_for_pages()
    info = get_current_week_info()
    week = request.args.get("week", default=info["week"], type=int)
    season = info["season"]
    league = _pick_league(leagues)
    unlocked = plus_unlocked()
    plan, error = None, None
    if unlocked and league and user_id:
        try:
            ensure_schedule_synced(season)
            plan = build_lineup_plan(league, user_id, season, week)
            if plan is None:
                error = "You don't have a team in that league."
        except Exception as e:
            app.logger.warning("lineup page: %s", e)
            error = "Sleeper didn't answer just now. Try again in a moment."
    return render_template_string(
        LINEUP_HTML, plan=plan, error=error, leagues=leagues, league=league, week=week, season=season,
        username=username, unlocked=unlocked, gate=gate_kind())


@app.route("/api/debug-projections")
def api_debug_projections():
    """The raw projections feed, for checking its shape on the live server."""
    if not _secret_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    info = get_current_week_info()
    season = request.args.get("season", default=info["season"], type=int)
    week = request.args.get("week", default=info["week"], type=int)
    try:
        r = requests.get(f"https://api.sleeper.com/projections/nfl/{season}/{week}", params={"season_type": "regular"}, timeout=10)
        parsed = get_week_projections(season, week)
        sample = next(iter(parsed.items()), None)
        return jsonify({"status_code": r.status_code, "body_preview": r.text[:600], "parsed_players": len(parsed),
                        "sample": sample})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 502


# --- Alerts by email --------------------------------------------------------
#
# Two messages, both about a decision with a deadline: your lineup has a
# problem and kickoff is close, and waivers are open with somebody worth
# claiming. Nothing else is ever emailed from here.
#
# The whole thing is driven by one scheduled job hitting /api/send-alerts
# every hour (see .github/workflows/send-alerts.yml). That job holds no
# state and decides nothing: every rule about who gets what, and when,
# lives in this file, so the schedule can be changed without changing
# behaviour and a missed run costs an hour rather than an alert.
#
# Three rules, and every one of them is enforced here rather than trusted
# to a caller:
#   1. A reader who has unsubscribed gets nothing, whatever the switches
#      below say. newsletter_opt_in is the master.
#   2. The same alert is never sent twice. The sent_alerts row is claimed
#      before the message goes out and released if it fails to send.
#   3. An alert with nothing to say is not sent. No "your lineup is fine"
#      email exists.
ALERT_KINDS = ("lineup", "waivers")
# How close to kickoff a lineup problem is worth an email. Wide enough to
# catch a Friday-evening injury ruling for a Sunday game, narrow enough
# that a problem found on Tuesday does not mail every hour until then.
LINEUP_ALERT_LEAD_HOURS = 36
# A swap the optimizer likes by less than this is not worth an email. The
# Lineup page still shows it.
LINEUP_ALERT_MIN_GAIN = 2.0
# How many accounts one run will work through. A ceiling, not a target:
# each account costs a few cached Sleeper reads.
ALERT_RUN_LIMIT = 200
# And how long the whole pass may take. The scheduled job waits four
# minutes for an answer, so the pass stops itself before that rather
# than being cut off mid-send with nobody to report it. Whatever it did
# not reach this hour it reaches the next one: nothing here is stateful,
# and an alert already sent is claimed, so a repeat pass re-sends
# nothing.
ALERT_RUN_SECONDS = 180


def _alert_dedupe(*parts):
    """A short, stable key for one alert. Built from what the alert
    actually SAYS, so a new problem sends a new email and an unchanged
    one never sends a second."""
    raw = "|".join(str(p) for p in parts)
    return hashlib.sha256(raw.encode()).hexdigest()[:24]


def claim_alert(user_id, kind, dedupe_key):
    """True the first time this exact alert is claimed for this reader.

    The row goes in before the email goes out, so two runs overlapping
    cannot both send it."""
    if not DATABASE_URL:
        return False
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                "INSERT INTO sent_alerts (user_id, kind, dedupe_key) VALUES (%s, %s, %s) "
                "ON CONFLICT DO NOTHING", (int(user_id), kind, dedupe_key))
            claimed = cur.rowcount == 1
        conn.commit()
        return claimed
    except Exception:
        app.logger.exception("could not claim %s alert for %s", kind, user_id)
        return False
    finally:
        conn.close()


def release_alert(user_id, kind, dedupe_key):
    """Give the claim back, so a send that failed is retried on the next
    run instead of being remembered as delivered."""
    if not DATABASE_URL:
        return
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM sent_alerts WHERE user_id = %s AND kind = %s AND dedupe_key = %s",
                        (int(user_id), kind, dedupe_key))
        conn.commit()
    except Exception:
        app.logger.exception("could not release %s alert for %s", kind, user_id)
    finally:
        conn.close()


def _kickoff_dt(value):
    """A card's kickoff string as a naive UTC datetime, or None."""
    if not value:
        return None
    try:
        return _as_naive_utc(datetime.fromisoformat(str(value).strip().replace("Z", "+00:00")))
    except (ValueError, TypeError):
        return None


def next_kickoff(plan):
    """When the first game a reader can still do something about starts.

    Only players who are not already locked count: a starter whose game
    has kicked off cannot be changed, so his kickoff is not a deadline
    any more."""
    soonest = None
    for row in (plan or {}).get("lineup") or []:
        player = row.get("player")
        if not player or player.get("locked"):
            continue
        when = _kickoff_dt(((player.get("game") or {}).get("kickoff")))
        if when and (soonest is None or when < soonest):
            soonest = when
    return soonest


def lineup_problems(plan):
    """What is wrong with this lineup, worst first.

    Each problem is (code, sentence). The code identifies the problem for
    deduplication -- it is what decides whether an email is new -- and the
    sentence is what the reader reads."""
    problems = []
    for row in (plan or {}).get("lineup") or []:
        slot, player = row.get("slot"), row.get("player")
        if not player:
            problems.append((f"empty:{slot}", f"Your {slot} slot is empty."))
            continue
        if player.get("locked"):
            continue
        note = player.get("value_note")
        if note == "out":
            title = ((player.get("injury") or {}).get("title") or "out").lower()
            problems.append((f"out:{player['sid']}", f"{player['name']} is starting at {slot} and is {title}."))
        elif note == "bye":
            problems.append((f"bye:{player['sid']}", f"{player['name']} is starting at {slot} and is on bye."))
        elif note in ("backup", "no_proj"):
            problems.append((f"noproj:{player['sid']}",
                             f"{player['name']} is starting at {slot} and nobody projects him to score."))
    for change in (plan or {}).get("changes") or []:
        if change.get("gain", 0) < LINEUP_ALERT_MIN_GAIN:
            continue
        over = (change.get("over") or {}).get("short") or "an empty slot"
        problems.append((f"swap:{change['start']['sid']}:{over}",
                         f"{change['start']['short']} projects {change['gain']} more than {over} at {change['slot']}."))
    return problems


def _lineup_alert(league, user_id, season, week, now=None):
    """(alert, reason). The alert, or None and the reason there is none.

    Every decision about sending lives here and nowhere else, so the dry
    run's explanation cannot drift from what the real run does: it is
    reading the same answer."""
    plan = build_lineup_plan(league, user_id, season, week)
    if not plan:
        return None, "no team in this league"
    if not plan.get("lineup_set"):
        return None, "no lineup set in Sleeper yet"
    problems = lineup_problems(plan)
    if not problems:
        return None, "nothing wrong with the lineup"
    kickoff = next_kickoff(plan)
    if not kickoff:
        return None, "no unplayed game to count down to"
    now = now or datetime.utcnow()
    hours = (kickoff - now).total_seconds() / 3600.0
    # Already started, or still days away: not a deadline to email about.
    if hours <= 0:
        return None, "every game has already kicked off"
    if hours > LINEUP_ALERT_LEAD_HOURS:
        return None, (f"{len(problems)} problem(s), but kickoff is {round(hours)}h away "
                      f"(waits until {LINEUP_ALERT_LEAD_HOURS}h)")
    codes = sorted(code for code, _ in problems)
    return {
        "kind": "lineup",
        "league_id": plan["league_id"], "league_name": plan["league_name"],
        "season": season, "week": week,
        "problems": problems, "hours": round(hours, 1), "kickoff": kickoff,
        "gain": plan.get("gain"), "plan": plan,
        "dedupe": _alert_dedupe("lineup", plan["league_id"], season, week, *codes),
    }, "sending"


def build_lineup_alert(league, user_id, season, week, now=None):
    """The lineup email for one league, or None when there is nothing to
    send: no problems, no deadline near, or no lineup at all."""
    return _lineup_alert(league, user_id, season, week, now=now)[0]


def _waiver_alert(league, user_id, season, week):
    """(alert, reason), for the same reason the lineup one comes in
    pairs: the dry run explains itself by reading the real answer."""
    plan = build_waiver_targets(league, user_id, season, week)
    if not plan:
        return None, "no team in this league"
    if not plan.get("next_week"):
        return None, f"week {plan['asked_week']} is still being played, so waivers are not open"
    groups = []
    for group in plan.get("groups") or []:
        healthy = [t for t in group["targets"] if not t.get("stash")]
        if healthy:
            groups.append({"label": group["label"], "targets": healthy})
    if not groups:
        return None, "no free agent worth a claim"
    targets = [t for g in groups for t in g["targets"]]
    return {
        "kind": "waivers",
        "league_id": plan["league_id"], "league_name": plan["league_name"],
        "season": season, "week": plan["week"],
        "groups": groups, "targets": targets, "drop": plan.get("drop"), "plan": plan,
        # One per league per week, however many times the job runs.
        "dedupe": _alert_dedupe("waivers", plan["league_id"], season, plan["week"]),
    }, "sending"


def build_waiver_alert(league, user_id, season, week):
    """The waiver email for one league, or None.

    Sent once a week, when the week's football is over and a claim can
    actually be made -- which is what waiver_target_week already knows."""
    return _waiver_alert(league, user_id, season, week)[0]


# --- how an email looks ----------------------------------------------
#
# Mail clients are a decade behind browsers: no flexbox, no grid, style
# blocks stripped by some, images blocked by default until a reader
# trusts the sender. So this is tables and inline styles, and every
# number is text -- an email with images turned off still reads as the
# whole message, with only the logo missing.
EMAIL_NAVY = "#10233F"
EMAIL_FLAME = "#F2542D"
EMAIL_BG = "#eef1f5"
EMAIL_PAPER = "#ffffff"
EMAIL_INK = "#16202c"
EMAIL_MUTED = "#6b7683"
EMAIL_LINE = "#e4e8ee"
EMAIL_SOFT = "#f6f8fa"
EMAIL_GOOD = "#1e7a4a"
EMAIL_BAD = "#b23b2e"
EMAIL_WIDTH = 600
EMAIL_FONT = ("-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,"
              "Helvetica,Arial,sans-serif")


def _alert_button(href, label):
    return (f'<table role="presentation" cellpadding="0" cellspacing="0" border="0" '
            f'style="margin:18px 0 4px;"><tr><td style="background:{EMAIL_FLAME};'
            f'border-radius:8px;"><a href="{href}" style="display:inline-block;'
            f'padding:12px 26px;color:#ffffff;text-decoration:none;font-weight:700;'
            f'font-size:15px;font-family:{EMAIL_FONT};">{html.escape(label)}</a>'
            f'</td></tr></table>')


def _email_who(card):
    """What to call a player. A card built from a thin source may carry
    only the short form, and an email that says "start  instead of" is
    worse than no email."""
    return (card or {}).get("name") or (card or {}).get("short") or ""


def _email_matchup(player):
    """"vs BUF" / "@ BUF", or the team alone when the week has no game
    attached to read."""
    game = (player or {}).get("game") or {}
    opp = game.get("opp")
    team = (player or {}).get("team") or ""
    if not opp:
        return html.escape(str(team))
    return f'{html.escape(str(team))} {"vs" if game.get("home") else "@"} {html.escape(str(opp))}'


def _email_player_cell(player, label, label_colour, slot=None):
    """One side of a swap: who, where he plays, and what he is worth."""
    if not player:
        return (f'<div style="font-size:11px;font-weight:700;letter-spacing:.06em;'
                f'color:{label_colour};">{label}</div>'
                f'<div style="font-size:15px;font-weight:700;color:{EMAIL_INK};">An empty slot</div>')
    bits = [_email_matchup(player)]
    if player.get("proj") is not None:
        bits.append(f'{player["proj"]} proj')
    if player.get("grade"):
        bits.append(f'grade {html.escape(str(player["grade"]))}')
    if player.get("recent_avg") is not None and player.get("recent_n"):
        bits.append(f'{player["recent_avg"]} avg last {player["recent_n"]}')
    pos = html.escape(str(player.get("position") or ""))
    where = f' &middot; {html.escape(str(slot))}' if slot else ""
    return (f'<div style="font-size:11px;font-weight:700;letter-spacing:.06em;'
            f'color:{label_colour};">{label}</div>'
            f'<div style="font-size:15px;font-weight:700;color:{EMAIL_INK};padding:1px 0;">'
            f'{html.escape(_email_who(player))}</div>'
            f'<div style="font-size:12px;color:{EMAIL_MUTED};line-height:1.55;">'
            f'{pos}{where}<br>{" &middot; ".join(bits)}</div>')


def _email_swap_card(change):
    """A change to make, as a card: the slot, what it is worth, both
    players side by side, and the reason underneath."""
    start, over = change.get("start"), change.get("over")
    return (
        f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" '
        f'style="border:1px solid {EMAIL_LINE};border-radius:10px;margin:0 0 10px;'
        f'background:{EMAIL_PAPER};"><tr><td style="padding:11px 14px 0;">'
        f'<span style="background:{EMAIL_NAVY};color:#ffffff;font-size:11px;font-weight:700;'
        f'letter-spacing:.06em;padding:3px 8px;border-radius:5px;">'
        f'{html.escape(str(change.get("slot") or ""))}</span>'
        f'<span style="color:{EMAIL_FLAME};font-weight:800;font-size:14px;">'
        f'&nbsp;&nbsp;+{change.get("gain")} projected</span>'
        f'</td></tr><tr><td style="padding:8px 14px 12px;">'
        f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
        f'<td width="50%" style="vertical-align:top;padding-right:8px;">'
        + _email_player_cell(start, "START", EMAIL_GOOD) +
        f'</td><td width="50%" style="vertical-align:top;padding-left:8px;'
        f'border-left:1px solid {EMAIL_LINE};">'
        + _email_player_cell(over, "INSTEAD OF", EMAIL_BAD,
                             change.get("over_slot") if change.get("over_slot") != change.get("slot") else None) +
        f'</td></tr></table>'
        + (f'<div style="font-size:12px;color:{EMAIL_MUTED};line-height:1.6;padding-top:9px;">'
           f'{html.escape(str(change.get("why")))}</div>' if change.get("why") else "")
        + '</td></tr></table>')


def _email_flag_row(sentence):
    """Something wrong that is not a swap -- out, on bye, nobody
    projecting him, an empty slot."""
    return (f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" '
            f'style="margin:0 0 8px;background:#fff5f2;border-left:3px solid {EMAIL_FLAME};'
            f'border-radius:0 8px 8px 0;"><tr><td style="padding:10px 13px;font-size:13px;'
            f'color:{EMAIL_INK};line-height:1.5;">{html.escape(sentence)}</td></tr></table>')


def _email_hero(big, caption):
    """The one number the message is about, given room to be read."""
    return (f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" '
            f'style="background:{EMAIL_SOFT};border:1px solid {EMAIL_LINE};border-radius:10px;'
            f'margin:0 0 14px;"><tr><td style="padding:13px 15px;">'
            f'<span style="font-size:27px;font-weight:800;color:{EMAIL_FLAME};'
            f'letter-spacing:-.01em;">{html.escape(str(big))}</span>'
            f'<span style="font-size:13px;color:{EMAIL_MUTED};">&nbsp;{html.escape(caption)}</span>'
            f'</td></tr></table>')


def _email_shell(eyebrow, headline, sub, inner, cta_href, cta_label):
    """The branded frame every alert arrives in.

    Self-contained: it opens and closes its own centred table, so the
    unsubscribe block that gets appended after it lines up underneath
    rather than having to be threaded through."""
    return (
        f'<div style="background:{EMAIL_BG};padding:22px 10px;font-family:{EMAIL_FONT};">'
        f'<table role="presentation" align="center" width="{EMAIL_WIDTH}" cellpadding="0" '
        f'cellspacing="0" border="0" style="width:{EMAIL_WIDTH}px;max-width:100%;margin:0 auto;">'
        # Header: the mark, the name, and what this message is.
        f'<tr><td style="background:{EMAIL_NAVY};padding:15px 20px;border-radius:12px 12px 0 0;">'
        f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
        f'<td style="vertical-align:middle;">'
        f'<img src="{SITE_URL}/icon-192.png" width="26" height="26" alt="" '
        f'style="border-radius:6px;vertical-align:middle;display:inline-block;">'
        f'<span style="color:#ffffff;font-weight:800;font-size:14px;letter-spacing:.1em;'
        f'vertical-align:middle;">&nbsp;&nbsp;STREAKPROS</span></td>'
        f'<td align="right" style="vertical-align:middle;color:#93a4bd;font-size:12px;">'
        f'{html.escape(eyebrow)}</td></tr></table></td></tr>'
        # Headline.
        f'<tr><td style="background:{EMAIL_PAPER};padding:22px 20px 0;">'
        f'<div style="font-size:20px;font-weight:800;color:{EMAIL_INK};line-height:1.3;">'
        f'{html.escape(headline)}</div>'
        f'<div style="font-size:13px;color:{EMAIL_MUTED};padding-top:5px;line-height:1.55;">'
        f'{sub}</div></td></tr>'
        # Body.
        f'<tr><td style="background:{EMAIL_PAPER};padding:16px 20px 0;">{inner}</td></tr>'
        # Call to action.
        f'<tr><td style="background:{EMAIL_PAPER};padding:0 20px 24px;'
        f'border-radius:0 0 12px 12px;">{_alert_button(cta_href, cta_label)}</td></tr>'
        f'</table></div>')


def render_lineup_alert(alert, username):
    """(subject, text, html) for a lineup alert.

    The swaps come from the plan rather than the problem sentences, so
    the email can show both players, what each is projected for, the
    grade and the recent form -- the sentence alone was one line with a
    single number in it, which is a poor use of the one email a week
    somebody actually opens."""
    league = alert["league_name"]
    count = len(alert["problems"])
    hours = int(round(alert["hours"]))
    subject = (f"Lineup alert: {count} thing{'' if count == 1 else 's'} to fix in {league}"
               f" before kickoff")
    link = f"{SITE_URL}/lineup?league={alert['league_id']}"
    plan = alert.get("plan") or {}
    # Swaps have both players behind them; everything else (out, bye,
    # empty slot, nobody projecting him) only ever had a sentence.
    swaps = [c for c in (plan.get("changes") or [])
             if (c.get("gain") or 0) >= LINEUP_ALERT_MIN_GAIN]
    flags = [line for code, line in alert["problems"] if not code.startswith("swap:")]
    gain = plan.get("gain")

    lines = [line for _code, line in alert["problems"]]
    def _bits(card):
        """The parenthesised detail after a name, with nothing invented:
        a card that does not carry a projection says so by leaving it
        out, not by printing "None proj"."""
        out = []
        if card.get("position"):
            out.append(str(card["position"]))
        if card.get("proj") is not None:
            out.append(f"{card['proj']} proj")
        if card.get("grade"):
            out.append(f"grade {card['grade']}")
        return f" ({', '.join(out)})" if out else ""

    text_rows = []
    for c in swaps:
        start, over = c.get("start") or {}, c.get("over") or {}
        row = f"  {c.get('slot')}: start {_email_who(start)}{_bits(start)}\n"
        row += (f"      instead of {_email_who(over)}{_bits(over)}"
                if over else "      into an empty slot")
        text_rows.append(row + f"  -> +{c.get('gain')}")
    text = (f"Hi {username},\n\n"
            f"Week {alert['week']} in {league} kicks off in about {hours} hours, "
            f"and your lineup has {count} thing{'' if count == 1 else 's'} worth a look."
            + (f"\n\nThere are {gain} projected points on the table." if gain else "")
            + ("\n\nChanges to make:\n" + "\n".join(text_rows) if text_rows else "")
            + ("\n\nAlso worth knowing:\n" + "\n".join(f"  - {f}" for f in flags) if flags else "")
            + f"\n\nSee the whole lineup, and what to do about it:\n{link}\n")

    inner = ""
    if gain:
        inner += _email_hero(f"+{gain}", "projected points on the table")
    if swaps:
        inner += (f'<div style="font-size:11px;font-weight:700;letter-spacing:.08em;'
                  f'color:{EMAIL_MUTED};padding:2px 0 8px;">CHANGES TO MAKE</div>')
        inner += "".join(_email_swap_card(c) for c in swaps)
    if flags:
        inner += (f'<div style="font-size:11px;font-weight:700;letter-spacing:.08em;'
                  f'color:{EMAIL_MUTED};padding:12px 0 8px;">ALSO WORTH KNOWING</div>')
        inner += "".join(_email_flag_row(f) for f in flags)
    if not inner:
        inner = "".join(_email_flag_row(line) for line in lines)
    body = _email_shell(
        eyebrow=f"Week {alert['week']}",
        headline=f"{count} thing{'' if count == 1 else 's'} to fix before kickoff",
        sub=(f'Hi {html.escape(str(username))} &mdash; <b>{html.escape(league)}</b> '
             f'kicks off in about {hours} hours.'),
        inner=inner, cta_href=link, cta_label="Open your lineup")
    return subject, text, body


def render_waiver_alert(alert, username):
    """(subject, text, html) for a waiver alert: the top three of each
    group, ranked, and nothing else."""
    league = alert["league_name"]
    best = alert["targets"][0]
    subject = f"Waivers are open in {league}: {best['name']} tops the board"
    link = f"{SITE_URL}/waivers?league={alert['league_id']}"
    drop = alert.get("drop")
    drop_line = (f"\n\nRoom for one: {drop['name']} is the weakest player on your bench."
                 if drop else "")
    text_groups = []
    html_groups = []
    for group in alert["groups"]:
        rows = [f"  {t['rank']}. {t['position']} {t['name']} ({t['team']}) - score {t['score']}. {t['why']}"
                for t in group["targets"]]
        text_groups.append(group["label"] + "\n" + "\n".join(rows))
        items = "".join(
            f'<tr><td width="30" style="vertical-align:top;padding:9px 0 9px 12px;'
            f'font-size:16px;font-weight:800;color:{EMAIL_FLAME};">{t["rank"]}</td>'
            f'<td style="padding:9px 12px 9px 4px;border-bottom:1px solid {EMAIL_LINE};">'
            f'<div style="font-size:15px;font-weight:700;color:{EMAIL_INK};">'
            f'{html.escape(str(t["name"]))}</div>'
            f'<div style="font-size:12px;color:{EMAIL_MUTED};line-height:1.55;">'
            f'{html.escape(str(t["position"]))} &middot; {html.escape(str(t["team"] or ""))} '
            f'&middot; score {t["score"]}<br>{html.escape(str(t["why"]))}</div></td></tr>'
            for t in group["targets"])
        html_groups.append(
            f'<div style="font-size:11px;font-weight:700;letter-spacing:.08em;'
            f'color:{EMAIL_MUTED};text-transform:uppercase;padding:12px 0 6px;">{html.escape(group["label"])}</div>'
            f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" '
            f'style="border:1px solid {EMAIL_LINE};border-radius:10px;">{items}</table>')
    text = (f"Hi {username},\n\n"
            f"Waivers for week {alert['week']} in {league}. The top "
            f"{WAIVER_GROUP_SIZE} of each group, on this season's form:\n\n"
            + "\n\n".join(text_groups)
            + drop_line
            + f"\n\nSee the board:\n{link}\n")
    inner = (_email_hero(html.escape(str(best["name"])), "tops the board this week")
             + "".join(html_groups)
             + (f'<table role="presentation" width="100%" cellpadding="0" cellspacing="0" '
                f'border="0" style="margin:12px 0 0;background:{EMAIL_SOFT};border-radius:8px;">'
                f'<tr><td style="padding:10px 13px;font-size:12px;color:{EMAIL_MUTED};">'
                f'Room for one: <b style="color:{EMAIL_INK};">{html.escape(drop["name"])}</b> '
                f'is the weakest player on your bench.</td></tr></table>' if drop else ""))
    body = _email_shell(
        eyebrow=f"Week {alert['week']}",
        headline="Waivers are open",
        sub=(f'Hi {html.escape(str(username))} &mdash; the top {WAIVER_GROUP_SIZE} of each '
             f'group in <b>{html.escape(league)}</b>, on this season\'s form.'),
        inner=inner, cta_href=link, cta_label="See your waiver targets")
    return subject, text, body


ALERT_RENDERERS = {"lineup": render_lineup_alert, "waivers": render_waiver_alert}


def alert_recipients(limit=None):
    """Every account that could get an alert: has an email, has not
    unsubscribed, has a Sleeper username, and wants at least one kind.

    The switches are filtered here rather than per-alert so an account
    that wants nothing costs no Sleeper calls at all."""
    if not DATABASE_URL:
        return []
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT id, email, username, sleeper_username,
                          COALESCE(alert_lineup, TRUE) AS alert_lineup,
                          COALESCE(alert_waivers, TRUE) AS alert_waivers
                     FROM users
                    WHERE email IS NOT NULL AND email <> ''
                      AND COALESCE(newsletter_opt_in, TRUE)
                      AND sleeper_username IS NOT NULL AND sleeper_username <> ''
                      AND (COALESCE(alert_lineup, TRUE) OR COALESCE(alert_waivers, TRUE))
                 ORDER BY id
                    LIMIT %s""",
                (int(limit or ALERT_RUN_LIMIT),))
            return [dict(r) for r in cur.fetchall()]
    except Exception:
        app.logger.exception("could not read alert recipients")
        return []
    finally:
        conn.close()


def _leagues_for_user(row):
    """The synced leagues of one account, by its stored Sleeper username."""
    try:
        user_id, _name = get_user_id(row["sleeper_username"])
    except Exception:
        return None, []
    if not user_id:
        return None, []
    synced = get_synced_league_ids(row["id"]) or set()
    if not synced:
        return user_id, []
    try:
        leagues = get_leagues(user_id, SEASON) or []
    except Exception:
        return user_id, []
    return user_id, [lg for lg in leagues if lg.get("league_id") in synced]


def alerts_for_user(row, season, week, now=None, notes=None):
    """Every alert this account should get right now, across its
    leagues. Reads only; sends nothing.

    `notes`, when a list is passed in, collects one line per league per
    kind saying what was decided and why. That is what makes a dry run
    answerable: "nothing was sent" and "nothing could be found" look
    identical from outside, and only one of them is working."""
    sleeper_id, leagues = _leagues_for_user(row)
    if not sleeper_id:
        if notes is not None:
            notes.append({"user_id": row["id"], "note": "no Sleeper account found for that username"})
        return []
    if not leagues:
        if notes is not None:
            notes.append({"user_id": row["id"], "note": "no synced league for this season"})
        return []
    out = []
    for league in leagues:
        name = league.get("name") or league.get("league_id")
        for kind, want, builder in (
                ("lineup", row.get("alert_lineup"),
                 lambda lg: _lineup_alert(lg, sleeper_id, season, week, now=now)),
                ("waivers", row.get("alert_waivers"),
                 lambda lg: _waiver_alert(lg, sleeper_id, season, week))):
            if not want:
                if notes is not None:
                    notes.append({"user_id": row["id"], "league": name, "kind": kind, "note": "turned off"})
                continue
            try:
                alert, reason = builder(league)
            except Exception as e:
                app.logger.exception("%s alert failed for %s", kind, row["id"])
                alert, reason = None, f"failed: {type(e).__name__}"
            if notes is not None:
                notes.append({"user_id": row["id"], "league": name, "kind": kind, "note": reason})
            if alert:
                out.append(alert)
    return out


def send_alert(row, alert, dry=False):
    """One alert to one reader. Returns what happened: "sent",
    "duplicate", "dry", or a failure reason.

    The claim comes first and is given back when the send fails, so the
    only thing a mail outage costs is an hour."""
    username = row.get("username") or "there"
    render = ALERT_RENDERERS.get(alert["kind"])
    if not render:
        return "unknown kind"
    subject, text, body = render(alert, username)
    footer_text, footer_html = _email_footer(row["id"])
    if dry:
        return "dry"
    if not claim_alert(row["id"], alert["kind"], alert["dedupe"]):
        return "duplicate"
    sent, reason = send_email_reason(row["email"], subject, text + footer_text, body + footer_html)
    if not sent:
        release_alert(row["id"], alert["kind"], alert["dedupe"])
        return reason or "not sent"
    return "sent"


def run_alerts(season=None, week=None, limit=None, dry=False, now=None):
    """One pass over every account that could get an alert. Returns a
    summary the scheduled job can read at a glance."""
    info = get_current_week_info()
    season = _safe_int(season if season is not None else info["season"], int(SEASON))
    week = _safe_int(week if week is not None else info["week"], 1)
    now = now or datetime.utcnow()
    summary = {"season": season, "week": week, "checked": 0, "sent": 0, "duplicates": 0,
               "failed": 0, "dry": bool(dry), "stopped_early": False, "alerts": []}
    # A dry run is for answering "why did nobody get anything?", so it
    # carries the reasons. A real run does not: the answer there is the
    # alerts themselves.
    notes = [] if dry else None
    if dry:
        summary["notes"] = notes
    deadline = time.time() + ALERT_RUN_SECONDS
    for row in alert_recipients(limit):
        if time.time() > deadline:
            # Out of time, not out of readers. Said plainly, because a
            # run that quietly did half its work looks exactly like one
            # that had half as much to do.
            summary["stopped_early"] = True
            break
        summary["checked"] += 1
        for alert in alerts_for_user(row, season, week, now=now, notes=notes):
            result = send_alert(row, alert, dry=dry)
            if result == "sent":
                summary["sent"] += 1
            elif result == "duplicate":
                summary["duplicates"] += 1
            elif result != "dry":
                summary["failed"] += 1
            summary["alerts"].append({
                "user_id": row["id"], "kind": alert["kind"],
                "league": alert["league_name"], "result": result,
                "detail": (len(alert.get("problems") or []) if alert["kind"] == "lineup"
                           else len(alert.get("targets") or [])),
            })
    return summary


@app.route("/api/send-alerts", methods=["GET", "POST"])
def api_send_alerts():
    """The scheduled job's one entry point. Runs the whole pass and
    reports it; `dry=1` builds every alert and sends none, which is how
    this is checked on the live server without mailing anybody."""
    if not _secret_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    dry = request.args.get("dry") in ("1", "true", "yes")
    try:
        summary = run_alerts(
            season=request.args.get("season", type=int),
            week=request.args.get("week", type=int),
            limit=request.args.get("limit", type=int),
            dry=dry)
    except Exception as e:
        app.logger.exception("alert run failed")
        return jsonify({"ok": False, "error": str(e)}), 500
    return jsonify({"ok": True, **summary})


# --- Waiver targets ---------------------------------------------------------
#
# Who is free in your league and worth adding. Everything here is read
# from data the site already holds: the league's rosters say who is
# taken, the stat table says what a player has been doing lately, and
# Sleeper's projections say what he is expected to do next.
#
# Two rules decide the whole page, and both come from what went wrong on
# the Lineup before it: a player is only a target if he is actually
# available and actually playing, and no number on the row is invented.
# A player nobody projects and who has not played is not ranked at all.
WAIVER_FORM_GAMES = 3
# What the two halves of a target's score weigh. Recent form leads
# because it is what has actually happened; the projection follows
# because it is the only part that knows about this week's opponent.
WAIVER_FORM_WEIGHT = 0.6
WAIVER_PROJ_WEIGHT = 0.4
# Three per group, ranked. A waiver claim is one decision, usually with
# one spot to make room in: a list of a dozen names is a list nobody
# reads to the bottom. Three is short enough to act on.
WAIVER_GROUP_SIZE = 3
# A target has to be worth the claim. Below this, a week's points are
# inside the noise of any bench player already on the roster.
WAIVER_MIN_SCORE = 4.0
# The three lists the page shows, in order. Kickers and defences are
# kept apart from the skill players rather than mixed in with them,
# because they are never competing for the same roster spot -- a kicker
# ranked above a running back would be a comparison nobody is making.
WAIVER_GROUPS = (
    ("skill", "Best available", ("QB", "RB", "WR", "TE")),
    ("K", "Kickers", ("K",)),
    ("DEF", "D/ST", ("DEF",)),
)
WAIVER_GROUP_OF = {pos: key for key, _label, positions in WAIVER_GROUPS for pos in positions}
WAIVER_POSITIONS = tuple(WAIVER_GROUP_OF)


def waiver_target_week(season, week):
    """The week a claim made now would actually be for.

    Waivers clear in midweek, so once every game of the current week is
    final the useful question is already about the next one. Asking the
    scoreboard rather than the calendar means this is right in a week
    moved for weather as well as an ordinary one."""
    try:
        games = live_team_games(season, week) or {}
    except Exception:
        return week
    if not games:
        return week
    if all((g or {}).get("status") == "final" for g in games.values()):
        return week + 1
    return week


def _rostered_ids(rosters):
    """Every player id held by anyone in the league, bench, injured
    reserve and taxi squad included. A player stashed on someone's IR is
    not a free agent, and listing him as one sends the reader to a claim
    that cannot be made."""
    taken = set()
    for roster in rosters or []:
        for key in ("players", "starters", "reserve", "taxi"):
            for sid in (roster.get(key) or []):
                if sid and sid not in ("0", 0):
                    taken.add(sid)
    return taken


def _league_positions(league):
    """Which positions this league can actually start, so a two-quarterback
    league sees quarterbacks and a league with no kicker slot never sees a
    kicker."""
    wanted = set()
    for slot in _lineup_slots(league):
        for pos in SLOT_ELIGIBLE.get(slot, (slot,)):
            wanted.add(pos)
    return {p for p in WAIVER_POSITIONS if p in wanted} or set(WAIVER_POSITIONS)


def _waiver_score(form, proj):
    """What a free agent is worth adding, from what he has been doing and
    what he is projected to do. Both halves are printed on the row, so
    this number can always be checked against them."""
    return round(WAIVER_FORM_WEIGHT * (form or 0.0) + WAIVER_PROJ_WEIGHT * (proj or 0.0), 1)


def _waiver_reason(row):
    """One plain sentence for why this player is on the list."""
    bits = []
    if row["form"] and row["form_games"]:
        games = row["form_games"]
        bits.append(f"{row['form']} a game over his last {games} this season"
                    if games > 1 else f"{row['form']} in his only game this season")
    # Snap share is a fact about a player on the field. A defence is the
    # whole unit and a kicker is never on a snap count, so neither gets a
    # percentage that would read as one.
    if row["snap_pct"] and row["position"] not in ("K", "DEF"):
        bits.append(f"{row['snap_pct']}% of his team's snaps")
    if row["rank_label"]:
        bits.append(f"{row['rank_label']} on the season")
    if row["proj"]:
        opponent = f" against {row['opponent']}" if row.get("opponent") else ""
        bits.append(f"projected {row['proj']}{opponent}")
    if row["injury"] and row["injury"].get("title"):
        bits.append(row["injury"]["title"].lower())
    if not bits:
        return ""
    sentence = "; ".join(bits)
    return sentence[0].upper() + sentence[1:] + "."


def build_waiver_targets(league, user_id, season, week):
    """The best free agents in one league, and the weakest player on the
    reader's own roster to make room with.

    None when the reader has no team in the league."""
    league_id = league["league_id"]
    rosters = get_rosters(league_id) or []
    mine = next((r for r in rosters if r.get("owner_id") == user_id), None)
    if mine is None:
        return None
    all_players = get_all_players() or {}
    scoring = league.get("scoring_settings") or {}
    target_week = waiver_target_week(season, week)
    projections = get_week_projections(season, target_week)
    season_stats = get_season_stats(season) or {}
    taken = _rostered_ids(rosters)
    positions = _league_positions(league)
    try:
        live = live_team_games(season, target_week) or {}
    except Exception:
        live = {}
    espn_injuries_by_sid = _espn_injury_by_sid()

    rows = []
    for sid, p in all_players.items():
        if sid in taken or not isinstance(p, dict):
            continue
        position = p.get("position")
        if position not in positions:
            continue
        # No club means nobody's free agent -- he is out of the league.
        team = p.get("team")
        if not team:
            continue
        # A player his own club is not playing is not an add. The one
        # exception is a defence, which has no depth chart at all.
        if position != "DEF" and not streak_is_starter(p) and position != "K":
            depth = _safe_int(p.get("depth_chart_order"), 0)
            limit = STREAK_DEPTH.get(streak_position_group(position)) or 0
            if depth and limit and depth > limit + 1:
                continue
        injury = _merged_injury(p, espn_injuries_by_sid.get(sid))
        # No feed for the target week means no projection, not a stand-in
        # recent average: that is the very number the form column already
        # carries, and counting it twice would dress one fact up as two.
        proj = 0.0
        if projections:
            proj, _source = _player_projection(sid, position, projections, scoring,
                                               season, target_week, None, None)
        # This season only. Last year's form is not a reason to claim
        # anybody: a player who has not played this year has not shown
        # anything a waiver claim can be made on.
        recent = _player_recent_games(sid, season, WAIVER_FORM_GAMES, allow_prior_season=False)
        form = (recent or {}).get("avg") or 0.0
        # Nothing to show and nothing expected: not a target, and never a
        # row of zeroes on the page.
        if not form and not proj:
            continue
        score = _waiver_score(form, proj)
        if score < WAIVER_MIN_SCORE:
            continue
        stat_line = season_stats.get(sid) or {}
        game = live.get(team) or {}
        row = {
            "sid": sid, "position": position, "team": team,
            "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip() or sid,
            "short": f"{(p.get('first_name') or ' ')[0]}. {p.get('last_name', '')}".strip(),
            "photo": team_logo_url(team) if position == "DEF" else player_photo_url(sid),
            "is_team": position == "DEF",
            "form": round(form, 1), "form_games": (recent or {}).get("games") or 0,
            "proj": round(proj, 1), "score": score,
            "snap_pct": stat_line.get("snap_pct"),
            "games": stat_line.get("games") or 0,
            "rank_label": kdst_rank_label(sid, position, season),
            "opponent": game.get("opp"),
            "injury": injury,
            # An injured player can still be the right claim -- as a
            # stash, which is a different decision, and labelled as one.
            "stash": bool(injury and injury.get("tier") in ("out", "doubtful", "admin")),
        }
        row["why"] = _waiver_reason(row)
        rows.append(row)

    # Three lists of three, each ranked. Within a list the healthy come
    # first, best score first; a stash is worth a place only when there
    # are not three players who can actually help this week.
    rows.sort(key=lambda r: (r["stash"], -r["score"], -(r["snap_pct"] or 0)))
    groups = []
    for key, label, group_positions in WAIVER_GROUPS:
        if not (set(group_positions) & positions):
            continue
        picked = [r for r in rows if WAIVER_GROUP_OF.get(r["position"]) == key][:WAIVER_GROUP_SIZE]
        for i, row in enumerate(picked, 1):
            row["rank"] = i
        if picked:
            groups.append({"key": key, "label": label, "targets": picked})
    targets = [r for g in groups for r in g["targets"]]

    # Who to drop for them: the weakest player on the roster who is not
    # in the lineup, by the same score the targets are ranked on, so the
    # two numbers are comparable.
    starters = {s for s in (mine.get("starters") or []) if s and s not in ("0", 0)}
    bench = []
    for sid in (mine.get("players") or []):
        if sid in starters:
            continue
        p = all_players.get(sid) or {}
        proj = 0.0
        if projections:
            proj, _source = _player_projection(sid, p.get("position"), projections, scoring,
                                               season, target_week, None, None)
        recent = _player_recent_games(sid, season, WAIVER_FORM_GAMES, allow_prior_season=False)
        form = (recent or {}).get("avg") or 0.0
        bench.append({
            "sid": sid, "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip() or sid,
            "short": f"{(p.get('first_name') or ' ')[0]}. {p.get('last_name', '')}".strip(),
            "position": p.get("position"), "team": p.get("team"),
            "photo": team_logo_url(p.get("team")) if p.get("position") == "DEF" else player_photo_url(sid),
            "form": round(form, 1), "proj": round(proj, 1), "score": _waiver_score(form, proj),
        })
    bench.sort(key=lambda b: b["score"])
    drop = bench[0] if bench else None

    return {
        "league_id": league_id, "league_name": league.get("name") or "League",
        "season": season, "week": target_week, "asked_week": week,
        "next_week": target_week != week,
        "groups": groups, "targets": targets, "drop": drop,
        "free_agents": len(rows), "shown": len(targets), "positions": sorted(positions),
        "group_size": WAIVER_GROUP_SIZE,
        "projections_available": bool(projections),
        "sleeper_url": f"https://sleeper.com/leagues/{league_id}/players",
    }


@app.route("/waivers")
def waivers_page():
    """The best free agents in your league. StreakPros+ (sign-in while the
    gate is off), same as the Lineup."""
    username, user_id, leagues = _account_leagues_for_pages()
    info = get_current_week_info()
    week = request.args.get("week", default=info["week"], type=int)
    season = info["season"]
    league = _pick_league(leagues)
    unlocked = plus_unlocked()
    plan, error = None, None
    if unlocked and league and user_id:
        try:
            ensure_schedule_synced(season)
            plan = build_waiver_targets(league, user_id, season, week)
            if plan is None:
                error = "You don't have a team in that league."
        except Exception as e:
            app.logger.warning("waivers page: %s", e)
            error = "Sleeper didn't answer just now. Try again in a moment."
    return render_template_string(
        WAIVERS_HTML, plan=plan, error=error, leagues=leagues, league=league, week=week, season=season,
        username=username, unlocked=unlocked, gate=gate_kind())


# --- Kickers and D/ST: the fantasy points board -----------------------------
#
# FantasyCalc prices quarterbacks, runners, receivers and tight ends and
# nothing else, which is why Rankings has never listed a kicker or a
# defence: there is no value to rank them by. What there IS, for both, is
# the thing that actually decides a fantasy week -- points scored -- and
# this site already stores every one of them, week by week, for every
# player Sleeper reports.
#
# So these two positions get ranked on what they have actually done.
# Nothing is projected, modelled or weighted here: a row is the sum of
# real weeks, and the order is that sum. That is what makes it checkable
# against any box score, and it is the only honest way to rank a position
# whose week-to-week scoring is as noisy as these two.
KDST_POSITIONS = ("K", "DEF")
# The ranges a board can be scored over. Rankings shows all four at once
# as its own sortable columns (see rankings_points_rows), so these are
# the keys kdst_board validates against rather than tabs anybody clicks.
KDST_RANGES = ("season", "avg", "last4", "week")
KDST_RANGE_LABEL = {k: k for k in KDST_RANGES}
KDST_LAST_N = 4
_kdst_board_cache = {}


# The little bar chart beside a row: four weeks at a glance. Heights are
# scaled against a good week rather than the player's own best, so two
# rows can be compared to each other -- a kicker's flat four and a
# defence's one big week look different, which is the point of it.
KDST_SPARK_FULL = 20.0
KDST_SPARK_MIN, KDST_SPARK_MAX = 3, 15


def _kdst_spark(recent):
    """Bar heights in pixels for the last few weeks' scores."""
    out = []
    for value in recent or []:
        share = max(0.0, min(1.0, float(value) / KDST_SPARK_FULL))
        out.append(int(round(KDST_SPARK_MIN + share * (KDST_SPARK_MAX - KDST_SPARK_MIN))))
    return out


def _kdst_weeks(stat_line):
    """{week: points} for one player, with the weeks in order."""
    weeks = (stat_line or {}).get("weeks") or {}
    return {int(w): float(p) for w, p in weeks.items() if isinstance(p, (int, float))}


def kdst_measure(weeks, total, games, rng, week=None, latest_week=None):
    """What this player is worth under the range being shown, and the
    weeks that number came out of. One place, so the board, the ranks and
    anything that quotes a rank can never disagree about what "best"
    meant.

    "Last 4" is the season's last four weeks, not the player's last four
    games. For a kicker who played twice in September and was cut, those
    are not the same thing, and the second reading would rank him on
    football played a month ago."""
    if rng == "avg":
        return (round(total / games, 2) if games else 0.0), sorted(weeks)
    if rng == "last4":
        end = int(latest_week or (max(weeks) if weeks else 0))
        recent = [w for w in sorted(weeks) if w > end - KDST_LAST_N]
        return round(sum(weeks[w] for w in recent), 2), recent
    if rng == "week":
        wk = int(week or 0)
        return (round(weeks[wk], 2) if wk in weeks else 0.0), ([wk] if wk in weeks else [])
    return round(total, 2), sorted(weeks)


def kdst_board(season, position="K", rng="season", week=None, scoring=None, cache=_kdst_board_cache):
    """Every kicker, or every defence, ranked by the points they have
    actually scored.

    A row carries the total, the per-game average, the last four weeks
    and this week's game, so the same board answers "who is best" and
    "who is hot" without a second query."""
    season = _safe_int(season, int(SEASON))
    position = position if position in KDST_POSITIONS else "K"
    rng = rng if rng in KDST_RANGE_LABEL else "season"
    scoring = normalize_scoring(scoring or current_scoring())
    week = _safe_int(week, 0)
    key = (season, position, rng, week, scoring)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]

    stats = get_season_stats(season, scoring) or {}
    players = get_all_players() or {}
    try:
        live = live_team_games(season, week) if week else {}
    except Exception:
        live = {}
    # The last week anyone has actually played, which is what "the last
    # four weeks" is counted back from -- not today's date, and not the
    # week this player last appeared in.
    latest_week = 0
    for line in stats.values():
        for w in (line or {}).get("weeks") or {}:
            latest_week = max(latest_week, _safe_int(w, 0))
    rows = []
    for sid, p in players.items():
        if not isinstance(p, dict) or p.get("position") != position:
            continue
        line = stats.get(sid)
        if not line:
            continue
        weeks = _kdst_weeks(line)
        games = len(weeks)
        if not games:
            continue
        total = round(sum(weeks.values()), 2)
        recent = [round(weeks[w], 1) for w in sorted(weeks)[-KDST_LAST_N:]]
        value, counted = kdst_measure(weeks, total, games, rng, week, latest_week)
        # A range nobody played in is not a zero, it is an absence. A
        # kicker who did not play this week does not belong on a board
        # of this week's kickers at all.
        if rng in ("week", "last4") and not counted:
            continue
        team = p.get("team")
        game = live.get(team) if team else None
        name = (f"{p.get('first_name', '')} {p.get('last_name', '')}".strip()
                or (TEAM_NAMES.get(sid) if position == "DEF" else None) or sid)
        rows.append({
            "sid": sid, "name": name, "team": team, "position": position,
            # A defence is its club, so it wears the club's badge; a
            # kicker is a person and wears his own face.
            "photo": team_logo_url(team) if position == "DEF" else player_photo_url(sid),
            "is_team": position == "DEF",
            "games": games, "total": total,
            "avg": round(total / games, 2) if games else 0.0,
            "best": round(max(weeks.values()), 2),
            "last": round(weeks[max(weeks)], 2) if weeks else 0.0,
            "recent": recent, "spark": _kdst_spark(recent),
            "value": value, "counted": len(counted), "counted_weeks": counted,
            "opponent": (game or {}).get("opp"),
            "game_status": (game or {}).get("status"),
        })
    # Most points first; a tie goes to whoever needed fewer games for
    # them, which is the honest tiebreak on a points total.
    rows.sort(key=lambda r: (-r["value"], r["games"], r["name"]))
    for i, row in enumerate(rows, 1):
        row["rank"] = i
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


def kdst_rank_map(season, position, rng="season", cache={}):
    """{sleeper_id: rank} for one position, so a kicker or a defence can
    carry "K4" or "DST7" anywhere else on the site without every page
    rebuilding the board."""
    key = (int(season), position, rng, normalize_scoring(current_scoring()))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    try:
        board = kdst_board(season, position, rng)
    except Exception:
        board = []
    out = {r["sid"]: r["rank"] for r in board}
    cache[key] = {"data": out, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return out


def kdst_rank_label(sid, position, season=None):
    """"K4" or "DST7" for a player, or None when the position is neither
    or the season has no games for them yet."""
    if position not in KDST_POSITIONS:
        return None
    rank = kdst_rank_map(int(season or SEASON), position).get(sid)
    if not rank:
        return None
    return f"{'DST' if position == 'DEF' else 'K'}{rank}"


def rankings_points_rows(season, week):
    """Kickers and defences, shaped as Rankings rows.

    Rankings ranks on dynasty value and FantasyCalc prices four
    positions, so these two have none -- they are ranked on the points
    they have actually scored instead. That is a different number, so
    they carry `board: "points"` and the table gives them their own
    columns: the season's total, the average, the last four weeks and
    this week, each sortable, which is every view the old separate board
    offered and all of them at once.

    Every movement field is None on purpose. There is no value to have
    moved, so no arrow is drawn and the Trending tabs skip them."""
    out = []
    for position in KDST_POSITIONS:
        try:
            season_rows = kdst_board(season, position, "season", week)
            last4 = {r["sid"]: r["value"] for r in kdst_board(season, position, "last4", week)}
            this_week = {r["sid"]: r["value"] for r in kdst_board(season, position, "week", week)}
        except Exception:
            app.logger.warning("rankings: %s board unavailable", position)
            continue
        for r in season_rows:
            out.append({
                "sid": r["sid"], "photo": r["photo"], "name": r["name"],
                "position": position, "team": r["team"] or "FA",
                "board": "points", "is_rookie": False, "age": None,
                "games": r["games"], "fpts": r["total"], "fpts_per_game": r["avg"],
                "fpts_last4": last4.get(r["sid"], 0.0), "fpts_week": this_week.get(r["sid"], 0.0),
                "snap_pct": None,
                # Rank on points, within the position. It is what the #
                # column shows and what the table sorts by first.
                "position_rank": r["rank"], "overall_rank": r["rank"],
                "value": None, "tier": None,
                "rank_delta": None, "pos_rank_delta": None, "value_delta": None,
                "trend_30day": None,
            })
    return out


@app.route("/kickers-dst")
def kdst_page():
    """Kickers and defences live on Rankings now, as two more positions
    in its filter. Kept as a redirect so a link from before still lands
    somewhere useful."""
    position = (request.args.get("pos") or "K").strip().upper()
    if position not in KDST_POSITIONS:
        position = "K"
    return redirect(f"/rankings?pos={position}")


# --- Player bio and contract sheet ----------------------------------------
#
# "View bio" on a player page opens a sheet with the facts the site
# already holds (birth date, size, college, from Sleeper) and the
# contract, which comes from OverTheCap by way of nflverse's daily
# contracts release. That file is parquet, and reading it takes more
# memory than this server has to spare, so a GitHub Actions job
# (scripts/sync_contracts.py) reads it and posts the active rows here;
# see /api/sync-contracts. Nothing on a page fetches it.

CONTRACT_SOURCE_URL = "https://overthecap.com/"
CONTRACT_REFRESH_S = 6 * 3600
# OverTheCap's contract types, as a reader would say them.
CONTRACT_TYPE_LABELS = {
    "Drafted": "Rookie contract", "UDFA": "Undrafted free agent", "Extension": "Extension",
    "UFA": "Free agent", "SFA": "Free agent", "RFA": "Restricted free agent",
    "ERFA": "Exclusive-rights free agent", "Franchise": "Franchise tag",
    "Transition": "Transition tag", "Practice": "Practice squad",
}
# The parts of a cap number, in the order OverTheCap names them.
CAP_PARTS = (
    ("prorated_bonus", "Signing bonus"), ("option_bonus", "Option bonus"),
    ("roster_bonus", "Roster bonus"), ("base_salary", "Base salary"),
    ("workout_bonus", "Workout bonus"), ("per_game_roster_bonus", "Per-game roster bonus"),
    ("other_bonus", "Other bonus"),
)
_contracts_cache = {}


def _f(x):
    try:
        return float(x) if x is not None and x != "" else 0.0
    except (TypeError, ValueError):
        return 0.0


def compact_contract_row(raw):
    """One OverTheCap row (as nflverse publishes it), reduced to what
    the sheet shows. Returns None for a row with no name."""
    if not isinstance(raw, dict) or not (raw.get("player") or "").strip():
        return None
    seasons = []
    for s in raw.get("season_history") or []:
        if not isinstance(s, dict):
            continue
        year = _safe_int(s.get("year"), None)
        if year is None:      # the "Total" row
            continue
        row = {"year": year, "team": s.get("team")}
        for key, _label in CAP_PARTS:
            row[key] = round(_f(s.get(key)), 6)
        row["guaranteed_salary"] = round(_f(s.get("guaranteed_salary")), 6)
        row["cap_number"] = round(_f(s.get("cap_number")), 6)
        row["cap_percent"] = round(_f(s.get("cap_percent")), 6)
        row["cash_paid"] = round(_f(s.get("cash_paid")), 6)
        seasons.append(row)
    seasons.sort(key=lambda r: r["year"])
    history = [h for h in (raw.get("contract_history") or []) if isinstance(h, dict)]
    current = next((h for h in history if (h.get("status") or "") == "Active"), history[-1] if history else {})
    return {
        "player": raw["player"].strip(), "position": (raw.get("position") or "").upper(),
        "team": raw.get("team"), "year_signed": _safe_int(raw.get("year_signed"), None),
        "years": _safe_int(raw.get("years"), None), "value": _f(raw.get("value")),
        "apy": _f(raw.get("apy")), "guaranteed": _f(raw.get("guaranteed")),
        "contract_type": current.get("contract_type") or "",
        "gsis_id": (raw.get("gsis_id") or "").strip() or None,
        "otc_id": _safe_int(raw.get("otc_id"), None), "player_page": raw.get("player_page"),
        "height": raw.get("height"), "weight": raw.get("weight"), "college": raw.get("college"),
        "draft_year": _safe_int(raw.get("draft_year"), None), "draft_round": _safe_int(raw.get("draft_round"), None),
        "draft_overall": _safe_int(raw.get("draft_overall"), None), "draft_team": raw.get("draft_team"),
        "date_of_birth": raw.get("date_of_birth") or None,
        "seasons": seasons,
    }


def _contract_rows_from_db():
    """Every stored contract row, as compact dicts."""
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT data FROM player_contracts")
            out = []
            for r in cur.fetchall():
                d = r["data"]
                if isinstance(d, str):
                    d = json.loads(d)
                if isinstance(d, dict):
                    out.append(d)
            return out
    finally:
        conn.close()


def contract_key(r):
    return r.get("gsis_id") or f"otc:{r.get('otc_id')}:{normalize_name(r['player'])}"


def dedupe_contract_rows(rows):
    """One row per player. OverTheCap occasionally lists two active
    deals for one player (two practice-squad signings in a season, say);
    keep the newest, and the larger when signed the same year, since
    the table is keyed by player and the sheet shows one contract."""
    best = {}
    for r in rows:
        k = contract_key(r)
        cur = best.get(k)
        if cur is None or (r.get("year_signed") or 0, r.get("value") or 0) > (cur.get("year_signed") or 0, cur.get("value") or 0):
            best[k] = r
    return list(best.values())


def _store_contract_rows(rows, stamp=None):
    """Replace the table with these rows, in one transaction, so a
    reader never sees it half-written."""
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute("DELETE FROM player_contracts")
            psycopg2.extras.execute_values(
                cur,
                "INSERT INTO player_contracts (key, gsis_id, name_key, position, data, source_stamp) VALUES %s",
                [(contract_key(r), r["gsis_id"], normalize_name(r["player"]), r["position"],
                  json.dumps(r), stamp) for r in rows],
                page_size=500)
        conn.commit()
    finally:
        conn.close()
    _contracts_cache.clear()


def contracts_index(cache=_contracts_cache):
    """{'by_gsis': {...}, 'by_name': {name_key: [rows]}}, cached."""
    now = time.time()
    if cache.get("index") and now - cache.get("time", 0) < CONTRACT_REFRESH_S:
        return cache["index"]
    by_gsis, by_name = {}, {}
    try:
        rows = _contract_rows_from_db()
    except Exception:
        app.logger.exception("contracts: could not read player_contracts")
        rows = []
    for r in rows:
        if r.get("gsis_id"):
            by_gsis[r["gsis_id"]] = r
        by_name.setdefault(normalize_name(r["player"]), []).append(r)
    cache["index"] = {"by_gsis": by_gsis, "by_name": by_name, "count": len(rows)}
    cache["time"] = now
    return cache["index"]


def find_contract(p):
    """The OverTheCap row for a Sleeper player: by NFL (gsis) id when
    both sides carry one, else by name, with position breaking a tie."""
    if not isinstance(p, dict):
        return None
    idx = contracts_index()
    gsis = (p.get("gsis_id") or "").strip()
    if gsis and gsis in idx["by_gsis"]:
        return idx["by_gsis"][gsis]
    name = normalize_name(f"{p.get('first_name', '')} {p.get('last_name', '')}".strip())
    cands = idx["by_name"].get(name) or []
    if len(cands) == 1:
        return cands[0]
    pos = (p.get("position") or "").upper()
    same = [c for c in cands if c.get("position") == pos]
    return same[0] if len(same) == 1 else None


def money_m(x, none="—"):
    """Millions of dollars the way a contract is spoken: $67.5m, $8.68m,
    $7.8k. Trailing zeros go, so $22.5m is not $22.50m."""
    if x is None:
        return none
    x = float(x)
    if abs(x) >= 1:
        s = f"{x:.2f}".rstrip("0").rstrip(".")
        return f"${s}m"
    if abs(x) >= 0.001:
        s = f"{x * 1000:.1f}".rstrip("0").rstrip(".")
        return f"${s}k"
    return "$0"


def _nickname_abbr(nick):
    """'Lions' -> 'DET'. OverTheCap names the drafting club by nickname,
    and an old one for a club that has moved or renamed."""
    if not nick:
        return None
    nick = str(nick).strip()
    old = {"Redskins": "WAS", "Football Team": "WAS", "Oilers": "TEN", "Rams": "LAR",
           "Chargers": "LAC", "Raiders": "LV"}
    if nick in old:
        return old[nick]
    for abbr, full in TEAM_NAMES.items():
        if full.split(" ")[-1] == nick:
            return abbr
    return nick


def _whole_age(birth):
    try:
        y, m, d = [int(x) for x in str(birth)[:10].split("-")]
        today = date.today()
        return today.year - y - ((today.month, today.day) < (m, d)), date(y, m, d)
    except (ValueError, TypeError):
        return None, None


def contract_summary(c, season=None):
    """What the sheet says about a contract, every number formatted."""
    if not c:
        return None
    season = _safe_int(season if season is not None else SEASON, int(SEASON))
    seasons = c.get("seasons") or []
    # Paid years: a void year carries a cap number and no money.
    paid = [s for s in seasons if s.get("cash_paid", 0) > 0 or s.get("base_salary", 0) > 0]
    until = max((s["year"] for s in paid), default=None)
    if until is None and c.get("year_signed") and c.get("years"):
        until = c["year_signed"] + c["years"] - 1
    yrs = c.get("years")
    line = f"{yrs} yr{'s' if yrs != 1 else ''}, {money_m(c.get('value'))}" if yrs else money_m(c.get("value"))
    if c.get("apy"):
        line += f" ({money_m(c['apy'])}/yr)"
    out = {
        "line": line,
        "until": f"Signed until {until}" if until else None,
        "type": CONTRACT_TYPE_LABELS.get(c.get("contract_type") or "", None),
        "source": c.get("player_page") or CONTRACT_SOURCE_URL,
        "cap": None,
        "guarantees": None,
    }
    this = next((s for s in seasons if s["year"] == season), None)
    if this and this.get("cap_number", 0) > 0:
        parts = [(label, this.get(key, 0)) for key, label in CAP_PARTS if this.get(key, 0) > 0]
        parts.sort(key=lambda t: -t[1])
        total = this["cap_number"]
        out["cap"] = {
            "year": season, "label": f"{season} cap hit",
            "hit": money_m(total),
            "pct": (f"{this['cap_percent'] * 100:.1f}% of cap" if this.get("cap_percent") else None),
            "parts": [{"label": label, "amount": money_m(v), "share": round(v / total, 4)} for label, v in parts],
        }
    if c.get("value"):
        g = c.get("guaranteed") or 0
        out["guarantees"] = {
            "total": money_m(c["value"]), "at_signing": money_m(g),
            "share": round(min(1.0, g / c["value"]), 4) if c["value"] else 0,
        }
    return out


def player_bio(sid, season=None):
    """Everything the sheet shows for one player, or None if Sleeper
    has never heard of them."""
    p = _players_or_empty().get(str(sid))
    if not isinstance(p, dict):
        return None
    c = find_contract(p)
    birth = p.get("birth_date") or (c or {}).get("date_of_birth")
    age, born = _whole_age(birth)
    status = (p.get("status") or "").strip()
    tone = "good" if status == "Active" else ("bad" if status in (
        "Injured Reserve", "Physically Unable to Perform", "Non Football Injury", "Suspended") else "")
    height = format_height(p.get("height")) or (c or {}).get("height")
    weight = p.get("weight") or (c or {}).get("weight")
    college = p.get("college") or (c or {}).get("college")
    draft = None
    if c and c.get("draft_year") and c.get("draft_round") and c.get("draft_overall"):
        draft = (f"{c['draft_year']} Round {c['draft_round']} Pick {c['draft_overall']}"
                 f" by {_nickname_abbr(c.get('draft_team')) or '?'}")
    elif c and c.get("draft_year") and c.get("contract_type") == "UDFA":
        draft = f"{c['draft_year']} Undrafted"
    return {
        "sid": str(sid),
        "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip(),
        "photo": player_photo_url(sid),
        "team": p.get("team"), "position": p.get("position"),
        "status": status or None, "status_tone": tone,
        "age": age, "born": born.strftime("%b %-d, %Y") if born else None,
        "height": height, "weight": f"{weight} lbs" if weight else None,
        "college": college, "draft": draft,
        "contract": contract_summary(c, season),
    }


@app.route("/api/player-bio")
def api_player_bio():
    sid = (request.args.get("sid") or "").strip()
    bio = player_bio(sid) if sid else None
    if not bio:
        return jsonify({"ok": False, "error": "unknown player"}), 404
    return jsonify({"ok": True, "bio": bio})


@app.route("/api/sync-contracts", methods=["POST"])
def api_sync_contracts():
    """The contracts job posts nflverse's active rows here (JSON, gzip
    optional). Secret-protected like every job endpoint."""
    if not _secret_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    body = request.get_data()
    if body[:2] == b"\x1f\x8b":
        body = gzip.decompress(body)
    try:
        payload = json.loads(body.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as e:
        return jsonify({"ok": False, "error": f"bad body: {e}"}), 400
    raw_rows = payload.get("rows") if isinstance(payload, dict) else payload
    if not isinstance(raw_rows, list):
        return jsonify({"ok": False, "error": "rows missing"}), 400
    rows = dedupe_contract_rows(r for r in (compact_contract_row(x) for x in raw_rows) if r)
    if len(rows) < 500:
        # A near-empty file is a broken upstream, not an empty league;
        # keep what we have.
        return jsonify({"ok": False, "error": f"only {len(rows)} rows, keeping the current table"}), 400
    stamp = (payload.get("stamp") if isinstance(payload, dict) else None) or None
    _store_contract_rows(rows, stamp)
    return jsonify({"ok": True, "stored": len(rows), "stamp": stamp})


@app.route("/api/contracts-status")
def api_contracts_status():
    if not _secret_ok():
        return jsonify({"ok": False, "error": "unauthorized"}), 401
    idx = contracts_index()
    return jsonify({"ok": True, "rows": idx["count"], "with_gsis": len(idx["by_gsis"])})


@app.route("/api/player-search")
def api_player_search():
    q = request.args.get("q", "").strip()
    fmt = request.args.get("format", "1qb")
    mode = request.args.get("mode", "dynasty")
    teams = request.args.get("teams", default=12, type=int)
    if teams not in (8, 10, 12, 14):
        teams = 12
    if not q:
        return jsonify({"results": []})

    num_qbs = 2 if fmt == "superflex" else 1
    is_dynasty = mode != "redraft"
    fc = get_fantasycalc_values(num_qbs, is_dynasty, teams)
    all_players = get_all_players()
    q_low = q.lower()
    # Pick labels look like "2026 Mid 1st" -- they never contain the words
    # people actually type when looking for one. Treat a generic
    # "pick"/"draft" query as "show me picks" (for someone who doesn't
    # know their exact draft position yet), and "1.02"-style round.slot
    # shorthand as "give me that exact slot" (for someone who does),
    # synthesizing a value FantasyCalc doesn't publish directly.
    q_is_generic_pick = q_low in ("pick", "picks", "draft", "draft pick", "draft picks")
    slot_query = None if q_is_generic_pick else parse_pick_slot_query(q_low)
    is_pick_query = q_is_generic_pick or slot_query is not None

    results = []
    for sid, p in all_players.items():
        if p.get("position") not in POSITIONS:
            continue
        full = f"{p.get('first_name','')} {p.get('last_name','')}".strip()
        if q_low in full.lower():
            results.append({
                "sid": sid, "name": full, "position": p.get("position"), "team": p.get("team") or "FA",
                "photo": player_photo_url(sid), "value": fc["players"].get(sid, {}).get("value", 0),
            })

    if is_dynasty:
        if q_is_generic_pick:
            matched_picks = sorted(fc["picks"].values(), key=pick_sort_key)
            for pk in matched_picks:
                results.append({
                    "sid": pk["sid"], "name": pk["name"], "position": "PICK", "team": "",
                    "photo": PICK_ICON, "value": pk["value"],
                })
        elif slot_query:
            rnd, slot = slot_query
            for pk in exact_slot_picks(fc["picks"], teams, rnd, slot):
                results.append({
                    "sid": pk["sid"], "name": pk["name"], "position": "PICK", "team": "",
                    "photo": PICK_ICON, "value": pk["value"],
                })
        else:
            for pk in fc["picks"].values():
                if q_low in pk["name"].lower():
                    results.append({
                        "sid": pk["sid"], "name": pk["name"], "position": "PICK", "team": "",
                        "photo": PICK_ICON, "value": pk["value"],
                    })

    if is_pick_query:
        # Chronological order from above (year -> round -> tier), not
        # relevance/value -- that's the whole point of "give me picks in
        # order" instead of highest-value-first.
        return jsonify({"results": results[:30]})

    results.sort(key=lambda r: (not r["name"].lower().startswith(q_low), -(r["value"] or 0), r["name"]))
    return jsonify({"results": results[:10]})


def _resolve_scores_username():
    """The username to cross-reference for "your players in this game" --
    an explicit ?u= wins, otherwise a signed-in account's saved Sleeper
    username (same auto-load convention League Manager already uses)."""
    username = request.args.get("u", "").strip()
    if not username and current_user.is_authenticated and current_user.sleeper_username:
        username = current_user.sleeper_username
    return username


def _annotate_my_players(games, username):
    """Mutates each game card in place, adding my_home_players/
    my_away_players -- only does real work (and only for a signed-in
    account with leagues already synced on League Manager) so a
    request with no username attached costs nothing extra."""
    if not username or not current_user.is_authenticated:
        return
    league_ids = get_synced_league_ids(current_user.id)
    if not league_ids:
        return
    try:
        by_team = get_my_players_by_team(username, league_ids)
    except Exception:
        return
    for g in games:
        g["my_home_players"] = by_team.get(g["home"]["abbr"], [])
        g["my_away_players"] = by_team.get(g["away"]["abbr"], [])


# Position order for a roster list, so it reads the way a lineup card
# does rather than the order leagues happened to be synced in.
MY_PLAYER_POS_ORDER = ("QB", "RB", "WR", "TE", "K", "DEF",
                       "DL", "LB", "DB", "IDP")


def _my_players_projection(players, season, week):
    """Attach this week's PPR projection to each entry, in place.

    PPR rather than each league's own scoring on purpose: this panel
    spans every league the reader syncs, and they do not agree. One
    honest common yardstick beats a number that is right for whichever
    league happened to be listed first."""
    if not players or not season or not week:
        return
    try:
        projections = get_week_projections(season, week)
    except Exception:
        return
    for p in players:
        raw = projections.get(str(p.get("sid"))) or {}
        pts = raw.get("pts_ppr") if isinstance(raw, dict) else None
        p["proj"] = round(float(pts), 1) if isinstance(pts, (int, float)) else None


def _my_players_sorted(players):
    """Best first, then by position, then by name -- a stable order that
    puts the players worth knowing about at the top."""
    def key(p):
        pos = (p.get("position") or "").upper()
        order = MY_PLAYER_POS_ORDER.index(pos) if pos in MY_PLAYER_POS_ORDER else 99
        return (-(p.get("proj") or 0.0), order, p.get("name") or "")
    return sorted(players or [], key=key)


def _my_players_for_game(detail, username, season=None, week=None):
    """Same lookup as _annotate_my_players but shaped for a single game's
    detail dict ({"home": [...], "away": [...]} or None) -- used by the
    /game page's "Your Players In This Game" panel."""
    if not username or not current_user.is_authenticated:
        return None
    league_ids = get_synced_league_ids(current_user.id)
    if not league_ids:
        return None
    try:
        by_team = get_my_players_by_team(username, league_ids)
    except Exception:
        return None
    home_abbr = detail.get("home", {}).get("abbr")
    away_abbr = detail.get("away", {}).get("abbr")
    home_players = by_team.get(home_abbr, []) if home_abbr else []
    away_players = by_team.get(away_abbr, []) if away_abbr else []
    if not home_players and not away_players:
        return None
    for side in (home_players, away_players):
        _my_players_projection(side, season, week)
    home_players = _my_players_sorted(home_players)
    away_players = _my_players_sorted(away_players)
    return {"home": home_players, "away": away_players}


# How many players per team the /scores PREVIEW row carries. That row
# shows a top 10 and links to the full board, so it only needs enough per
# team that whichever single day the visitor selects still has ten real
# names to draw from -- not the whole slate, which would mean baking
# hundreds of rows into a page that displays ten of them.
#
# The full /performances board passes per_team=None and scores everyone
# who played. This cap is a payload budget for one preview, never a limit
# on who gets rated.
PERFORMERS_PER_TEAM = 5
_week_performers_cache = {}


def get_week_performers(season, week, cache=_week_performers_cache, allow_fetch=True,
                        per_team=PERFORMERS_PER_TEAM):
    """The best fantasy performances of one week, as display-ready rows.

    Returns a list of dicts sorted best-first, each carrying the player,
    their team and opponent, the fantasy points, the headline stat line,
    and a full performance grade (see grade_performance).

    Built from get_live_week_stats rather than the database, so the board
    moves while games are being played instead of waiting for the next
    sync. Keyed by team so the /scores page can filter the week down to
    the teams that played on whichever date the visitor has selected --
    that filtering happens on the client on purpose, because the visitor's
    browser is the only place that knows their real local calendar day
    (ESPN's kickoff times are UTC, so a Sunday night game is already
    Monday in UTC for anyone west of the UK).

    TTL 45s, matching the live stats fetch underneath it -- no point
    caching the derived board longer than its own input.

    allow_fetch=False makes this cache-only. /scores renders with it off
    on purpose: the board is worth baking in when it's already warm (no
    second request, no flash of empty content), but it is never worth
    holding up the whole scoreboard behind a live Sleeper call. This app
    has already shipped that exact bug once, in get_season_stats, and it
    took the site down -- the page always renders first."""
    season, week = _safe_int(season, int(SEASON)), _safe_int(week, 1)
    key = (season, week, per_team, current_scoring())
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 45:
        return entry["data"]

    live = get_live_week_stats(season, week, allow_fetch=allow_fetch)
    if not live:
        # Keep serving the last good board rather than blanking the
        # section on one failed upstream call -- or, when this is a
        # non-blocking caller and nothing is cached yet, an empty board
        # the client will fill in for itself a moment later.
        return entry["data"] if entry else []

    all_players = get_all_players()
    by_team = {}
    for sid, rec in live.items():
        p = all_players.get(sid)
        if not p:
            continue
        pos = p.get("position")
        team = p.get("team")
        if not pos or pos not in SCORED_POSITIONS or not team:
            continue
        by_team.setdefault(team, []).append((rec["pts"], sid, p, rec))

    rows = []
    for team, entries in by_team.items():
        # Ranked within the team by raw points only to decide WHO makes a
        # capped preview -- the board itself is then ordered by score
        # below. Points are the right cut for "this team's most notable
        # days"; score is the right order for "best performances", and
        # conflating the two is what put a 20-point quarterback above a
        # 15-point tight end who had the better game.
        entries.sort(key=lambda e: -e[0])
        sched = get_schedule_for_team_week(season, week, team)
        opponent = (sched or {}).get("opponent")
        is_home = (sched or {}).get("home")
        for pts, sid, p, rec in (entries if per_team is None else entries[:per_team]):
            pos = p["position"]
            rows.append({
                "sid": sid,
                "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
                "position": pos,
                "team": team,
                "opponent": opponent,
                # "@ IND" vs "vs TB", the way the reference board reads.
                "vs_label": (None if not opponent else
                             (f"vs {opponent}" if is_home else f"@ {opponent}")),
                "photo": player_photo_url(sid),
                "logo": team_logo_url(team),
                "fpts": pts,
                "stat_line": build_stat_line(pos, rec.get("stats")),
                "grade": grade_performance(pos, pts, season),
            })

    # Ordered by the SCORE, not by raw points. That's the whole point of
    # scoring positionally: 15 points is a better game for a tight end
    # than 20 is for a quarterback, and a board that claims to rank
    # performances has to say so. Raw points break exact ties.
    rows.sort(key=lambda r: (-r["grade"]["score"], -r["fpts"]))
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


# The full stat grid on a performance page, per position group. Every
# entry is (Sleeper stat key, short label). Only keys actually present in
# the payload are rendered, so this can list more than any one game will
# ever fill without producing a grid full of blanks -- and a stat Sleeper
# renames or stops sending simply disappears instead of erroring.
_STAT_GRID_FIELDS = {
    "QB": [
        ("pass_yd", "PYDS"), ("pass_td", "PTD"), ("pass_int", "INT"),
        ("pass_cmp", "CMP"), ("pass_att", "ATT"), ("pass_lng", "LNG"),
        ("pass_sack", "SACK"), ("rush_att", "CAR"), ("rush_yd", "RUYDS"),
        ("rush_td", "RUTD"), ("fum_lost", "FL"),
    ],
    "RB": [
        ("rush_yd", "RUYDS"), ("rush_td", "RUTD"), ("rush_att", "CAR"),
        ("rush_ypa", "YPC"), ("rush_lng", "LNG"), ("rec", "REC"),
        ("rec_yd", "REYDS"), ("rec_td", "RETD"), ("rec_tgt", "TGT"),
        ("fum_lost", "FL"),
    ],
    "WR": [
        ("rec_yd", "REYDS"), ("rec_td", "RETD"), ("rec", "REC"),
        ("rec_tgt", "TGT"), ("rec_ypr", "REAVG"), ("rec_lng", "LNG"),
        ("rec_yar", "YAC"), ("rec_air_yd", "AIRYD"), ("rush_att", "CAR"),
        ("rush_yd", "RUYDS"), ("rush_td", "RUTD"), ("fum_lost", "FL"),
    ],
}
_STAT_GRID_FIELDS["TE"] = _STAT_GRID_FIELDS["WR"]
_STAT_GRID_FIELDS["K"] = [
    ("fgm", "FG"), ("fga", "FGA"), ("fgm_lng", "LNG"), ("fgm_50p", "50+"),
    ("fgmiss", "MISS"), ("xpm", "XP"), ("xpa", "XPA"), ("xpmiss", "XPMISS"),
    ("fgm_pct", "FG%"),
]
_STAT_GRID_IDP = [
    ("idp_tkl_solo", "SOLO"), ("idp_tkl_ast", "AST"), ("idp_sack", "SACK"),
    ("idp_tkl_loss", "TFL"), ("idp_qb_hit", "QBH"), ("idp_int", "INT"),
    ("idp_pass_def", "PD"), ("idp_ff", "FF"), ("idp_fum_rec", "FR"),
]


def build_stat_grid(position, stats):
    """The full [(value, label), ...] grid for a performance page.

    Unlike build_stat_line (three headline numbers for a list row) this
    keeps zeros: on a detail page "0 FL" is information -- it says the
    player didn't fumble -- whereas on a one-line summary it would just
    be noise crowding out the stats that did happen."""
    stats = stats or {}
    fields = _STAT_GRID_FIELDS.get(position) or _STAT_GRID_IDP
    grid = []
    for key, label in fields:
        val = stats.get(key)
        if not isinstance(val, (int, float)):
            continue
        grid.append((round(val, 1) if isinstance(val, float) and val % 1 else int(val), label))
    return grid


def get_player_game_swing(sid, season, week):
    """How much this player's plays actually moved the result, in
    percentage points of win probability.

    Live: ESPN publishes the win-probability series play by play as the
    game happens, so this fills in during the game rather than the
    morning after. `total` is the sum across everything the player did,
    `best` the single play that moved it most.

    Returns None when ESPN carries no win-probability series for the
    game, which the page shows as an absent panel rather than a zero."""
    plays = [p for p in (get_player_espn_plays(sid, season, week) or [])
             if p.get("swing") is not None]
    if not plays:
        return None
    total = sum(p["swing"] for p in plays)
    gained = sum(p["swing"] for p in plays if p["swing"] > 0)
    return {
        "total": round(total, 1),
        "gained": round(gained, 1),
        "plays": len(plays),
        "per_play": round(total / len(plays), 2),
        "best": max(plays, key=lambda p: p["swing"]),
    }


# --- Per-play ratings and the quarter breakdown -------------------------
#
# One source, ESPN's own play-by-play, for every number on the
# performance page. The quarter panel used to read nflverse play-by-play
# and was empty for nearly everybody, because nflverse publishes a game
# only after the final whistle AND only once a nightly sync has run.
# ESPN's drive feed is live, covers every game, and already carries
# everything a play row needs -- the score at the time, the quarter and
# clock, the down and distance -- alongside the win-probability series
# that says how much each play mattered.

# How much one play was worth to the player it belonged to, in
# fantasy-point-shaped units. These weights only ever decide the
# RELATIVE size of one play against another (the quarter ratings are a
# split of the score the player actually earned, and the per-play rating
# is a curve over this value), so they are a weighting, not a scoring
# system, and they do not have to match any particular league's rules.
_PLAY_W_YARD = 0.1
_PLAY_W_PASS_YARD = 0.04
_PLAY_W_TD = 6.0
_PLAY_W_PASS_TD = 4.0
_PLAY_W_RECEPTION = 1.0
# Kicking, on the tiering every fantasy league uses -- a 50-yarder is
# worth more than a chip shot, and a miss is worth nothing rather than a
# negative (see _play_value_for on why nothing here goes below zero).
_PLAY_W_FG = 3.0
_PLAY_W_FG_40 = 4.0
_PLAY_W_FG_50 = 5.0
_PLAY_W_XP = 1.0
_PLAY_W_SACK = 4.0
_PLAY_W_INT = 6.0
_PLAY_W_FUMBLE = 4.0
_PLAY_W_TACKLE = 1.0

# The compressive curve that turns that value into the 0-10 rating shown
# beside a play: 10 * v / (v + K). A touchdown run lands in the high
# sixes, a chunk gain in the fours, a routine carry near one, and nothing
# ever reaches ten. K is fitted so the curve reproduces the per-play
# ratings the reference app publishes for a known game.
PLAY_RATING_K = 4.3

_PLAY_PASSER_RE = re.compile(
    r"(?:\d{1,2}-)?([A-Z][A-Za-z]?\.[A-Z][A-Za-z'\-]+)\s+(?:pass|sacked)\b")
_PLAY_RECEIVER_RE = re.compile(
    r"\bto\s+(?:\d{1,2}-)?([A-Z][A-Za-z]?\.[A-Z][A-Za-z'\-]+)")
_PLAY_PAREN_RE = re.compile(r"\(([^)]*)\)")
_FG_DISTANCE_RE = r"\s+(\d{1,3})\s+yard field goal"


def play_rating(value):
    """A play's 0-10 rating from its weighted value.

    The curve only approaches ten, and the rounding is held just below it
    as well, so a ten on this page always means the season-long rating it
    is reserved for rather than one very good snap."""
    v = max(0.0, float(value or 0))
    return min(9.9, round(10 * v / (v + PLAY_RATING_K), 1))


def play_role_for(text, name):
    """What THIS player did on this play, as a role name.

    One play is several different events depending on whose page you are
    reading it on. "22-D.Henry right tackle for 32 yards, TOUCHDOWN.
    8-E.McPherson extra point is GOOD, Center-C.Adomitis,
    Holder-R.Robbins" is a touchdown run for Henry, an extra point for
    McPherson, and nothing at all for the two men who got the ball to the
    tee -- and every one of those four names is in the same sentence.

    Resolving the role ONCE, here, is what keeps the number beside a play
    and the words describing it from disagreeing: both read this. It is
    also the fix for a kicker's page listing three touchdown runs, which
    is what "whoever is named, assume they carried it" produced.

    Returns None when the player is only incidentally named."""
    t = text or ""
    if not name or name not in t:
        return None
    esc = re.escape(name)
    low = t.lower()
    main = _primary_clause(t)
    main_low = main.lower()

    # --- kicking, read off the whole sentence ------------------------
    # The extra point is written AFTER the word "touchdown", which is
    # exactly where _primary_clause cuts, so the kicker is invisible to
    # anything that only looks at the primary clause.
    if re.search(r"(?:center|holder|snapper)-(?:\d{1,2}-)?" + esc, t, re.I):
        return "snap_hold"
    if re.search(esc + r"\s+kicks\b", t, re.I):
        return "kickoff"
    if re.search(esc + r"\s+punts\b", t, re.I):
        return "punt"
    if re.search(esc + _FG_DISTANCE_RE, t, re.I):
        return "field_goal"
    if re.search(esc + r"\s+extra point", t, re.I):
        return "extra_point"

    # --- passing and receiving ---------------------------------------
    m_pass = _PLAY_PASSER_RE.search(main)
    if m_pass and m_pass.group(1) == name:
        if "sacked" in main_low:
            return "sacked"
        if "intercepted" in main_low:
            return "interception_thrown"
        return "passer"
    m_rec = _PLAY_RECEIVER_RE.search(main)
    if m_rec and m_rec.group(1) == name:
        if "incomplete" in main_low or "intercepted" in main_low:
            return "target"
        return "receiver"

    # --- defence, read off the clauses ESPN writes it in --------------
    # Case-insensitively: ESPN writes these in capitals in a gamebook
    # sentence and in title case elsewhere, and both turn up.
    # ESPN writes the credited player as "K.Hamilton", "37-K.Hamilton"
    # or "BAL-37-K.Hamilton" depending on the feed, so team prefix and
    # jersey number are each optional AND stackable -- matching only one
    # of them read a fumble recovery as a carry.
    _CREDIT = r"\s+(?:[A-Z]{2,3}-)?(?:\d{1,2}-)?"
    if re.search(r"intercepted by" + _CREDIT + esc, main, re.I):
        return "interception"
    if re.search(r"recovered by" + _CREDIT + esc, main, re.I):
        return "fumble_recovery"
    if any(name in group for group in _PLAY_PAREN_RE.findall(main)):
        return "sack" if "sacked" in main_low else "tackle"

    # Anything left with the player's name in the play itself is a carry.
    return "rusher" if name in main else None


def _field_goal_distance(text, name):
    """The length of the kick, when the sentence says it."""
    m = re.search(re.escape(name) + _FG_DISTANCE_RE, text or "", re.I)
    return int(m.group(1)) if m else None


def _play_value_for(text, yards, scoring, name):
    """What `name` did on this play, as a non-negative weight.

    Returns 0 for a play the player was only incidentally named in, and
    never goes negative: a lost fumble or an interception is a real part
    of the game, but a negative weight would subtract from a quarter's
    share of a rating the player genuinely earned, which reads as
    nonsense on a bar chart."""
    role = play_role_for(text, name)
    if role is None:
        return 0.0
    t = text or ""
    low = t.lower()
    y = yards if isinstance(yards, (int, float)) else 0
    gain = max(0, int(y))
    # Read off the WHOLE sentence, not the primary clause -- the clause
    # splitter cuts at the word "touchdown" itself, so asking the clause
    # whether a touchdown happened always says no.
    td = "touchdown" in low

    if role == "field_goal":
        if "field goal is good" not in low:
            return 0.0
        d = _field_goal_distance(t, name) or 0
        return (_PLAY_W_FG_50 if d >= 50 else
                _PLAY_W_FG_40 if d >= 40 else _PLAY_W_FG)
    if role == "extra_point":
        return _PLAY_W_XP if "extra point is good" in low else 0.0
    # A kickoff, a punt, a snap and a hold are all real jobs and none of
    # them is scored in any fantasy league.
    if role in ("kickoff", "punt", "snap_hold"):
        return 0.0

    if role == "passer":
        return gain * _PLAY_W_PASS_YARD + (_PLAY_W_PASS_TD if td else 0.0)
    if role in ("sacked", "interception_thrown", "target"):
        return 0.0
    if role == "receiver":
        return gain * _PLAY_W_YARD + _PLAY_W_RECEPTION + (_PLAY_W_TD if td else 0.0)

    if role == "interception":
        return _PLAY_W_INT + (_PLAY_W_TD if td else 0.0)
    if role == "fumble_recovery":
        return _PLAY_W_FUMBLE + (_PLAY_W_TD if td else 0.0)
    if role == "sack":
        return _PLAY_W_SACK
    if role == "tackle":
        return _PLAY_W_TACKLE

    return gain * _PLAY_W_YARD + (_PLAY_W_TD if td else 0.0)


def play_headline_for(text, yards, scoring, name):
    """The play, described as THIS player's play.

    _play_headline titles a play by whoever it mainly belonged to, which
    is right on a game feed where every play appears once. On a player's
    own page every row is his row, so the same sentence has to be read
    from where he was standing -- otherwise a kicker's page reports the
    touchdown runs he kicked the extra points after."""
    role = play_role_for(text, name)
    t = text or ""
    low = t.lower()
    y = yards if isinstance(yards, (int, float)) else None
    td = "touchdown" in low

    if role == "field_goal":
        d = _field_goal_distance(t, name)
        made = "field goal is good" in low
        return (f"{d}-yd field goal" if d else "Field goal") + ("" if made else " missed")
    if role == "extra_point":
        return "Extra point" if "extra point is good" in low else "Extra point missed"
    if role == "kickoff":
        return "Kickoff"
    if role == "punt":
        return "Punt"
    if role == "snap_hold":
        return "Snap"

    if role == "passer":
        yd = _yard_prefix(y)
        if td:
            return f"{yd}TD pass"
        if _went_backwards(y, td):
            return _loss_headline(y)
        return f"{yd}pass" if yd else "Completion"
    if role == "sacked":
        return "Sacked"
    if role == "interception_thrown":
        return "Interception thrown"
    if role == "target":
        return "Incomplete"

    if role == "interception":
        return "Pick-six" if td else "Interception"
    if role == "fumble_recovery":
        return "Fumble returned for TD" if td else "Fumble recovery"
    if role == "sack":
        return "Sack"
    if role == "tackle":
        return "Tackle for loss" if (y is not None and y < 0) else "Tackle"

    # Receiver and rusher read the same either way, so the play's own
    # title is already the right one.
    return _play_headline(text, yards, scoring)


def _player_play_name(player):
    """The "D.Henry" form ESPN writes in play text."""
    first, last = (player or {}).get("first_name"), (player or {}).get("last_name")
    return f"{first[0]}.{last}" if first and last else None


def _win_probability_deltas(summary_json, is_home):
    """{play_id: percentage points this play moved the player's team's
    win probability}.

    ESPN records the home side's win probability after every play, so the
    swing a play produced is the difference from the play before it,
    flipped for an away player. The first entry has nothing before it and
    is skipped rather than measured against zero.

    This is what replaced nflverse EPA. EPA is the better measure in
    principle, but it is published the morning after a game and behind a
    nightly sync, so it could never put a number on a play while anyone
    was watching it. Win probability added answers nearly the same
    question -- how much did this actually change the game -- from a feed
    that updates during the game, and in a unit that reads on its own
    without a reference distribution."""
    raw = (summary_json or {}).get("winprobability") or []
    out, prev = {}, None
    for entry in raw:
        if not isinstance(entry, dict):
            continue
        pct = entry.get("homeWinPercentage")
        try:
            pct = float(pct)
        except (TypeError, ValueError):
            continue
        # ESPN gives a 0-1 fraction; a stray 0-100 payload is taken as-is.
        pct = pct * 100 if abs(pct) <= 1 else pct
        play_id = entry.get("playId")
        if prev is not None and play_id is not None:
            delta = pct - prev
            out[str(play_id)] = round(delta if is_home else -delta, 1)
        prev = pct
    return out


_espn_player_plays_cache = {}


def get_player_espn_plays(sid, season, week, cache=_espn_player_plays_cache):
    """Every play this player appeared in for one game, best first, from
    ESPN's live play-by-play.

    Each row carries what a play line needs to be read without the
    surrounding sentence: the quarter and clock, the down and distance,
    the score at that moment, a short headline, and a 0-10 rating.

    Returns [] rather than raising for a player with no team, a week
    that has not been synced, or an ESPN response that arrived empty --
    the panels above it simply do not render."""
    season, week = _safe_int(season, int(SEASON)), _safe_int(week, 1)
    key = (sid, season, week)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 45:
        return entry["data"]

    player = get_all_players().get(sid) or {}
    name, team = _player_play_name(player), player.get("team")
    sched = get_schedule_for_team_week(season, week, team) if (name and team) else None
    event_id = (sched or {}).get("espn_event_id")
    if not event_id:
        cache[key] = {"data": [], "time": now}
        _cache_trim(cache, CACHE_LIMIT_PER_USER)
        return []

    summary = espn_game_summary(event_id) or {}
    # A whole game is 150-190 plays; the default feed cap of 60 would
    # silently drop the first half.
    raw = extract_drive_plays(summary, limit=400)
    is_home = bool((sched or {}).get("home"))
    opponent = (sched or {}).get("opponent")

    # How much each play moved the result, from ESPN's own
    # win-probability series. This is the live replacement for nflverse
    # EPA: published play by play as the game happens rather than the
    # morning after, and in a unit that needs no reference pool to read
    # -- percentage points of win probability.
    swing_by_play = _win_probability_deltas(summary, is_home)

    out = []
    for play in raw:
        text = play.get("text") or ""
        if not name or name not in text:
            continue
        value = _play_value_for(text, play.get("yards"), play.get("scoring"), name)
        if value <= 0:
            # Nothing this player did on this play counts: a bystander
            # ESPN happened to name, an incompletion, a kickoff, or the
            # long snapper on somebody else's field goal. The scoringPlay
            # flag used to wave these through, which is how a kickoff
            # turned up on a kicker's highlight list.
            continue
        role = play_role_for(text, name)
        touchdown = ("touchdown" in text.lower()
                     and role in ("receiver", "rusher", "passer",
                                  "interception", "fumble_recovery"))
        qtr = play.get("period")
        clock = (play.get("clock") or "").strip()
        out.append({
            # What /play needs to find this exact snap again. A play
            # ESPN gave no id to simply isn't clickable, rather than
            # linking to a page that can't resolve it.
            "play_id": str(play.get("id")) if play.get("id") else None,
            "event_id": event_id,
            "qtr": qtr,
            "clock": clock,
            "down": play.get("down"),
            "ydstogo": play.get("distance"),
            "description": text,
            # Described from where THIS player was standing, not from
            # whoever the play mainly belonged to.
            "headline": play_headline_for(text, play.get("yards"),
                                          play.get("scoring"), name),
            "role": role,
            "yards_gained": play.get("yards"),
            # Only a touchdown THIS player was part of reads as one --
            # the kicker's extra point on somebody else's score is not
            # the kicker's touchdown.
            "touchdown": touchdown,
            # Did this player put points on the board? Touchdowns and
            # made kicks both did; a missed kick never reaches here,
            # since it is worth nothing and gets filtered out above.
            "scored": touchdown or role in ("field_goal", "extra_point"),
            "value": round(value, 2),
            "rating": play_rating(value),
            "swing": swing_by_play.get(str(play.get("id"))) if play.get("id") else None,
            "team": team,
            "opponent": opponent,
            "team_score": play.get("home_score") if is_home else play.get("away_score"),
            "opp_score": play.get("away_score") if is_home else play.get("home_score"),
        })

    out.sort(key=lambda p: (p["value"], p.get("qtr") or 0), reverse=True)
    cache[key] = {"data": out, "time": now}
    _cache_trim(cache, CACHE_LIMIT_PER_USER)
    return out


def get_player_quarter_breakdown(sid, season, week, score=None):
    """The player's game rating, split across the quarters they earned it
    in -- so the four bars add up to the one number at the top of the
    page rather than sitting on some unrelated scale.

    Weighting comes from ESPN's play-by-play, which is live and covers
    every game. Where ESPN also carries a win-probability series, the
    swing each play produced is the weight -- a truer measure of when a
    game was actually won than yardage is -- and where it does not, the
    play's own production stands in. Both are live; the split is on the
    same scale either way.

    Quarters run from the first one the player appeared in to the last,
    so a quarter they were on the field for but did nothing in shows as a
    zero -- which is information -- while quarters before they entered or
    after they left are simply absent, which is also information."""
    season, week = _safe_int(season, int(SEASON)), _safe_int(week, 1)
    if score is None:
        player = get_all_players().get(sid) or {}
        live = (get_live_week_stats(season, week, allow_fetch=False) or {}).get(sid) or {}
        score = (grade_performance(player.get("position"), live.get("pts"), season) or {}).get("score")
    if score is None:
        return []

    plays = get_player_espn_plays(sid, season, week)
    if not plays:
        return []

    # Swing first, production second -- and never a mix of the two in one
    # chart, since they are different units and a half-and-half split
    # would be measuring two things at once.
    swings = [p for p in plays if p.get("qtr") and p.get("swing") is not None]
    if swings and sum(abs(p["swing"]) for p in swings) > 0:
        source = "swing"
        weighted = [(int(p["qtr"]), abs(p["swing"])) for p in swings]
    else:
        source = "production"
        weighted = [(int(p["qtr"]), p["value"]) for p in plays if p.get("qtr")]

    weights = {}
    for qtr, w in weighted:
        weights[qtr] = weights.get(qtr, 0.0) + w

    if not weights:
        return []
    total = sum(weights.values())
    if total <= 0:
        return []

    lo, hi = min(weights), max(weights)
    out = []
    for q in range(lo, hi + 1):
        w = weights.get(q, 0.0)
        out.append({
            "qtr": q,
            "label": f"Q{q}" if q <= 4 else ("OT" if q == 5 else f"OT{q - 4}"),
            "rating": round(score * w / total, 2),
            "share": round(100 * w / total),
            "source": source,
        })

    # Rounding must not cost the player part of their score: the
    # leftover thousandths go to the biggest quarter, so the bars always
    # add back up to the number printed at the top of the page.
    drift = round(score - sum(q["rating"] for q in out), 2)
    if drift and out:
        top = max(out, key=lambda q: q["rating"])
        top["rating"] = round(top["rating"] + drift, 2)
    return out


def ordinal(n):
    """1st, 2nd, 3rd, 4th -- with the teens exception, which a bare
    last-digit rule gets wrong in both directions (11th not 11st, but
    21st not 21th). Registered as a Jinja filter because this was being
    written inline in templates, where the short version produced "22th".
    """
    try:
        n = int(n)
    except (TypeError, ValueError):
        return ""
    if 11 <= (n % 100) <= 13:
        return f"{n}th"
    return f"{n}{ {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th') }"


app.jinja_env.filters["ordinal"] = ordinal


def get_performance_detail(sid, season, week):
    """Everything the /performance page shows for one player-week, or
    None if that player has no stat line for the week.

    Reads the same live week stats the performer board does, so a page
    opened mid-game shows the same numbers the board just showed rather
    than a staler set from the database."""
    season, week = _safe_int(season, int(SEASON)), _safe_int(week, 1)
    live = get_live_week_stats(season, week)
    rec = (live or {}).get(sid)
    p = get_all_players().get(sid)
    if not rec or not p:
        return None

    position = p.get("position")
    team = p.get("team")
    stats = rec.get("stats") or {}
    fpts = rec.get("pts", 0)
    sched = get_schedule_for_team_week(season, week, team) if team else None

    # Snap share is real, already synced, and the closest thing this app
    # has to the tracking data a paid provider would sell -- how much of
    # the offense the player was actually on the field for.
    snap_pct = None
    off_snp, tm_off_snp = stats.get("off_snp"), stats.get("tm_off_snp")
    if isinstance(off_snp, (int, float)) and isinstance(tm_off_snp, (int, float)) and tm_off_snp:
        snap_pct = round(100 * off_snp / tm_off_snp)

    # One source for everything on this page: ESPN's own play-by-play,
    # which is live and covers every game.
    feed_plays = get_player_espn_plays(sid, season, week)
    swing = get_player_game_swing(sid, season, week)

    # Target share, same idea, for pass catchers.
    target_share = None
    tgt, team_tgt = stats.get("rec_tgt"), stats.get("tm_pass_att")
    if isinstance(tgt, (int, float)) and isinstance(team_tgt, (int, float)) and team_tgt:
        target_share = round(100 * tgt / team_tgt)

    return {
        "sid": sid,
        "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
        "position": position,
        "team": team,
        "photo": player_photo_url(sid),
        "season": season,
        "week": week,
        "fpts": fpts,
        "opponent": (sched or {}).get("opponent"),
        "is_home": (sched or {}).get("home"),
        "vs_label": (None if not sched else
                     (f"vs {sched['opponent']}" if sched.get("home") else f"@ {sched['opponent']}")),
        "team_score": (sched or {}).get("team_score"),
        "opp_score": (sched or {}).get("opp_score"),
        "game_status": (sched or {}).get("status"),
        "headline": build_stat_line(position, stats),
        "grid": build_stat_grid(position, stats),
        "snap_pct": snap_pct,
        "target_share": target_share,
        "score": grade_performance(position, fpts, season),
        # Fills in DURING the game now, rather than after it: ESPN
        # publishes its win-probability series play by play.
        "swing": swing,
        "feed_plays": feed_plays,
        "opp_logo": team_logo_url((sched or {}).get("opponent")) if sched else None,
        "team_logo": team_logo_url(team) if team else None,
    }


def get_player_season_log(sid, season, position, through_week=None):
    """This player's score for every week they've played this season, for
    the game-log chart -- so one performance can be read against their
    own body of work, not just against the league.

    Comes from the database rather than the live feed (only the current
    week is live, and a season-long chart needs all of them), with the
    live figure patched over the current week so the chart's last bar
    matches the score shown at the top of the page instead of lagging a
    sync behind."""
    season = _safe_int(season, int(SEASON))
    weeks = dict((get_season_stats(season).get(sid) or {}).get("weeks") or {})
    if through_week:
        live = get_live_week_stats(season, through_week, allow_fetch=False) or {}
        if sid in live:
            weeks[through_week] = live[sid].get("pts", 0)
    out = []
    for wk in sorted(weeks, key=lambda w: _safe_int(w, 0)):
        pts = weeks[wk]
        if not isinstance(pts, (int, float)):
            continue
        out.append({
            "week": _safe_int(wk, 0),
            "fpts": round(float(pts), 1),
            "score": grade_performance(position, pts, season)["score"],
        })
    return out


# The ranges the performance leaderboard offers, and how far back each
# one reaches. "All time" means every season actually synced into this
# database, not every season in NFL history -- the label says "all time"
# because that's what it is for this site, and the page says how many
# seasons that covers rather than implying more.
PERF_SCOPES = ("day", "week", "month", "season", "alltime")
# The earliest season this site ever backfills (see backfill-stats.yml,
# which seeds 2015 through the current year). Anchored to a START YEAR
# rather than "N seasons back" on purpose: a fixed offset silently stops
# meaning 2015 the moment a new season rolls over, so "all time" would
# quietly shed its oldest season every September.
PERF_EARLIEST_SEASON = 2015
_perf_board_cache = {}


def _month_weeks(season, month, season_type=2):
    """Which week numbers of `season` have games falling in `month`.

    Derived from the schedule table rather than assumed, because the NFL
    week grid doesn't line up with calendar months and drifts year to
    year."""
    if not DATABASE_URL:
        return []
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT DISTINCT week FROM nfl_schedule
                   WHERE season = %s AND season_type = %s
                     AND EXTRACT(MONTH FROM kickoff) = %s
                   ORDER BY week""",
                (season, season_type, month),
            )
            return [r["week"] for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


def _historical_performances(season, position=None, weeks=None):
    """Every scored performance from one season, out of the database.

    This is the path the month/season/all-time ranges use. It can't use
    the live feed -- that only covers the current week -- so it reads
    player_stats, which is exactly what that table is for."""
    all_players = get_all_players()
    stats = get_season_stats(season)
    week_filter = set(weeks) if weeks else None
    out = []
    for sid, stat in stats.items():
        p = all_players.get(sid)
        if not p:
            continue
        pos = p.get("position")
        if not pos or pos not in SCORED_POSITIONS:
            continue
        if position and pos != position:
            continue
        for week, fpts in (stat.get("weeks") or {}).items():
            wk = _safe_int(week, 0)
            if week_filter is not None and wk not in week_filter:
                continue
            if not isinstance(fpts, (int, float)):
                continue
            out.append({
                "sid": sid,
                "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
                "position": pos,
                "team": p.get("team") or "FA",
                "photo": player_photo_url(sid),
                "season": season,
                "week": wk,
                "fpts": round(float(fpts), 1),
                "grade": grade_performance(pos, fpts, season),
                # A historical row has no live stat payload to summarise,
                # so the points stand in for the line. The detail page
                # still shows the full breakdown when it's opened.
                "stat_line": [],
                "vs_label": None,
            })
    return out


def get_performance_board(scope="week", position=None, season=None, week=None,
                          order="top", limit=250, cache=_perf_board_cache):
    """The performance leaderboard, for any range and position.

    `scope` is one of PERF_SCOPES. "day" and "week" come from the live
    feed so an in-progress slate updates; everything longer comes from
    the database, because only the current week is ever live.

    `order` is "top" or "lowest". Lowest deliberately excludes anyone who
    scored nothing at all -- a list of players who didn't play isn't a
    list of bad performances, it's a list of absences, and it would be
    the same few hundred names every week."""
    season = _safe_int(season if season is not None else SEASON, int(SEASON))
    week = _safe_int(week if week is not None else 1, 1)
    scope = scope if scope in PERF_SCOPES else "week"
    order = "lowest" if order == "lowest" else "top"
    key = (scope, position, season, week, order, limit)
    now = time.time()
    entry = cache.get(key)
    # Live ranges go stale in 45s; historical ones can't change at all
    # until the next sync, so they're held for an hour.
    ttl = 45 if scope in ("day", "week") else 3600
    if entry and now - entry["time"] < ttl:
        return entry["data"]

    if scope in ("day", "week"):
        rows = [r for r in get_week_performers(season, week, per_team=None)
                if not position or r["position"] == position]
    elif scope == "month":
        info = get_current_week_info()
        month = None
        sched = None
        # Which calendar month the selected week sits in.
        for wk in (week,):
            games, _ = _week_games(season, wk, info.get("season_type", 2))
            if games and games[0].get("date"):
                month = _safe_int(str(games[0]["date"])[5:7], 0)
        weeks = _month_weeks(season, month) if month else [week]
        rows = _historical_performances(season, position, weeks or [week])
    elif scope == "season":
        rows = _historical_performances(season, position)
    else:
        rows = []
        for yr in range(season, PERF_EARLIEST_SEASON - 1, -1):
            rows.extend(_historical_performances(yr, position))

    if order == "lowest":
        rows = [r for r in rows if r["fpts"] > 0]
        rows.sort(key=lambda r: (r["grade"]["score"], r["fpts"]))
    else:
        rows.sort(key=lambda r: (-r["grade"]["score"], -r["fpts"]))

    rows = rows[:limit]
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


# Still-to-play first, finished last -- the same ordering the scores
# board uses, kept in one place so the two can't drift apart.
GAME_STATUS_ORDER = {"in_progress": 0, "scheduled": 1, "final": 2}


def _week_games(season, week, season_type=2):
    """Shared by /scores and /api/scoreboard so both build cards the same
    way. Returns (games, any_live) where games is a list of card dicts
    from espn_event_to_card, already filtered for malformed events."""
    data = espn_week_scoreboard(season, week, season_type)
    games = [c for c in (espn_event_to_card(ev) for ev in data.get("events", [])) if c]
    # Tag the week we asked for onto each card. The date strip labels every
    # tab "W1 / Sep 13", and a scoreboard event doesn't reliably carry its
    # own week number -- but the caller always knows which week it fetched.
    for g in games:
        g["week"] = week
        g["season"] = season
    any_live = any(g["status"] == "in_progress" for g in games)
    return games, any_live


# Conference and division for all 32 teams. Static on purpose: the NFL's
# alignment has not changed since 2002 and a realignment would be league
# news, not a silent data drift -- so hardcoding it is more reliable than
# scraping it, and it means standings work from the schedule table alone.
NFL_DIVISIONS = {
    "BAL": ("AFC", "North"), "CIN": ("AFC", "North"), "CLE": ("AFC", "North"), "PIT": ("AFC", "North"),
    "HOU": ("AFC", "South"), "IND": ("AFC", "South"), "JAX": ("AFC", "South"), "TEN": ("AFC", "South"),
    "BUF": ("AFC", "East"), "MIA": ("AFC", "East"), "NE": ("AFC", "East"), "NYJ": ("AFC", "East"),
    "DEN": ("AFC", "West"), "KC": ("AFC", "West"), "LV": ("AFC", "West"), "LAC": ("AFC", "West"),
    "CHI": ("NFC", "North"), "DET": ("NFC", "North"), "GB": ("NFC", "North"), "MIN": ("NFC", "North"),
    "ATL": ("NFC", "South"), "CAR": ("NFC", "South"), "NO": ("NFC", "South"), "TB": ("NFC", "South"),
    "DAL": ("NFC", "East"), "NYG": ("NFC", "East"), "PHI": ("NFC", "East"), "WAS": ("NFC", "East"),
    "ARI": ("NFC", "West"), "LAR": ("NFC", "West"), "SF": ("NFC", "West"), "SEA": ("NFC", "West"),
}
# Full names for the 32 teams. Same reasoning as the division map: stable
# league facts, and hardcoding them means a team page renders correctly
# even before any schedule has synced.
TEAM_NAMES = {
    "ARI": "Arizona Cardinals", "ATL": "Atlanta Falcons", "BAL": "Baltimore Ravens",
    "BUF": "Buffalo Bills", "CAR": "Carolina Panthers", "CHI": "Chicago Bears",
    "CIN": "Cincinnati Bengals", "CLE": "Cleveland Browns", "DAL": "Dallas Cowboys",
    "DEN": "Denver Broncos", "DET": "Detroit Lions", "GB": "Green Bay Packers",
    "HOU": "Houston Texans", "IND": "Indianapolis Colts", "JAX": "Jacksonville Jaguars",
    "KC": "Kansas City Chiefs", "LAC": "Los Angeles Chargers", "LAR": "Los Angeles Rams",
    "LV": "Las Vegas Raiders", "MIA": "Miami Dolphins", "MIN": "Minnesota Vikings",
    "NE": "New England Patriots", "NO": "New Orleans Saints", "NYG": "New York Giants",
    "NYJ": "New York Jets", "PHI": "Philadelphia Eagles", "PIT": "Pittsburgh Steelers",
    "SEA": "Seattle Seahawks", "SF": "San Francisco 49ers", "TB": "Tampa Bay Buccaneers",
    "TEN": "Tennessee Titans", "WAS": "Washington Commanders",
}
CONFERENCES = ("AFC", "NFC")
DIVISIONS = ("North", "South", "East", "West")

_standings_cache = {}


def _finished_games(season, season_type=2, include_live=False):
    """Every completed game of a season, oldest first, as plain rows.

    One query feeds standings, rankings, recent form and the team page's
    results list -- they are all the same underlying facts, and deriving
    them from a single read keeps them from ever disagreeing.

    `include_live` additionally counts games still being played, at the
    score they currently hold. Standings must not use it -- a win is not
    a win until the whistle -- but a power ranking should move while the
    games move, which is what it is for."""
    if not DATABASE_URL:
        return []
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT espn_event_id, week, kickoff, home_team, away_team,
                          home_score, away_score, status
                   FROM nfl_schedule
                   WHERE season = %s AND season_type = %s
                     AND home_score IS NOT NULL AND away_score IS NOT NULL
                     AND status = ANY(%s)
                   ORDER BY kickoff""",
                (season, season_type,
                 ["final", "in_progress"] if include_live else ["final"]),
            )
            return [dict(r) for r in cur.fetchall()]
    except Exception:
        return []
    finally:
        conn.close()


def get_team_standings(season, season_type=2, cache=_standings_cache):
    """{team: {...}} -- record, win pct, points for/against, division
    record, last five, streak and conference rank.

    Computed from our own schedule rather than fetched, so it is correct
    for whatever the table holds and needs no second source to stay in
    step with the scores already on the site."""
    season, season_type = _safe_int(season, int(SEASON)), _safe_int(season_type, 2)
    key = (season, season_type)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 300:
        return entry["data"]

    rows = {t: {"team": t, "conference": c, "division": d,
                "wins": 0, "losses": 0, "ties": 0,
                "pf": 0, "pa": 0, "games": 0,
                "div_wins": 0, "div_losses": 0, "div_ties": 0,
                "results": []}
            for t, (c, d) in NFL_DIVISIONS.items()}

    for g in _finished_games(season, season_type):
        home, away = g["home_team"], g["away_team"]
        hs, as_ = g["home_score"], g["away_score"]
        if home not in rows or away not in rows:
            continue
        same_div = (NFL_DIVISIONS[home] == NFL_DIVISIONS[away])
        for team, own, opp in ((home, hs, as_), (away, as_, hs)):
            r = rows[team]
            r["games"] += 1
            r["pf"] += own
            r["pa"] += opp
            outcome = "W" if own > opp else ("L" if own < opp else "T")
            r["results"].append(outcome)
            r["wins" if outcome == "W" else ("losses" if outcome == "L" else "ties")] += 1
            if same_div:
                r["div_wins" if outcome == "W" else
                  ("div_losses" if outcome == "L" else "div_ties")] += 1

    for r in rows.values():
        played = r["games"] or 0
        decided = r["wins"] + r["losses"] + r["ties"]
        # Ties count as half a win, which is how the NFL computes win pct.
        r["pct"] = round((r["wins"] + 0.5 * r["ties"]) / decided, 3) if decided else 0.0
        r["ppg"] = round(r["pf"] / played, 1) if played else 0.0
        r["papg"] = round(r["pa"] / played, 1) if played else 0.0
        r["diff"] = r["pf"] - r["pa"]
        r["record"] = f"{r['wins']}-{r['losses']}" + (f"-{r['ties']}" if r["ties"] else "")
        r["div_record"] = (f"{r['div_wins']}-{r['div_losses']}"
                           + (f"-{r['div_ties']}" if r["div_ties"] else ""))
        last5 = r["results"][-5:]
        r["last5"] = f"{last5.count('W')}-{last5.count('L')}" + (
            f"-{last5.count('T')}" if last5.count("T") else "")
        # Current streak, counted back from the most recent result.
        streak = 0
        for outcome in reversed(r["results"]):
            if streak and outcome != r["results"][-1]:
                break
            streak += 1
        r["streak"] = f"{r['results'][-1]}{streak}" if r["results"] else "-"

    # Conference rank, the "6th AFC" figure on each row. Ordered by win
    # pct, then point differential as the tie-break -- not the NFL's full
    # tiebreaker ladder (head-to-head, common games, strength of victory),
    # which needs more than a schedule table; this is an ordering for
    # display, and the page says as much.
    for conf in CONFERENCES:
        members = sorted((r for r in rows.values() if r["conference"] == conf),
                         key=lambda r: (-r["pct"], -r["diff"], -r["pf"]))
        for i, r in enumerate(members, 1):
            r["conf_rank"] = i

    _assign_playoff_seeds(rows)
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


# The marks the reference standings use, and what each one means. Kept in
# one place so the rows and the legend below them can never disagree.
PLAYOFF_MARKERS = {
    "bye":      {"emoji": "\U0001F410", "label": "Bye to Divisional Round"},
    "division": {"emoji": "\U0001F451", "label": "Division leader"},
    "wildcard": {"emoji": "\U0001F0CF", "label": "Wild Card team"},
}
TRADED_PICK_EMOJI = "\u27A1\uFE0F"

# Where a traded first-round pick actually lands: {(season, original
# team): team that now holds it}. Deliberately empty.
#
# Nobody publishes traded draft picks in a free feed -- not ESPN's
# scoreboard, not Sleeper, not nflverse. The marker below renders the
# moment an entry exists here, so this is the one line to fill in (by
# hand, or from a paid feed) rather than a feature to rebuild. An empty
# map means the draft order simply shows no trades, which is honest.
TRADED_DRAFT_PICKS = {}


def _seed_order(r):
    """Win pct, then point differential, then points scored.

    Not the NFL's full tiebreaker ladder -- head-to-head, common games
    and strength of victory need more than a schedule table. This is an
    ordering for display and the page says so."""
    return (-r["pct"], -r["diff"], -r["pf"])


def _assign_playoff_seeds(rows):
    """Give every team its conference seed and the mark that goes with
    it: the goat for the first-round bye, the crown for the other three
    division winners, the joker for the wild cards.

    Division winners take seeds 1-4 however their records compare to the
    rest of the conference -- that is the whole point of winning a
    division, and a 9-8 winner really does seed above an 11-6 wild
    card."""
    for conf in CONFERENCES:
        members = [r for r in rows.values() if r["conference"] == conf]
        leaders = []
        for d in DIVISIONS:
            division = sorted((r for r in members if r["division"] == d), key=_seed_order)
            if division:
                leaders.append(division[0])
        leaders.sort(key=_seed_order)
        leader_teams = {r["team"] for r in leaders}
        rest = sorted((r for r in members if r["team"] not in leader_teams), key=_seed_order)

        for i, r in enumerate(leaders + rest, 1):
            kind = ("bye" if i == 1 else
                    "division" if i <= 4 else
                    "wildcard" if i <= 7 else None)
            mark = PLAYOFF_MARKERS.get(kind)
            r["seed"] = i
            r["seed_kind"] = kind
            r["marker"] = mark["emoji"] if mark else None
            r["marker_label"] = mark["label"] if mark else None
            r["in_playoffs"] = kind is not None


def get_playoff_field(season, conf, season_type=2):
    """One conference in seed order, playoff teams first -- the same list
    the reference shows behind its Playoffs tab."""
    rows = get_team_standings(season, season_type)
    members = [r for r in rows.values() if r["conference"] == conf]
    members.sort(key=lambda r: r.get("seed") or 99)
    return members


def _season_opponents(season, season_type=2, cache={}):
    """{team: [opponent, ...]} across the WHOLE schedule, played or not.

    Strength of schedule counts every opponent a team is down to face,
    each appearance separately, so a division rival met twice counts
    twice. That is how the league computes it, and it is why the figure
    is meaningful in week 1 when almost nothing has been played."""
    season, season_type = _safe_int(season, int(SEASON)), _safe_int(season_type, 2)
    key = (season, season_type)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 3600:
        return entry["data"]
    out = {}
    if DATABASE_URL:
        conn = get_db()
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT home_team, away_team FROM nfl_schedule
                       WHERE season = %s AND season_type = %s""",
                    (season, season_type),
                )
                for r in cur.fetchall():
                    out.setdefault(r["home_team"], []).append(r["away_team"])
                    out.setdefault(r["away_team"], []).append(r["home_team"])
        except Exception:
            out = {}
        finally:
            conn.close()
    cache[key] = {"data": out, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return out


def get_draft_order(season, season_type=2):
    """All 32 teams in draft order: worst record picks first, ties broken
    by the easier schedule, as the league breaks them.

    This is the regular-season order. Once the postseason is played the
    last fourteen picks reorder by how far each team went, which needs
    playoff results this does not have yet -- so during the season it is
    right, and in January it is the order before the bracket moves it."""
    rows = get_team_standings(season, season_type)
    opponents = _season_opponents(season, season_type)
    out = []
    for team, r in rows.items():
        wins = losses = ties = 0
        for opp in opponents.get(team, []):
            o = rows.get(opp)
            if not o:
                continue
            wins += o["wins"]
            losses += o["losses"]
            ties += o["ties"]
        decided = wins + losses + ties
        sos = round((wins + 0.5 * ties) / decided, 3) if decided else 0.0
        entry = dict(r)
        entry["sos"] = sos
        entry["traded_to"] = TRADED_DRAFT_PICKS.get((_safe_int(season, int(SEASON)), team))
        out.append(entry)
    # Worst record first; the easier schedule picks ahead of the harder
    # one; points allowed as a last resort so the order is stable.
    out.sort(key=lambda r: (r["pct"], r["sos"], -r["pa"]))
    for i, r in enumerate(out, 1):
        r["pick"] = i
    return out


# The position families the scores board leads with, in the order the
# reference shows them. Kickers get their own line rather than being
# folded in with the skill positions, where a 14-point day would never
# out-rank a receiver's 30.
PERFORMER_GROUPS = [
    {"key": "qb",  "title": "Top QB",         "positions": ["QB"]},
    {"key": "flex", "title": "Top WR/RB/TE",  "positions": ["WR", "RB", "TE"]},
    {"key": "idp", "title": "Top DB/LB/DL",   "positions": ["DB", "LB", "DL"]},
    {"key": "k",   "title": "Top K",          "positions": ["K"]},
]

# How many teams the scores board's power-ranking strip shows before
# handing off to the full standings page.
POWER_BOARD_SIZE = 10


RANK_WINDOWS = [("d7", "7-day"), ("d30", "30-day"), ("season", "Season")]


def get_power_board(season, season_type=2, limit=POWER_BOARD_SIZE, window="d30"):
    """The power ranking, ready to render: rank, logo, record, point
    differential, and the per-game figure the rank was computed on.

    `window` is one of the three the team page shows -- the latest round,
    the last four, or the whole season. The scores page asks for the
    four-round one, which is what people mean by "power ranking": who is
    good NOW, not who banked wins in September. Teams with nothing in a
    window fall back to the next one out inside get_team_rankings, so
    nobody is missing.

    Returns [] rather than raising when the season has no finished games
    yet; the strip simply does not render."""
    if window not in dict(RANK_WINDOWS):
        window = "d30"
    try:
        ranks = get_team_rankings(season, season_type)
        standings = get_team_standings(season, season_type)
        live_diff = _live_point_diff(season, season_type)
    except Exception:
        return []
    out = []
    for team, r in (ranks or {}).items():
        place = r.get(window) or r.get("season")
        if not place:
            continue
        st = standings.get(team) or {}
        record = f"{st.get('wins', 0)}-{st.get('losses', 0)}"
        if st.get("ties"):
            record += f"-{st['ties']}"
        out.append({
            "team": team, "rank": place, "logo": team_logo_url(team),
            "record": record,
            # The rank counts a game in progress at its current score --
            # that is what makes it live. The differential beside it must
            # count the same game, or a team leading on Monday night sits
            # at #3 reading "0-0, +0", which looks like a mistake rather
            # than a game half played. The record stays finished games
            # only: a win is not a win until the whistle.
            "diff": live_diff.get(team, st.get("diff")),
            "live": team in live_diff and live_diff[team] != st.get("diff"),
            # Average margin per game inside the window -- the number the
            # rank actually came from.
            "avg": r.get(window + "_avg"),
            "games": r.get(window + "_games"),
            "inherited": bool(r.get(window + "_inherited")),
        })
    out.sort(key=lambda t: t["rank"])
    return out[:limit]


def _live_point_diff(season, season_type=2):
    """Season point differential per team, counting games in progress at
    the score they hold right now. {} when nothing is live, so callers
    fall through to the settled figure."""
    games = _finished_games(season, season_type, include_live=True)
    if not any(g.get("status") == "in_progress" for g in games):
        return {}
    out = {}
    for g in games:
        for team, own, opp in ((g["home_team"], g["home_score"], g["away_score"]),
                               (g["away_team"], g["away_score"], g["home_score"])):
            if team in NFL_DIVISIONS and own is not None and opp is not None:
                out[team] = out.get(team, 0) + (own - opp)
    return out


# --- Injuries and birthdays ---------------------------------------------
#
# Both read the player dump the site already pulls, so neither costs a
# new source. Injuries need one thing the dump cannot give on its own:
# Sleeper publishes the CURRENT designation, never the change, so
# "Out -> Active" only exists if something was watching for it. That is
# what player_injury_state is for -- it is written every time the dump
# refreshes and remembers what each designation used to be.

# Sleeper leaves injury_status null for a healthy player. "Active" is
# what that means and what the reference calls it.
ACTIVE_STATUS = "Active"

# Designations that read as a setback, so a change INTO one is bad news
# and a change out of one is good news.
_INJURY_BAD = {"IR", "OUT", "DOUBTFUL", "PUP", "SUSPENDED", "NA", "COV"}

INJURY_FEED_SIZE = 6
BIRTHDAY_FEED_SIZE = 6


# ESPN publishes the league's whole injury report in one call, updated
# continuously, with the designation, the body part and the date it was
# set. Sleeper's dump carries only a bare designation and refreshes every
# few hours, so ESPN leads and Sleeper backs it up.
#
# Undocumented, like the rest of ESPN's site API and like everything else
# this app reads from it -- so it is parsed defensively and an
# unrecognised response costs the section and nothing else.
ESPN_INJURIES_URL = f"{ESPN_SITE_BASE}/injuries"


# ESPN fills unknown injury fields with a literal placeholder rather
# than leaving them out, and the one my first parser reached for --
# details.detail -- is the field most often set to it. That is how the
# board came to read "Injured Reserve - Not Specified" down a whole
# column. None of these is information; every one of them is dropped.
_INJURY_PLACEHOLDERS = {
    "", "not specified", "notspecified", "unspecified", "unknown",
    "n/a", "na", "none", "null", "-", "--", "tbd",
}


def _clean_injury_field(value):
    """A field's value, or None when it is one of ESPN's placeholders."""
    text = str(value or "").strip()
    return None if text.lower() in _INJURY_PLACEHOLDERS else (text or None)


def _espn_injury_detail(item):
    """What is actually wrong, e.g. "Left/Knee/Sprain" or "Hamstring".

    Assembled from the parts ESPN splits it across -- side, location and
    the kind of injury -- because any one of them alone is usually the
    placeholder. `type.description` is deliberately NOT used: on these
    entries it holds the STATUS ("Out"), not the ailment, so reading it
    as a detail prints the designation twice."""
    details = item.get("details") if isinstance(item.get("details"), dict) else {}
    side = _clean_injury_field(details.get("side"))
    location = _clean_injury_field(details.get("location"))
    kind = (_clean_injury_field(details.get("detail"))
            or _clean_injury_field(details.get("type")))
    # "Left/Knee/Sprain", skipping whichever parts are unknown, and never
    # repeating one ("Knee/Knee"). The parts are joined with a slash
    # rather than a space because ESPN's three fields are three separate
    # facts -- run together, "Leg Knee" reads like one garbled ailment,
    # where "Leg/Knee" reads as the list it actually is. A single known
    # part comes back bare, with no slash to separate it from nothing.
    parts, seen = [], set()
    for part in (side, location, kind):
        key = (part or "").lower()
        if part and key not in seen:
            seen.add(key)
            parts.append(part)
    return "/".join(parts) or None


def _espn_injury_reason(item, limit=160):
    """The sentence ESPN writes about why, when it writes one.

    The short comment is the one meant to be read at a glance ("Pacheco
    (knee) is out for Sunday's game"); the long one is the fallback,
    trimmed at a sentence rather than mid-word."""
    for key in ("shortComment", "longComment"):
        text = _clean_injury_field(item.get(key))
        if not text:
            continue
        if len(text) <= limit:
            return text
        cut = text[:limit]
        stop = max(cut.rfind(". "), cut.rfind("! "))
        return (cut[:stop + 1] if stop > 40 else cut.rstrip() + "\u2026")
    return None


def _parse_espn_datetime(value):
    """ESPN's ISO timestamps, as a naive UTC datetime. None if absent or
    unparseable -- a missing date costs the row its stamp, never the
    row."""
    if not value:
        return None
    try:
        return _as_naive_utc(
            datetime.fromisoformat(str(value).strip().replace("Z", "+00:00")))
    except (ValueError, TypeError):
        return None
_espn_injuries_cache = {}


def espn_injuries(cache=_espn_injuries_cache):
    """[{team, name, status, detail, since}] for every injured player
    ESPN lists, or [] if the call fails or arrives in a shape we do not
    recognise.

    TTL 600s: designations change over a week, not a drive, and this is
    one request for the entire league."""
    now = time.time()
    entry = cache.get("all")
    if entry and now - entry["time"] < 600:
        return entry["data"]
    try:
        r = requests.get(ESPN_INJURIES_URL, timeout=15)
        r.raise_for_status()
        body = r.json()
    except Exception:
        # Serve the last good answer rather than blanking the section on
        # one bad request.
        return entry["data"] if entry else []

    out = []
    # ESPN nests these per team: {"injuries": [{"team"/"displayName",
    # "injuries": [{athlete, status, date, ...}]}]}. Both levels are read
    # tolerantly because neither is documented.
    for group in (body.get("injuries") or []):
        if not isinstance(group, dict):
            continue
        team = (group.get("abbreviation")
                or ((group.get("team") or {}).get("abbreviation")
                    if isinstance(group.get("team"), dict) else None)
                or group.get("displayName"))
        for item in (group.get("injuries") or []):
            if not isinstance(item, dict):
                continue
            athlete = item.get("athlete") if isinstance(item.get("athlete"), dict) else {}
            name = (athlete.get("displayName") or athlete.get("fullName")
                    or item.get("displayName"))
            if not name:
                continue
            status = (item.get("status") or "").strip()
            out.append({
                "team": normalize_team_abbr(team) if team else None,
                "name": name,
                "espn_id": str(athlete.get("id") or "") or None,
                "status": canonical_status(status) or ACTIVE_STATUS,
                "detail": _espn_injury_detail(item),
                "reason": _espn_injury_reason(item),
                # When the designation was actually published, which is
                # what orders and timestamps the board -- not when this
                # app happened to notice.
                "since": _parse_espn_datetime(item.get("date")),
            })
    cache["all"] = {"data": out, "time": now}
    return out


def _players_or_empty():
    """The player dump, or {} when it is unavailable or not the shape we
    expect.

    Injuries and birthdays are decoration on a page whose job is live
    scores. An upstream hiccup, or a response that arrives in an
    unexpected shape, must cost those two sections and nothing else --
    it must never be able to blank the scoreboard above them, which is
    what an exception escaping into the route would do."""
    try:
        players = get_all_players()
    except Exception:
        return {}
    return players if isinstance(players, dict) else {}


def _injury_status_of(player):
    """The designation as it should be displayed: a real status, or
    Active when Sleeper leaves it blank."""
    raw = ((player or {}).get("injury_status") or "").strip()
    if not raw:
        return ACTIVE_STATUS
    return INJURY_BADGE.get(raw.upper(), (None, raw.title(), None))[1]


def record_injury_changes(statuses):
    """Write every designation that moved since the last time we looked.

    `statuses` is {sleeper_id: designation}. Runs on a background thread,
    never a request path. Returns the number of changes recorded (0 when
    there is no database, which is a valid configuration here and simply
    means the arrows never appear -- the report itself still does)."""
    if not DATABASE_URL or not isinstance(statuses, dict) or not statuses:
        return 0
    conn = get_db()
    changed = 0
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT sleeper_id, status FROM player_injury_state")
            known = {r["sleeper_id"]: r["status"] for r in cur.fetchall()}
            rows = [(sid, status, known.get(sid))
                    for sid, status in statuses.items()
                    if known.get(sid) != status]
            if not rows:
                return 0
            # A player we have never seen before is not a change -- there
            # is nothing to have changed FROM. Seed them with no previous
            # status, so the arrow appears the moment something moves.
            # Three columns, not four. execute_values sniffs the
            # placeholder count from the first row, so naming changed_at
            # here while passing three values built an INSERT with more
            # target columns than expressions -- which Postgres rejects
            # outright. It was caught by the bare `except` below and
            # reported as "0 changes", so the report kept working off the
            # live dump and only the arrows silently never appeared.
            # changed_at defaults to NOW() on insert and is set
            # explicitly on the update, so it never needed naming.
            psycopg2.extras.execute_values(
                cur,
                """INSERT INTO player_injury_state
                       (sleeper_id, status, previous_status)
                   VALUES %s
                   ON CONFLICT (sleeper_id) DO UPDATE SET
                       previous_status = player_injury_state.status,
                       status = EXCLUDED.status,
                       changed_at = NOW()""",
                rows,
            )
            changed = len(rows)
        conn.commit()
    except Exception:
        changed = 0
    finally:
        conn.close()
    _injury_feed_cache.clear()
    return changed


def _full_name_index(all_players):
    """{(team, "gabriel rubio"): sleeper_id} -- ESPN writes full display
    names, Sleeper keys by id, and this is the join between them."""
    index = {}
    for sid, p in (all_players or {}).items():
        if not isinstance(p, dict) or not p.get("team"):
            continue
        name = f"{p.get('first_name','')} {p.get('last_name','')}".strip().lower()
        if name:
            index.setdefault((p["team"], name), sid)
            index.setdefault((None, name), sid)
    return index


def build_injury_statuses():
    """{sleeper_id: designation} for every rostered player.

    ESPN leads: its report is updated continuously and says what is
    actually wrong. Sleeper's dump fills in anyone ESPN does not list,
    which is most of the league -- and a player in neither is Active,
    which is what makes a RETURN detectable at all."""
    players = _players_or_empty()
    if not players:
        return {}, {}
    index = _full_name_index(players)

    espn_by_sid = {}
    for row in espn_injuries():
        sid = (index.get((row.get("team"), (row.get("name") or "").lower()))
               or index.get((None, (row.get("name") or "").lower())))
        if sid:
            espn_by_sid[sid] = row

    statuses = {}
    for sid, p in players.items():
        if not isinstance(p, dict) or not p.get("team"):
            continue
        hit = espn_by_sid.get(sid)
        statuses[sid] = (hit or {}).get("status") or _injury_status_of(p)
    return statuses, espn_by_sid


# ---------------- Roster moves ----------------
#
# Every signing, release, waiver claim and trade in the league, found the
# same way the injury arrows are: Sleeper's player dump carries each
# player's current team, so a move is that field changing. No separate
# transactions API to depend on, and it updates as soon as Sleeper does.
#
# A team of None means not on any roster. That is what makes the three
# kinds of row distinguishable at all:
#   None -> "KC"    signed, claimed off waivers, activated
#   "CHI" -> None   released, waived, cut
#   "ATL" -> "DAL"  traded
MOVE_FEED_SIZE = 6
# How long a move stays on the board. A signing is news the day it
# happens and history a fortnight later, so it ages off rather than
# accumulating -- the same reasoning as RETURN_NEWS_DAYS.
MOVE_NEWS_DAYS = 14
NOT_ROSTERED = "NR"

_team_state_lock = threading.Lock()
_team_state_last = {"time": 0.0}
TEAM_STATE_REFRESH_S = 900
_moves_feed_cache = {}


def build_team_assignments():
    """{sleeper_id: team or None} for everyone worth watching.

    Restricted to players who carry a real position: Sleeper's dump runs
    to thousands of entries, most of them long-retired or never-rostered,
    and a move only means something for someone who could be on a
    roster."""
    players = _players_or_empty()
    if not players:
        return {}
    # NOT_ROSTERED rather than None, deliberately. NULL in this column
    # has to mean one thing only: "never seen before". A player genuinely
    # off every roster is a known state, not an unknown one, and if both
    # were NULL then the first time this table is ever filled every
    # rostered player in the league would read as a fresh signing.
    return {sid: (p.get("team") or NOT_ROSTERED)
            for sid, p in players.items()
            if isinstance(p, dict) and _moves_watches(p.get("position"))}


def _moves_watches(position):
    """Is this a player the moves feed follows?

    Not `position in SCORED_POSITIONS`, which is the mistake this
    replaces. That list holds the GROUPED defensive names -- DL, LB, DB
    -- while Sleeper's dump labels defenders the way a depth chart does:
    DE, DT, NT, OLB, ILB, MLB, CB, S, FS, SS. Testing raw membership
    quietly dropped nearly every defender in the league, so a traded
    edge rusher would never have appeared. IDP_POSITION_MAP is the same
    translation the rest of the site already runs defenders through."""
    if not position:
        return False
    return (position in POSITIONS
            or position in KICKER_POSITIONS
            or position in IDP_POSITION_MAP)


def record_team_changes(assignments):
    """Write every team that moved since the last time we looked.

    Mirrors record_injury_changes deliberately -- same seeding rule, same
    background-thread discipline, same "no database is a valid
    configuration" behaviour. A player seen for the first time is seeded
    rather than reported: there is nothing for them to have moved FROM,
    and without this every player would appear as a signing the first
    time the table was ever filled."""
    if not DATABASE_URL or not isinstance(assignments, dict) or not assignments:
        return 0
    conn = get_db()
    changed = 0
    try:
        with conn.cursor() as cur:
            cur.execute("SELECT sleeper_id, team FROM player_team_state")
            known = {r["sleeper_id"]: r["team"] for r in cur.fetchall()}
            rows = [(sid, team, known.get(sid))
                    for sid, team in assignments.items()
                    if sid not in known or known.get(sid) != team]
            if not rows:
                return 0
            psycopg2.extras.execute_values(
                cur,
                """INSERT INTO player_team_state
                       (sleeper_id, team, previous_team)
                   VALUES %s
                   ON CONFLICT (sleeper_id) DO UPDATE SET
                       previous_team = player_team_state.team,
                       team = EXCLUDED.team,
                       changed_at = NOW()""",
                rows,
            )
            changed = len(rows)
        conn.commit()
    except Exception:
        changed = 0
    finally:
        conn.close()
    _moves_feed_cache.clear()
    return changed


def _record_team_changes_background():
    """Keep the move history current off the request path, driven by
    traffic rather than a cron -- the same arrangement the injury
    arrows use, and for the same reason: nothing to configure."""
    now = time.time()
    with _team_state_lock:
        if now - _team_state_last["time"] < TEAM_STATE_REFRESH_S:
            return
        _team_state_last["time"] = now

    def _run():
        try:
            with _BACKGROUND_SYNC_SLOTS:
                record_team_changes(build_team_assignments())
        except Exception:
            pass

    threading.Thread(target=_run, daemon=True).start()


def _rostered(value):
    return bool(value) and value != NOT_ROSTERED


def _move_kind(previous_team, team):
    """What actually happened, in the words a reader uses."""
    if _rostered(previous_team) and _rostered(team):
        return "traded"
    if _rostered(team):
        return "signed"
    return "released"


def get_moves_report(limit=None, days=MOVE_NEWS_DAYS, cache=_moves_feed_cache):
    """Every roster move the app has watched happen, newest first.

    Returns [] rather than raising for a missing database or an empty
    player dump -- a decoration feed is never worth the page it sits on.
    """
    key = ("moves", days)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 300:
        rows = entry["rows"]
        return rows[:limit] if limit else rows

    _record_team_changes_background()
    rows = []
    if not DATABASE_URL:
        return []
    players = _players_or_empty()
    try:
        conn = get_db()
        try:
            with conn.cursor() as cur:
                cur.execute(
                    """SELECT sleeper_id, team, previous_team, changed_at
                       FROM player_team_state
                       WHERE previous_team IS NOT NULL
                         AND previous_team IS DISTINCT FROM team
                       ORDER BY changed_at DESC
                       LIMIT 400""")
                found = cur.fetchall()
        finally:
            conn.close()
    except Exception:
        return []

    for r in found:
        if not _is_recent(r.get("changed_at"), days):
            continue
        sid = r["sleeper_id"]
        p = players.get(sid) or {}
        name = f"{p.get('first_name','')} {p.get('last_name','')}".strip()
        if not name:
            continue
        team, prev = r.get("team"), r.get("previous_team")
        rows.append({
            "sid": sid, "name": name,
            "position": p.get("position"),
            "photo": player_photo_url(sid),
            # The crest on the mugshot is where they are NOW -- which for
            # a release is nowhere, so it falls back to the old one
            # rather than leaving a hole.
            "logo": team_logo_url(team if _rostered(team) else prev),
            "from_team": prev or NOT_ROSTERED,
            "from_logo": team_logo_url(prev) if _rostered(prev) else None,
            "to_team": team or NOT_ROSTERED,
            "to_logo": team_logo_url(team) if _rostered(team) else None,
            "kind": _move_kind(prev, team),
            "ago": _time_ago(r.get("changed_at")),
            "ts": _feed_ts(r.get("changed_at")),
            "changed_at": r.get("changed_at"),
        })
    cache[key] = {"rows": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows[:limit] if limit else rows


def get_moves_today(limit=MOVE_FEED_SIZE):
    """The short list the scoreboard has room for."""
    return get_moves_report(limit=limit)


# ---------------- Streaks: prop lines and hit rates, game by game ----------------
#
# The lines here are the site's own, not a sportsbook's. There is no
# free, licensable source of book player-prop lines -- they are the
# books' product, and every aggregator that carries them charges for it
# -- so each player's default line is shaped from their own last ten
# games the way a book shapes one: the median, landed on the .5 so an
# over or under is always decidable. The reader moves it anyway; that is
# the point of the page. `line_source` travels with every row so a
# licensed feed can replace the default later without the UI knowing.
#
# Everything reads the stat line Sleeper already sends for every
# player-game (player_stats.stats), so a prop is a formula over keys
# Sleeper names, not a second data source.

STREAK_BARS = 20          # games on the chart and in a list row
# The default line is shaped from twice the games the board judges
# against it (the last ten). Shaped from the same ten, at most half of
# them could ever clear it, and no hit rate would say anything -- an
# 80% "trend" was impossible by construction.
STREAK_LINE_GAMES = 20    # games the default line is shaped from
STREAK_TREND_GAMES = 5    # games a trend needs in the last ten
STREAK_TREND_PCT = 80     # and the share on one side of the line
STREAK_UNDER_MIN_LINE = 2 # an under streak needs a line worth going under
STREAK_MIN_GAMES = 3      # fewer than this and a player is not listed
STREAK_LIST_MAX = 250
STREAK_SEASONS_BACK = 1   # this season plus last: enough for 20 games
STREAK_WINDOWS = (("season", "This season"), ("h2h", "H2H"),
                  ("l5", "L5"), ("l10", "L10"), ("l20", "L20"))
STREAK_LINE_SOURCE = "site"

# key, label, short label, position groups, ((sleeper key, weight), ...), whole numbers?
STREAK_PROPS = [
    ("pass_yd",      "Passing Yards",       "Pass Yds",  ("QB",),               (("pass_yd", 1),), False),
    ("pass_td",      "Passing TDs",         "Pass TD",   ("QB",),               (("pass_td", 1),), True),
    ("pass_cmp",     "Completions",         "Comp",      ("QB",),               (("pass_cmp", 1),), True),
    ("pass_att",     "Pass Attempts",       "Pass Att",  ("QB",),               (("pass_att", 1),), True),
    ("pass_int",     "Interceptions",       "INT",       ("QB",),               (("pass_int", 1),), True),
    ("pass_lng",     "Longest Completion",  "Pass Long", ("QB",),               (("pass_lng", 1),), False),
    ("pass_rush_yd", "Pass + Rush Yards",   "Pass+Rush", ("QB",),               (("pass_yd", 1), ("rush_yd", 1)), False),
    ("rush_yd",      "Rushing Yards",       "Rush Yds",  ("QB", "RB", "WR"),    (("rush_yd", 1),), False),
    ("rush_att",     "Carries",             "Carries",   ("RB",),               (("rush_att", 1),), True),
    ("rush_td",      "Rushing TDs",         "Rush TD",   ("QB", "RB"),          (("rush_td", 1),), True),
    ("rush_lng",     "Longest Rush",        "Rush Long", ("RB",),               (("rush_lng", 1),), False),
    ("rec",          "Receptions",          "Catches",   ("RB", "WR", "TE"),    (("rec", 1),), True),
    ("rec_yd",       "Receiving Yards",     "Rec Yds",   ("RB", "WR", "TE"),    (("rec_yd", 1),), False),
    ("rec_td",       "Receiving TDs",       "Rec TD",    ("RB", "WR", "TE"),    (("rec_td", 1),), True),
    ("rec_tgt",      "Targets",             "Targets",   ("RB", "WR", "TE"),    (("rec_tgt", 1),), True),
    ("rec_lng",      "Longest Reception",   "Rec Long",  ("RB", "WR", "TE"),    (("rec_lng", 1),), False),
    ("rush_rec_yd",  "Rush + Rec Yards",    "Rush+Rec",  ("RB", "WR", "TE"),    (("rush_yd", 1), ("rec_yd", 1)), False),
    ("any_td",       "Anytime TD",          "TD",        ("QB", "RB", "WR", "TE"), (("rush_td", 1), ("rec_td", 1)), True),
    ("fgm",          "Field Goals Made",    "FG",        ("K",),                (("fgm", 1),), True),
    ("xpm",          "Extra Points Made",   "XP",        ("K",),                (("xpm", 1),), True),
    ("kick_pts",     "Kicking Points",      "Kick Pts",  ("K",),                (("fgm", 3), ("xpm", 1)), True),
    ("fgm_lng",      "Longest Field Goal",  "FG Long",   ("K",),                (("fgm_lng", 1),), False),
    ("idp_tkl",      "Tackles",             "Tackles",   ("DL", "LB", "DB"),    (("idp_tkl", 1),), True),
    ("idp_tkl_solo", "Solo Tackles",        "Solo",      ("DL", "LB", "DB"),    (("idp_tkl_solo", 1),), True),
    ("idp_sack",     "Sacks",               "Sacks",     ("DL", "LB", "DB"),    (("idp_sack", 1),), False),
    ("idp_tkl_loss", "Tackles for Loss",    "TFL",       ("DL", "LB", "DB"),    (("idp_tkl_loss", 1),), True),
    ("idp_int",      "Interceptions",       "INT",       ("LB", "DB"),          (("idp_int", 1),), True),
    ("idp_pass_def", "Passes Defended",     "PD",        ("LB", "DB"),          (("idp_pass_def", 1),), True),
]
STREAK_PROP_BY_KEY = {p[0]: p for p in STREAK_PROPS}
# The tabs the list page offers, in the order the reference shows them:
# the cross-prop trends first, then the props most people come for.
STREAK_LIST_TABS = ["trends", "any_td", "pass_yd", "rec_yd", "rush_yd", "rec",
                    "pass_td", "rec_tgt", "rush_att", "pass_rush_yd", "rush_rec_yd",
                    "kick_pts", "idp_tkl", "idp_sack"]

_streaks_cache = {}
_streak_logs_cache = {}
_streak_sched_cache = {}


def streak_position_group(position):
    """QB/RB/WR/TE/K as themselves, every defender as DL/LB/DB."""
    if not position:
        return None
    if position in POSITIONS or position in KICKER_POSITIONS:
        return position
    return IDP_POSITION_MAP.get(position)


# What each group's tabs lead with, and which family of props comes
# first. The catalogue above is one list shared by every group, so
# without this a receiver's first tab was Rush Yds -- it sits earlier in
# the list than the receiving props because quarterbacks and backs share
# it. A receiver opens on Rec Yds, a back on Rush Yds, a quarterback on
# Pass Yds, a kicker on Kicking Points, and a lineman on sacks; the rest
# of the group's own family follows in catalogue order, then the shared
# props.
STREAK_LEAD = {"QB": "pass_yd", "RB": "rush_yd", "WR": "rec_yd", "TE": "rec_yd",
               "K": "kick_pts", "DL": "idp_sack", "LB": "idp_tkl", "DB": "idp_tkl"}
STREAK_FAMILY = {"QB": ("pass",), "RB": ("rush",), "WR": ("rec",), "TE": ("rec",),
                 "K": ("fgm", "xpm", "kick"), "DL": ("idp",), "LB": ("idp",), "DB": ("idp",)}


def streak_props_for(position):
    group = streak_position_group(position)
    props = [p for p in STREAK_PROPS if group in p[3]]
    lead = STREAK_LEAD.get(group)
    family = STREAK_FAMILY.get(group, ())
    return sorted(props, key=lambda p: (p[0] != lead, not p[0].startswith(family)))


def streak_prop_value(prop, stats):
    """The prop's figure for one game, from Sleeper's stat line."""
    total = 0.0
    for key, weight in prop[4]:
        v = (stats or {}).get(key)
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            total += v * weight
    return round(total, 1)


def _median(values):
    vals = sorted(values)
    n = len(vals)
    if not n:
        return None
    mid = n // 2
    return vals[mid] if n % 2 else (vals[mid - 1] + vals[mid]) / 2.0


def streak_line(values, games=STREAK_LINE_GAMES):
    """The default line: the median of the last `games` figures, landed
    on the .5 just above its floor. Always a half so no game pushes;
    always within half a unit of what the player has actually been
    doing, which is where a book puts it too. None with nothing to
    shape it from."""
    recent = [v for v in values[-games:] if isinstance(v, (int, float))]
    if not recent:
        return None
    return math.floor(_median(recent)) + 0.5


def streak_windows(games, line, opponent=None, season=None):
    """Hit rates against `line` over every window the page offers.

    `games` is chronological. A window with no games reports None
    rather than 0%, so "never played them" and "never beat the line
    against them" cannot be confused."""
    def rate(subset):
        n = len(subset)
        hits = sum(1 for g in subset if g["value"] > line)
        unders = sum(1 for g in subset if g["value"] < line)
        return {"hits": hits, "unders": unders, "n": n,
                "pct": round(100.0 * hits / n) if n else None,
                "under_pct": round(100.0 * unders / n) if n else None}
    out = {
        "l5": rate(games[-5:]),
        "l10": rate(games[-10:]),
        "l20": rate(games[-20:]),
        "season": rate([g for g in games if g["season"] == season]),
        "h2h": rate([g for g in games if opponent and g["opp"] == opponent]),
    }
    return out


def _streak_date_label(when, today=None):
    """"11/15" for a game played this calendar year, "11/15/25" for one
    played in another. The year is only shown where it tells the two
    apart, and "this year" is read off the clock, so the labels turn
    over on their own each January."""
    if not isinstance(when, datetime):
        return None
    try:
        local = (when.replace(tzinfo=timezone.utc) if when.tzinfo is None else when).astimezone(NFL_TZ)
    except Exception:
        return None
    today = today or datetime.now(NFL_TZ)
    if local.year != today.year:
        return f"{local.month}/{local.day}/{local.year % 100:02d}"
    return f"{local.month}/{local.day}"


def _streak_schedule_index(seasons, cache=_streak_sched_cache):
    """{(season, week, team): {opp, home, date}} for every game in
    `seasons`, from one query. A player's log is 20 opponent lookups and
    a list is 250 players' worth; per-row lookups would be thousands of
    round trips."""
    key = tuple(sorted(seasons))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    index = {}
    if DATABASE_URL:
        try:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT season, week, home_team, away_team, kickoff
                           FROM nfl_schedule WHERE season = ANY(%s)""",
                        (list(key),))
                    rows = cur.fetchall()
            finally:
                conn.close()
            today = datetime.now(NFL_TZ)
            for r in rows:
                label = _streak_date_label(r.get("kickoff"), today)
                home, away = r["home_team"], r["away_team"]
                index[(r["season"], r["week"], home)] = {"opp": away, "home": True, "date": label}
                index[(r["season"], r["week"], away)] = {"opp": home, "home": False, "date": label}
        except Exception:
            index = {}
    cache[key] = {"data": index, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return index


def _streak_logs(seasons, cache=_streak_logs_cache):
    """{sleeper_id: [(season, week, stats), ...]} chronological, for
    every row in `seasons` that carries a stat line. One query, cached
    ten minutes; the boards and the detail page both read from it."""
    key = tuple(sorted(seasons))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    logs = {}
    if DATABASE_URL:
        try:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT sleeper_id, season, week, stats FROM player_stats
                           WHERE season = ANY(%s) AND stats IS NOT NULL
                           ORDER BY season, week""",
                        (list(key),))
                    for r in cur.fetchall():
                        st = r.get("stats")
                        if isinstance(st, str):
                            try:
                                st = json.loads(st)
                            except Exception:
                                st = None
                        if not isinstance(st, dict):
                            continue
                        logs.setdefault(r["sleeper_id"], []).append((r["season"], r["week"], st))
            finally:
                conn.close()
        except Exception:
            logs = {}
    cache[key] = {"data": logs, "time": now}
    _cache_trim(cache, CACHE_LIMIT_PER_USER)
    return logs


def streak_seasons(season):
    return [int(season) - n for n in range(STREAK_SEASONS_BACK, -1, -1)]


# Who counts as a starter, by Sleeper's own depth chart. Sleeper slots
# receivers and defenders by alignment (LWR/RWR/SWR, LDE/RDE/DT, LCB/RCB/
# SS/FS), so order 1 within a slot IS the starter and there are three
# starting receivers at order 1. The wider allowances cover teams that
# list a flat WR1..WR6 instead, and committee backfields, where an RB2
# gets real work. Recent snap share is the second signal: a depth chart
# Sleeper has not updated yet, or a player it has not slotted at all, is
# still a starter if he is on the field for half his team's snaps.
STREAK_DEPTH = {"QB": 1, "RB": 2, "WR": 3, "TE": 1, "K": 1, "DL": 1, "LB": 1, "DB": 1}
STREAK_STARTER_SNAP = 0.5
STREAK_STARTER_GAMES = 3


def _snap_share(stats):
    """This game's share of the team's snaps, offence or defence."""
    stats = stats or {}
    played = stats.get("off_snp") or stats.get("def_snp")
    team = stats.get("tm_off_snp") or stats.get("tm_def_snp")
    if isinstance(played, (int, float)) and isinstance(team, (int, float)) and team > 0:
        return min(1.0, played / team)
    return None


def streak_is_starter(p, log=None):
    """Depth chart first, snap share second. Neither alone is enough:
    the chart can lag a change by a day, and snap share alone would
    list a backup for the week the starter left hurt in the first
    quarter."""
    if not isinstance(p, dict) or not p.get("team"):
        return False
    if (p.get("status") or "Active") != "Active":
        return False
    group = streak_position_group(p.get("position"))
    limit = STREAK_DEPTH.get(group)
    if not limit:
        return False
    order = _safe_int(p.get("depth_chart_order"), 0)
    if 1 <= order <= limit:
        return True
    shares = [sh for sh in (_snap_share(st) for _, _, st in (log or [])[-STREAK_STARTER_GAMES:])
              if sh is not None]
    return bool(shares) and sum(shares) / len(shares) >= STREAK_STARTER_SNAP


# ---------------- Book lines: The Odds API ----------------
#
# Sportsbooks do not publish their prop lines for reuse, and reading them
# off FanDuel's or DraftKings' own pages breaks those sites' terms. The
# Odds API licenses exactly those books' lines for use in an app like
# this one, so that is the source: set ODDS_API_KEY in Render and the
# book's line replaces the site's shaped one for every prop it carries,
# FanDuel first, DraftKings where FanDuel has none. No key, and nothing
# here runs; the site's own line stands.
#
# Quota: every event fetch costs one credit per market asked for, so a
# full refresh is roughly 20 markets x the games left this week. Only
# the warm ping refreshes, never a page view, and never more often than
# ODDS_REFRESH_HOURS -- so a burst of visitors cannot spend the quota.
ODDS_API_BASE = "https://api.the-odds-api.com/v4"
ODDS_SPORT = "americanfootball_nfl"
ODDS_BOOKS = ("fanduel", "draftkings")
ODDS_BOOK_LABELS = {"fanduel": "FanDuel", "draftkings": "DraftKings", STREAK_LINE_SOURCE: "Site line"}
ODDS_REFRESH_S = max(1, _safe_int(os.environ.get("ODDS_REFRESH_HOURS"), 12)) * 3600
ODDS_MARKETS = {
    "pass_yd": "player_pass_yds", "pass_td": "player_pass_tds",
    "pass_cmp": "player_pass_completions", "pass_att": "player_pass_attempts",
    "pass_int": "player_pass_interceptions", "pass_lng": "player_pass_longest_completion",
    "rush_yd": "player_rush_yds", "rush_att": "player_rush_attempts", "rush_lng": "player_rush_longest",
    "rec": "player_receptions", "rec_yd": "player_reception_yds", "rec_lng": "player_reception_longest",
    "rush_rec_yd": "player_rush_reception_yds", "any_td": "player_anytime_td",
    "kick_pts": "player_kicking_points", "fgm": "player_field_goals", "xpm": "player_pats",
    "idp_tkl": "player_tackles_assists", "idp_tkl_solo": "player_solo_tackles",
    "idp_sack": "player_sacks", "idp_int": "player_defensive_interceptions",
}
# If the full list is refused (a market key the API no longer knows), a
# refresh falls back to the ones every book carries rather than to none.
ODDS_CORE_MARKETS = ("player_pass_yds", "player_pass_tds", "player_rush_yds",
                     "player_receptions", "player_reception_yds", "player_anytime_td")
ODDS_MARKET_TO_PROP = {v: k for k, v in ODDS_MARKETS.items()}
_odds_state = {"last": 0.0, "last_key": None, "error": None, "remaining": None, "used": None,
               "events": 0, "lines": 0, "unmatched": [], "books": {}, "fell_back": False}
_book_lines_cache = {}
_odds_lock = threading.Lock()
_NAME_SUFFIXES = {"jr", "sr", "ii", "iii", "iv", "v"}


def odds_api_key():
    return (os.environ.get("ODDS_API_KEY") or "").strip()


def _odds_norm_name(name):
    """'Marvin Harrison Jr.' and 'marvin harrison' are one person."""
    words = re.sub(r"[^a-z0-9 ]", " ", (name or "").lower().replace("'", "")).split()
    return " ".join(w for w in words if w not in _NAME_SUFFIXES)


def _odds_team_abbr(full_name):
    """'Buffalo Bills' -> 'BUF', tolerating a city rename by matching the
    nickname when the full name is unknown."""
    key = (full_name or "").lower().strip()
    if not key:
        return None
    by_name = {v.lower(): k for k, v in TEAM_NAMES.items()}
    if key in by_name:
        return by_name[key]
    nick = key.split()[-1]
    for name, abbr in by_name.items():
        if name.split()[-1] == nick:
            return abbr
    return None


def _odds_player_index(players):
    by_team, by_name = {}, {}
    for sid, p in (players or {}).items():
        if not isinstance(p, dict) or not p.get("team"):
            continue
        n = _odds_norm_name(f"{p.get('first_name', '')} {p.get('last_name', '')}")
        if not n:
            continue
        by_team.setdefault((p["team"], n), sid)
        by_name.setdefault(n, []).append(sid)
    return by_team, by_name


def parse_odds_event(event, index):
    """{(sleeper_id, prop): {line, over, under, book}} from one event's
    odds payload, plus the names nothing matched.

    Outcomes come as name=Over/Under with the player in `description`;
    the anytime-TD market lists the player as the name with no point,
    which is a 0.5 line by definition. Both shapes are read."""
    by_team, by_name = index
    home = _odds_team_abbr(event.get("home_team"))
    away = _odds_team_abbr(event.get("away_team"))
    out, unmatched = {}, []
    for bm in event.get("bookmakers") or []:
        book = bm.get("key")
        if book not in ODDS_BOOKS:
            continue
        for mk in bm.get("markets") or []:
            prop = ODDS_MARKET_TO_PROP.get(mk.get("key"))
            if not prop:
                continue
            per_player = {}
            for oc in mk.get("outcomes") or []:
                if not isinstance(oc, dict):
                    continue
                side = (oc.get("name") or "").strip()
                who = oc.get("description") or ""
                if side.lower() not in ("over", "under", "yes", "no"):
                    who, side = side, "Yes"
                if not who:
                    continue
                entry = per_player.setdefault(who, {})
                if side.lower() in ("over", "yes"):
                    point = oc.get("point")
                    if point is None and prop == "any_td":
                        point = 0.5
                    entry["line"] = point
                    entry["over"] = oc.get("price")
                else:
                    entry["under"] = oc.get("price")
            for who, entry in per_player.items():
                if not isinstance(entry.get("line"), (int, float)):
                    continue
                n = _odds_norm_name(who)
                sid = by_team.get((home, n)) or by_team.get((away, n))
                if not sid:
                    cands = by_name.get(n) or []
                    sid = cands[0] if len(cands) == 1 else None
                if not sid:
                    unmatched.append(who)
                    continue
                key = (sid, prop)
                have = out.get(key)
                if have and ODDS_BOOKS.index(have["book"]) <= ODDS_BOOKS.index(book):
                    continue
                out[key] = {"line": float(entry["line"]), "over": entry.get("over"),
                            "under": entry.get("under"), "book": book}
    return out, unmatched


def _save_book_lines(season, week, lines):
    if not DATABASE_URL or not lines:
        return 0
    rows = [(int(season), int(week), sid, prop, v["line"], v.get("over"), v.get("under"), v["book"])
            for (sid, prop), v in lines.items()]
    conn = get_db()
    try:
        with conn.cursor() as cur:
            # Eight columns, eight values -- see record_injury_changes for
            # how a mismatch here fails silently.
            psycopg2.extras.execute_values(
                cur,
                """INSERT INTO prop_lines
                       (season, week, sleeper_id, prop, line, over_price, under_price, book)
                   VALUES %s
                   ON CONFLICT (season, week, sleeper_id, prop) DO UPDATE SET
                       line = EXCLUDED.line, over_price = EXCLUDED.over_price,
                       under_price = EXCLUDED.under_price, book = EXCLUDED.book,
                       fetched_at = NOW()""",
                rows)
        conn.commit()
    finally:
        conn.close()
    return len(rows)


def get_book_lines(season, week, cache=_book_lines_cache):
    """{(sleeper_id, prop): {line, over, under, book, fetched_at}} for the
    week, from the database. Never fetches: a page view must not be
    able to spend the quota."""
    key = (int(season), int(week))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    data = {}
    if DATABASE_URL:
        try:
            conn = get_db()
            try:
                with conn.cursor() as cur:
                    cur.execute(
                        """SELECT sleeper_id, prop, line, over_price, under_price, book, fetched_at
                           FROM prop_lines WHERE season = %s AND week = %s""", key)
                    for r in cur.fetchall():
                        data[(r["sleeper_id"], r["prop"])] = {
                            "line": r["line"], "over": r["over_price"], "under": r["under_price"],
                            "book": r["book"], "fetched_at": r["fetched_at"]}
            finally:
                conn.close()
        except Exception:
            data = {}
    cache[key] = {"data": data, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return data


def _odds_commence(value):
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except Exception:
        return None


def fetch_book_lines(season, week):
    """One refresh: this week's events, then each event's player-prop
    markets from the books we read. Returns the number of lines saved."""
    key = odds_api_key()
    if not key:
        return 0
    index = _odds_player_index(_players_or_empty())
    r = requests.get(f"{ODDS_API_BASE}/sports/{ODDS_SPORT}/events",
                     params={"apiKey": key}, timeout=20)
    r.raise_for_status()
    events = r.json() if isinstance(r.json(), list) else []
    now = datetime.now(timezone.utc)
    # Games still to come this week. A finished game's lines are gone
    # from the books anyway, and each event costs quota.
    upcoming = [e for e in events
                if (c := _odds_commence(e.get("commence_time"))) is not None
                and now - timedelta(hours=6) <= c <= now + timedelta(days=8)]
    markets = ",".join(ODDS_MARKETS.values())
    lines, unmatched, books = {}, [], {}
    fell_back = False
    for e in upcoming:
        params = {"apiKey": key, "regions": "us", "markets": markets,
                  "oddsFormat": "american", "bookmakers": ",".join(ODDS_BOOKS)}
        r = requests.get(f"{ODDS_API_BASE}/sports/{ODDS_SPORT}/events/{e.get('id')}/odds",
                         params=params, timeout=25)
        if r.status_code == 422 and not fell_back:
            # A market key the API no longer recognises refuses the
            # whole request. Drop to the core set for the rest of the
            # run rather than come back with nothing.
            fell_back = True
            markets = ",".join(ODDS_CORE_MARKETS)
            params["markets"] = markets
            r = requests.get(f"{ODDS_API_BASE}/sports/{ODDS_SPORT}/events/{e.get('id')}/odds",
                             params=params, timeout=25)
        _odds_state["remaining"] = r.headers.get("x-requests-remaining")
        _odds_state["used"] = r.headers.get("x-requests-used")
        r.raise_for_status()
        got, un = parse_odds_event(r.json() or {}, index)
        lines.update(got)
        unmatched.extend(un)
        for v in got.values():
            books[v["book"]] = books.get(v["book"], 0) + 1
    _save_book_lines(season, week, lines)
    _book_lines_cache.clear()
    _streaks_cache.clear()
    _odds_state.update({"events": len(upcoming), "lines": len(lines), "books": books,
                        "unmatched": sorted(set(unmatched))[:40], "fell_back": fell_back})
    return len(lines)


def refresh_book_lines(season, week, force=False):
    """Fetch if what we have is older than ODDS_REFRESH_HOURS. Called
    from the warm ping; a process restart measures age from the
    database's own timestamp, so a deploy never spends a refresh."""
    if not odds_api_key():
        return False
    key = (int(season), int(week))
    now = time.time()
    with _odds_lock:
        last = _odds_state["last"] if _odds_state["last_key"] == key else 0.0
        if not last:
            newest = [v.get("fetched_at") for v in get_book_lines(season, week).values()
                      if isinstance(v.get("fetched_at"), datetime)]
            if newest:
                when = _as_naive_utc(max(newest))
                last = (when - datetime(1970, 1, 1)).total_seconds() if when else 0.0
        if not force and last and now - last < ODDS_REFRESH_S:
            _odds_state["last"], _odds_state["last_key"] = last, key
            return False
        _odds_state["last"], _odds_state["last_key"] = now, key
    try:
        fetch_book_lines(season, week)
        _odds_state["error"] = None
    except Exception as e:
        _odds_state["error"] = str(e)[:300]
    return True


def build_streak_games(rows, prop, team, sched):
    """One player's chronological game list for one prop. The opponent
    is looked up by the player's CURRENT team -- the same accepted
    approximation defense-vs-position uses; a mid-season trade
    misattributes a handful of old weeks."""
    games = []
    for season, week, stats in rows:
        meta = sched.get((season, week, team)) or {}
        games.append({
            "season": season, "week": week,
            "opp": meta.get("opp"), "home": meta.get("home"),
            "date": meta.get("date") or f"W{week}",
            "value": streak_prop_value(prop, stats),
        })
    return games


def _streak_player_row(sid, p, prop, rows, sched, season, opponent=None, book=None):
    games = build_streak_games(rows, prop, p.get("team"), sched)
    if len(games) < STREAK_MIN_GAMES:
        return None
    values = [g["value"] for g in games]
    site_line = streak_line(values)
    if site_line is None:
        return None
    # The book's line when a book has one this week; the site's own
    # otherwise. Both travel with the row so the page can say which.
    line = float(book["line"]) if book and isinstance(book.get("line"), (int, float)) else site_line
    source = book["book"] if book and book.get("book") in ODDS_BOOK_LABELS else STREAK_LINE_SOURCE
    shown = games[-STREAK_BARS:]
    recent = values[-STREAK_LINE_GAMES:]
    avg = round(sum(recent) / len(recent), 1)
    windows = streak_windows(games, line, opponent=opponent, season=season)
    return {
        "sid": sid,
        "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip(),
        "team": p.get("team"), "position": p.get("position"),
        "group": streak_position_group(p.get("position")),
        "photo": player_photo_url(sid),
        "prop": prop[0], "prop_label": prop[1], "prop_short": prop[2],
        "integer": prop[5],
        "line": line, "site_line": site_line, "line_source": source,
        "book_label": ODDS_BOOK_LABELS.get(source, source),
        "over_price": (book or {}).get("over") if source != STREAK_LINE_SOURCE else None,
        "under_price": (book or {}).get("under") if source != STREAK_LINE_SOURCE else None,
        "avg": avg, "edge": round(avg - line, 1),
        "games": shown, "windows": windows,
    }


def _streak_opponents(players, season, week, sched):
    """{team: opponent this week} so every row's H2H means the same
    thing: the club they are about to play."""
    out = {}
    for p in players.values():
        t = (p or {}).get("team")
        if t and t not in out:
            out[t] = (sched.get((season, week, t)) or {}).get("opp")
    return out


def get_streak_board(prop_key, season, week, cache=_streaks_cache):
    """Every listed player for one prop, best L10 hit rate first."""
    prop = STREAK_PROP_BY_KEY.get(prop_key)
    if not prop:
        return []
    key = ("board", prop_key, int(season), int(week))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    seasons = streak_seasons(season)
    for yr in seasons:
        ensure_season_stats_synced(yr)
        ensure_stat_lines_synced(yr)
        ensure_schedule_synced(yr)
    players = _players_or_empty()
    logs = _streak_logs(seasons)
    sched = _streak_schedule_index(seasons)
    opps = _streak_opponents(players, season, week, sched)
    books = get_book_lines(season, week)
    # A player whose team has no game this week has no props this week
    # -- the list moves with the schedule, so a bye drops off and comes
    # back. Only enforced once the week's schedule is actually known:
    # an empty index means "not synced yet", not "everyone is on bye".
    week_known = any(k[0] == int(season) and k[1] == int(week) for k in sched)
    rows = []
    for sid, p in players.items():
        if not isinstance(p, dict) or not p.get("team"):
            continue
        if streak_position_group(p.get("position")) not in prop[3]:
            continue
        if week_known and not opps.get(p.get("team")):
            continue
        log = logs.get(sid)
        if not log:
            continue
        # Starters only. A backup quarterback has a log and a line and
        # no business on a props board.
        if not streak_is_starter(p, log):
            continue
        row = _streak_player_row(sid, p, prop, log, sched, int(season),
                                 opponent=opps.get(p.get("team")),
                                 book=books.get((sid, prop[0])))
        if row:
            rows.append(row)
    rows.sort(key=lambda r: (-(r["windows"]["l10"]["pct"] or 0), -r["edge"]))
    rows = rows[:STREAK_LIST_MAX]
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


def _streak_run(games, line, side):
    """Consecutive games on `side` of the line, counting back from the
    most recent one: the "six straight" a streak is named for."""
    n = 0
    for g in reversed(games):
        v = g["value"]
        if (v > line) if side == "over" else (v < line):
            n += 1
        else:
            break
    return n


def get_streak_trends(season, week, cache=_streaks_cache):
    """The best current streaks across every prop, on either side of the
    line: at least five games in the last ten and 80%+ of them over, or
    80%+ of them under. One row per player-prop, carrying which side."""
    key = ("trends", int(season), int(week))
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 600:
        return entry["data"]
    rows = []
    for prop in STREAK_PROPS:
        for r in get_streak_board(prop[0], season, week):
            w = r["windows"]["l10"]
            if w["n"] < STREAK_TREND_GAMES:
                continue
            if (w["pct"] or 0) >= STREAK_TREND_PCT:
                side, pct = "over", w["pct"]
            elif (w.get("under_pct") or 0) >= STREAK_TREND_PCT and r["line"] >= STREAK_UNDER_MIN_LINE:
                # Under a 0.5 or 1.5 line just means "doesn't do this much"
                # -- a receiver with no two-score games is not on an under
                # streak, and those would outrank every real over.
                side, pct = "under", w["under_pct"]
            else:
                continue
            rows.append(dict(r, side=side, trend_pct=pct,
                             streak=_streak_run(r["games"], r["line"], side)))
    # Strongest first: the rate, then how many games it is built on,
    # then the run, then how far the average sits from the line.
    rows.sort(key=lambda r: (-r["trend_pct"], -r["windows"]["l10"]["n"], -r["streak"],
                             -(abs(r["edge"]) / r["line"] if r["line"] else 0)))
    rows = rows[:STREAK_LIST_MAX]
    cache[key] = {"data": rows, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return rows


def _kickoff_label(when):
    """"12:00PM" on the league's clock, or None."""
    if not isinstance(when, datetime):
        return None
    try:
        local = (when.replace(tzinfo=timezone.utc) if when.tzinfo is None else when).astimezone(NFL_TZ)
        return local.strftime("%-I:%M%p")
    except Exception:
        return None


def get_streak_detail(sid, season, week):
    """One player, every prop their position offers, the whole log.

    Baked in full so the prop tabs switch without a round trip: a
    player's log is forty games at most and a prop is a formula over
    it, so the whole set is a few kilobytes."""
    players = _players_or_empty()
    p = players.get(sid)
    if not isinstance(p, dict):
        return None
    props = streak_props_for(p.get("position"))
    if not props:
        return None
    seasons = streak_seasons(season)
    for yr in seasons:
        ensure_season_stats_synced(yr)
        ensure_stat_lines_synced(yr)
        ensure_schedule_synced(yr)
    logs = _streak_logs(seasons)
    sched = _streak_schedule_index(seasons)
    team = p.get("team")
    nxt = get_schedule_for_team_week(int(season), int(week), team) if team else None
    opponent = nxt["opponent"] if nxt else None

    books = get_book_lines(season, week)
    per_prop = {}
    for prop in props:
        row = _streak_player_row(sid, p, prop, logs.get(sid) or [], sched, int(season),
                                 opponent=opponent, book=books.get((sid, prop[0])))
        if row:
            # The detail page shows the full log, not the list's twenty.
            row["games"] = build_streak_games(logs.get(sid) or [], prop, team, sched)
            # Where this player's L10 average sits among the position.
            board = get_streak_board(prop[0], season, week)
            ranked = sorted(board, key=lambda r: -r["avg"])
            row["pos_rank"] = next((i + 1 for i, r in enumerate(ranked) if r["sid"] == sid), None)
            row["pos_count"] = len(ranked)
            per_prop[prop[0]] = row

    grade = None
    dvp_rank = None
    if p.get("position") in POSITIONS:
        try:
            grade = compute_matchup_grade(sid, int(season), int(week))
        except Exception:
            grade = None
        if opponent:
            try:
                dvp_rank = ((get_defense_vs_position(int(season)).get(opponent) or {})
                            .get(p.get("position")) or {}).get("rank")
            except Exception:
                dvp_rank = None

    return {
        "sid": sid,
        "name": f"{p.get('first_name', '')} {p.get('last_name', '')}".strip(),
        "team": team, "team_name": TEAM_NAMES.get(team, team),
        "position": p.get("position"), "group": streak_position_group(p.get("position")),
        "position_name": POSITION_NAMES.get(p.get("position"), p.get("position")),
        "photo": player_photo_url(sid), "logo": team_logo_url(team),
        "props": [{"key": pr[0], "label": pr[1], "short": pr[2]} for pr in props
                  if pr[0] in per_prop],
        "per_prop": per_prop,
        "next": ({"opponent": opponent, "home": nxt["home"],
                  "kickoff": _kickoff_label(nxt.get("kickoff")),
                  "logo": team_logo_url(opponent)} if nxt else None),
        "grade": ({"grade": grade["grade"], "grade_class": grade["grade_class"]}
                  if grade else None),
        "dvp_rank": dvp_rank,
        "starter": streak_is_starter(p, logs.get(sid)),
    }


POSITION_NAMES = {
    "QB": "Quarterback", "RB": "Running Back", "WR": "Wide Receiver", "TE": "Tight End",
    "K": "Kicker", "DE": "Defensive End", "DT": "Defensive Tackle", "NT": "Nose Tackle",
    "DL": "Defensive Line", "LB": "Linebacker", "OLB": "Outside Linebacker",
    "ILB": "Inside Linebacker", "MLB": "Middle Linebacker", "CB": "Cornerback",
    "S": "Safety", "FS": "Free Safety", "SS": "Strong Safety", "DB": "Defensive Back",
}


_injury_state_lock = threading.Lock()
_injury_state_last = {"time": 0.0}
INJURY_STATE_REFRESH_S = 900


def _record_injury_changes_background():
    """Keep the transition history current off the request path.

    Driven by traffic rather than a cron: the first visitor after the
    interval lapses kicks this off and is not made to wait for it. That
    is what makes the arrows appear on their own -- the site does not
    depend on a scheduled job being configured."""
    now = time.time()
    with _injury_state_lock:
        if now - _injury_state_last["time"] < INJURY_STATE_REFRESH_S:
            return
        _injury_state_last["time"] = now

    def _run():
        try:
            with _BACKGROUND_SYNC_SLOTS:
                statuses, _ = build_injury_statuses()
                record_injury_changes(statuses)
        except Exception:
            pass

    threading.Thread(target=_run, daemon=True).start()


_injury_feed_cache = {}


# How long a return to Active stays on the injury board. A player coming
# back is the most useful row there is on the day it happens and noise a
# fortnight later, so it ages off rather than accumulating.
RETURN_NEWS_DAYS = 7


def _is_recent(when, days):
    """Whether `when` is within `days` of now. False for no timestamp --
    a change with no date cannot be shown to be recent."""
    when = _as_naive_utc(when)
    if not when:
        return False
    return (datetime.utcnow() - when) <= timedelta(days=days)


def _injury_history():
    """{sleeper_id: {status, previous_status, changed_at}} for every
    designation this app has watched change.

    Separate from the report that reads it so the two can be reasoned
    about -- and tested -- on their own."""
    if not DATABASE_URL:
        return {}
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT sleeper_id, status, previous_status, changed_at
                   FROM player_injury_state
                   WHERE previous_status IS NOT NULL
                     AND previous_status IS DISTINCT FROM status""")
            return {r["sleeper_id"]: dict(r) for r in cur.fetchall()}
    except Exception:
        return {}
    finally:
        conn.close()


def get_injury_report(limit=None, cache=_injury_feed_cache):
    """The league's injury report, most recently changed first.

    Every player currently carrying a designation, plus anyone who has
    just come back -- a return to Active is the most useful row on the
    board and the one the reference leads with.

    Where a change has been observed the row reads "Out -> Active"; where
    it has not (yet) it reads the current designation on its own. Sleeper
    and ESPN both publish only what IS, never what changed, so the arrow
    can only appear once this app has seen both sides of it."""
    now = time.time()
    entry = cache.get(limit)
    if entry and now - entry["time"] < 300:
        return entry["data"]

    statuses, espn_by_sid = build_injury_statuses()
    if not statuses:
        return []
    _record_injury_changes_background()

    history = _injury_history()

    players = _players_or_empty()
    out = []
    for sid, status in statuses.items():
        past = history.get(sid)
        if status == ACTIVE_STATUS:
            # A healthy player is only news if we watched them get
            # healthy, and only for as long as that is still news. The
            # league is mostly healthy players, and a recovery from
            # October should not still be sitting on the board in
            # January -- which is exactly what keeping every recorded
            # return forever produced.
            if not past or not _is_recent(past.get("changed_at"), RETURN_NEWS_DAYS):
                continue
        p = players.get(sid) or {}
        hit = espn_by_sid.get(sid) or {}
        # When this designation was PUBLISHED, in order of preference:
        # ESPN's own date for it, then the moment this app first saw it.
        # The league report drops as a batch, so everyone in one drop
        # shares a stamp -- which is why the reference board reads "4h"
        # down a whole run of rows.
        reported = (hit.get("since")
                    or _as_naive_utc((past or {}).get("changed_at")))
        out.append({
            "sid": sid,
            "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
            "position": p.get("position"),
            "team": p.get("team"),
            "logo": team_logo_url(p.get("team")),
            "photo": player_photo_url(sid),
            "from": display_status((past or {}).get("previous_status")),
            "to": display_status(status),
            "detail": hit.get("detail"),
            "good": status == ACTIVE_STATUS,
            "tone": injury_tone(status),
            "reported_at": reported,
            "ago": _time_ago(reported),
            "ts": _feed_ts(reported),
            "severity": _INJURY_ORDER.get(status, 5),
        })

    # Newest report first. A row with no date at all sinks to the bottom
    # rather than pretending to be either the freshest or the stalest.
    out.sort(key=lambda r: (r["reported_at"] is None,
                            -(r["reported_at"].timestamp() if r["reported_at"] else 0),
                            r["severity"], r["name"]))
    data = out[:limit] if limit else out
    cache[limit] = {"data": data, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return data


# How serious a designation is, for ordering a report nobody has seen
# change yet. Active first among those, since a return is the row worth
# reading.
# What colour a designation reads in. Derived from INJURY_BADGE's own
# tiers rather than restated, so the injury board and the depth-chart
# badges can never disagree about how serious something is.
#
# Green healthy, red out, yellow questionable -- with doubtful keeping
# the amber the badges already give it, since "probably not playing"
# genuinely sits between the two and flattening it into either one
# throws away the distinction.
_TIER_TONE = {"probable": "good", "out": "bad", "doubtful": "doubt",
              "questionable": "caution", "admin": "admin"}
_STATUS_TONE = {ACTIVE_STATUS: "good"}
for _code, (_label, _title, _tier) in INJURY_BADGE.items():
    _STATUS_TONE[_title] = _TIER_TONE.get(_tier, "admin")


def injury_tone(status):
    """The colour class for a designation. Anything unrecognised reads
    as a plain designation rather than as an alarm."""
    return _STATUS_TONE.get(status, "admin")


_INJURY_ORDER = {
    ACTIVE_STATUS: 0, "Injured Reserve": 1, "Physically Unable to Perform": 1, "Out": 2, "Doubtful": 3,
    "Questionable": 4,
}


def get_injury_changes(limit=INJURY_FEED_SIZE):
    """The short version for the scores board."""
    return get_injury_report(limit=limit)


# The NFL keeps its own calendar, and so does a feed that says a
# birthday started "7h" ago. Eastern is that calendar. Falls back to a
# fixed -5 if the container ships without a timezone database, which
# costs an hour during summer time and nothing else.
try:
    NFL_TZ = ZoneInfo("America/New_York")
except Exception:
    NFL_TZ = timezone(timedelta(hours=-5))


def _as_naive_utc(when):
    """A datetime comparable with utcnow(), whatever it arrived as.

    An aware datetime is converted before its tzinfo is dropped -- just
    stripping it would read a 00:00 Eastern timestamp as 00:00 UTC and
    report every birthday as starting four hours later than it did."""
    if not isinstance(when, datetime):
        return None
    if when.tzinfo is not None:
        return when.astimezone(timezone.utc).replace(tzinfo=None)
    return when


def _feed_ts(when):
    """A feed entry's moment as epoch seconds, for the page to place on
    the reader's own calendar. The day a change belongs to depends on
    where the reader is, which only their browser knows, so the server
    hands over the instant and the page draws the day rules itself."""
    when = _as_naive_utc(when)
    if not when:
        return None
    try:
        return int(when.replace(tzinfo=timezone.utc).timestamp())
    except Exception:
        return None


def _time_ago(when, now=None):
    """"4h", "2d" -- the age of something, the way a feed writes it.

    `now` exists so a caller working from a given day measures against
    that same day rather than against the wall clock; everything in
    production leaves it alone."""
    when = _as_naive_utc(when)
    if not when:
        return None
    try:
        delta = (_as_naive_utc(now) or datetime.utcnow()) - when
    except Exception:
        return None
    secs = max(0, int(delta.total_seconds()))
    if secs < 3600:
        return f"{max(1, secs // 60)}m"
    if secs < 86400:
        return f"{secs // 3600}h"
    return f"{secs // 86400}d"


def _ordinal_age(n):
    """22nd, 31st, 23rd -- reusing the same rule the rest of the site
    uses so an age and a draft slot are never written differently."""
    return ordinal(n)


def season_start_date(season, season_type=2):
    """The day the season opened, read from the schedule the site already
    holds rather than hardcoded -- so it is right every year without
    anyone remembering to change it."""
    days = get_season_game_days(season, season_type) or []
    for d in days:
        raw = d.get("kickoff") if isinstance(d, dict) else None
        if not raw:
            continue
        try:
            return datetime.fromisoformat(str(raw).replace("Z", "+00:00")).date()
        except (ValueError, TypeError):
            continue
    # Nothing synced yet: the NFL opens in the first full week of
    # September, which is close enough to bound a birthday list.
    return date(_safe_int(season, int(SEASON)), 9, 1)


def _birthday_this_year(y, m, d, year):
    """The date this player's birthday falls on in `year`.

    A 29 February birthday is marked on the 28th in a common year, which
    is the usual convention and better than skipping the player in three
    years out of four."""
    try:
        return date(year, m, d)
    except ValueError:
        if m == 2 and d == 29:
            return date(year, 2, 28)
        return None


def get_birthdays(season=None, limit=None, today=None, since=None, now=None):
    """Every rostered player whose birthday has come round since the
    season opened, most recent first.

    Not just today's: a board that is empty on every day nobody happens
    to have been born is a board nobody checks. The window runs from the
    season opener to today and grows on its own as the season does, with
    no list to maintain and nothing to switch over in January -- the
    opener comes from the schedule."""
    today = today or date.today()
    # A caller that names the day measures ages against that day too,
    # or every row on it reads as having started moments ago.
    now = now or (datetime.utcnow() if today == date.today()
                  else _day_started_at(today))
    season = _safe_int(season if season is not None else SEASON, int(SEASON))
    since = since or season_start_date(season)
    if since > today:
        since = date(today.year, 1, 1)

    out = []
    for sid, p in _players_or_empty().items():
        if not isinstance(p, dict) or not p.get("team"):
            continue
        raw = (p.get("birth_date") or "").strip()
        if not raw:
            continue
        try:
            y, m, d = [int(x) for x in raw.split("-")]
        except (ValueError, TypeError):
            continue
        # The window can straddle New Year (a season opening in September
        # runs into January), so both years are candidates.
        when = None
        for year in {today.year, today.year - 1}:
            cand = _birthday_this_year(y, m, d, year)
            if cand and since <= cand <= today:
                when = cand if (when is None or cand > when) else when
        if not when:
            continue
        age = when.year - y
        if age <= 0 or age > 70:
            continue
        out.append({
            "sid": sid,
            "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
            "position": p.get("position"),
            "team": p.get("team"),
            "logo": team_logo_url(p.get("team")),
            "photo": player_photo_url(sid),
            "age": age,
            "age_label": _ordinal_age(age),
            "date": when,
            "today": when == today,
            # Stamped from the moment the day itself started, not from
            # the moment this page was built -- so every birthday on a
            # given day carries the same age, and today's reads as the
            # hours since midnight rather than as nothing at all.
            "started_at": _day_started_at(when),
            "ago": _time_ago(_day_started_at(when), now),
            "day_key": when.isoformat(),
            "rank": p.get("search_rank") or 999999,
        })
    # Newest first, and within a day the players people have heard of.
    out.sort(key=lambda b: (-b["date"].toordinal(), b["rank"]))
    return out[:limit] if limit else out


def _day_started_at(day):
    """Midnight on `day`, on the league's own clock, as naive UTC.

    Eastern rather than the server's UTC: a birthday that starts at
    midnight in New York has not started yet at midnight in London, and
    the NFL's calendar is the one this board is keeping."""
    try:
        return _as_naive_utc(datetime(day.year, day.month, day.day, tzinfo=NFL_TZ))
    except Exception:
        return None


def get_birthdays_today(limit=BIRTHDAY_FEED_SIZE, today=None):
    """The scores board's short list: yesterday's, today's and tomorrow's
    birthdays by the server's clock, newest first. Tomorrow's ride along
    for a reader whose day has already turned, and the page hides
    whichever rows are still ahead of the reader's own clock -- the
    server cannot know where anyone is, so it sends the whole window
    and lets the browser decide what "today" means."""
    today = today or date.today()
    rows = get_birthdays(today=today + timedelta(days=1), since=today - timedelta(days=1),
                         now=datetime.utcnow())
    return rows[:limit * 3] if limit else rows


_team_rank_cache = {}


def get_team_rankings(season, season_type=2, cache=_team_rank_cache):
    """Power ranking over three windows -- the latest round, the last
    four rounds, and the whole season -- as {team: {"d7": n, "d30": n,
    "season": n}}.

    Ranked on average point differential, which is the single most
    predictive simple measure of team strength and, importantly, is
    computable from data the site already has.

    Three things make it a live ranking rather than a weekly one:

    * Games in progress count, at the score they currently hold, so the
      board moves while the games move.
    * The windows are counted in weeks rather than days. The NFL plays
      in rounds, and a date window catches the Thursday game but misses
      the Sunday one from the same round -- so "last 7 days" means the
      most recent round, and "last 30 days" the most recent four.
    * A team with nothing in a narrow window (a bye, or a round it has
      not played yet) inherits its rank from the next window out rather
      than showing a blank. Every team that has played is ranked in all
      three columns."""
    season, season_type = _safe_int(season, int(SEASON)), _safe_int(season_type, 2)
    key = (season, season_type)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < entry.get("ttl", 300):
        return entry["data"]

    games = _finished_games(season, season_type, include_live=True)
    live = any(g.get("status") == "in_progress" for g in games)
    latest_week = max((g["week"] for g in games if g["week"]), default=None)
    out = {t: {} for t in NFL_DIVISIONS}

    # Widest first, so each narrower window has something to fall back on.
    windows = [("season", None),
               ("d30", PLAYER_WINDOW_WEEKS["d30"]),
               ("d7", PLAYER_WINDOW_WEEKS["d7"])]
    wider = {"d30": "season", "d7": "d30"}

    for label, weeks in windows:
        totals = {}
        for g in games:
            if weeks is not None:
                if not g["week"] or latest_week is None:
                    continue
                if g["week"] <= latest_week - weeks:
                    continue
            for team, own, opp in ((g["home_team"], g["home_score"], g["away_score"]),
                                   (g["away_team"], g["away_score"], g["home_score"])):
                if team not in out or own is None or opp is None:
                    continue
                t = totals.setdefault(team, {"diff": 0, "games": 0})
                t["diff"] += own - opp
                t["games"] += 1
        ranked = sorted(((team, v["diff"] / v["games"]) for team, v in totals.items() if v["games"]),
                        key=lambda kv: -kv[1])
        for i, (team, avg) in enumerate(ranked, 1):
            out[team][label] = i
            # The figure the rank was computed from, so a list of the
            # ranking can show WHY a team sits where it does rather than
            # only that it does.
            out[team][label + "_avg"] = round(avg, 1)
            out[team][label + "_games"] = totals[team]["games"]
        # Teams with no game in this window come AFTER every team that
        # played one, in the order the next window out ranks them, and
        # the numbering carries on. They used to copy that wider rank
        # outright, which handed a team on its bye the same "1st" as the
        # team that had just won -- fine as a lone figure on a team page,
        # nonsense as a list of the league.
        fallback = wider.get(label)
        if fallback:
            rest = sorted((t for t, vals in out.items()
                           if label not in vals and fallback in vals),
                          key=lambda t: out[t][fallback])
            for i, team in enumerate(rest, len(ranked) + 1):
                vals = out[team]
                vals[label] = i
                vals[label + "_avg"] = vals.get(fallback + "_avg")
                vals[label + "_games"] = vals.get(fallback + "_games")
                vals[label + "_inherited"] = True

    # While games are being played the ranking is worth recomputing often;
    # between rounds it cannot change, so it is cached the usual way.
    cache[key] = {"data": out, "time": now, "ttl": 45 if live else 300}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return out


def get_team_schedule(team, season, season_type=2):
    """Every game on a team's schedule, played or not, oldest first --
    with the bye week identified by its absence rather than assumed."""
    season = _safe_int(season, int(SEASON))
    if not DATABASE_URL or not team:
        return {"games": [], "bye_week": None}
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT espn_event_id, week, kickoff, home_team, away_team,
                          home_score, away_score, status
                   FROM nfl_schedule
                   WHERE season = %s AND season_type = %s AND (home_team = %s OR away_team = %s)
                   ORDER BY week""",
                (season, season_type, team, team),
            )
            rows = [dict(r) for r in cur.fetchall()]
    except Exception:
        return {"games": [], "bye_week": None}
    finally:
        conn.close()

    games = []
    for r in rows:
        is_home = r["home_team"] == team
        own = r["home_score"] if is_home else r["away_score"]
        opp_score = r["away_score"] if is_home else r["home_score"]
        # Whether a game has a result is decided by its status, not by
        # whether a score column happens to hold a number -- rows written
        # before kickoff (and older rows that stored ESPN's placeholder
        # 0-0) otherwise render as a schedule full of ties.
        played = r["status"] in ("final", "in_progress") and own is not None and opp_score is not None
        games.append({
            "id": r["espn_event_id"], "week": r["week"], "kickoff": r["kickoff"],
            "opponent": r["away_team"] if is_home else r["home_team"],
            "home": is_home,
            "score": own if played else None,
            "opp_score": opp_score if played else None,
            "status": r["status"],
            "result": (("W" if own > opp_score else ("L" if own < opp_score else "T"))
                       if played else None),
            "diff": (own - opp_score) if played else None,
        })
    played_weeks = {g["week"] for g in games}
    bye = next((w for w in range(1, SCHEDULE_WEEKS_PER_SEASON + 1) if w not in played_weeks), None)
    return {"games": games, "bye_week": bye}


# NFL teams play once a week, so a "last 7 days" window is the most
# recent week and "last 30 days" is roughly the last four. Deriving the
# windows from weeks rather than from timestamps keeps them aligned to
# games actually played -- a date-based window would sometimes catch a
# Thursday game and miss the Sunday one from the same round.
PLAYER_WINDOW_WEEKS = {"d7": 1, "d30": 4}
_player_rank_cache = {}


def get_player_window_ranks(season, cache=_player_rank_cache):
    """{sleeper_id: {d7, d30, season, alltime}} -- where each player
    ranks by fantasy points over each window.

    All-time spans every season this database holds, back to
    PERF_EARLIEST_SEASON, so it grows as the backfill does rather than
    being pinned to a fixed set."""
    season = _safe_int(season, int(SEASON))
    # Derived from fantasy points, so the format it was built in is part
    # of its identity -- otherwise whoever loads a season first decides
    # the numbers everyone after them gets.
    _sc = current_scoring()
    now = time.time()
    entry = cache.get((season, _sc))
    if entry and now - entry["time"] < 900:
        return entry["data"]

    stats = get_season_stats(season) or {}
    weeks_seen = [_safe_int(w, 0) for s in stats.values() for w in (s.get("weeks") or {})]
    latest_week = max(weeks_seen) if weeks_seen else 0

    totals = {"d7": {}, "d30": {}, "season": {}, "alltime": {}}
    for sid, stat in stats.items():
        for w, pts in (stat.get("weeks") or {}).items():
            if not isinstance(pts, (int, float)):
                continue
            wk = _safe_int(w, 0)
            totals["season"][sid] = totals["season"].get(sid, 0) + pts
            for label, span in PLAYER_WINDOW_WEEKS.items():
                if latest_week and wk > latest_week - span:
                    totals[label][sid] = totals[label].get(sid, 0) + pts

    for yr in range(season, PERF_EARLIEST_SEASON - 1, -1):
        for sid, stat in (get_season_stats(yr) or {}).items():
            for _w, pts in (stat.get("weeks") or {}).items():
                if isinstance(pts, (int, float)):
                    totals["alltime"][sid] = totals["alltime"].get(sid, 0) + pts

    out = {}
    for label, bucket in totals.items():
        for i, (sid, _pts) in enumerate(
                sorted(bucket.items(), key=lambda kv: -kv[1]), 1):
            out.setdefault(sid, {})[label] = i
    cache[(season, _sc)] = {"data": out, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return out


def get_team_roster(team, season):
    """The team's players, split offence/defence, each with their window
    ranks -- the roster view on the team page.

    Read down the page by position in depth-chart order -- quarterbacks,
    backs, receivers, tight ends -- and within each position by season
    rank, so the starter leads their own group rather than every
    quarterback being buried under the receivers. Players who have not
    played this season are gathered at the bottom as the bench, in the
    same position order."""
    if not team:
        return {"offense": [], "defense": []}
    ranks = get_player_window_ranks(season)
    out = {"offense": [], "defense": []}
    for sid, p in (get_all_players() or {}).items():
        if p.get("team") != team:
            continue
        pos = p.get("position")
        if not pos or pos not in SCORED_POSITIONS:
            continue
        r = ranks.get(sid) or {}
        out["defense" if pos in IDP_POSITIONS else "offense"].append({
            "sid": sid,
            "name": f"{p.get('first_name','')} {p.get('last_name','')}".strip(),
            "position": pos,
            "number": p.get("number"),
            "status": (p.get("status") or "").title() or None,
            "injury": _injury_badge(p),
            "photo": player_photo_url(sid),
            "ranks": r,
        })
    order = {pos: i for i, pos in enumerate(POSITIONS + IDP_POSITIONS)}
    for group in out.values():
        for p in group:
            p["bench"] = not p["ranks"].get("season")
        group.sort(key=lambda x: (1 if x["bench"] else 0,
                                  order.get(x["position"], len(order)),
                                  x["ranks"].get("season") or 10**9,
                                  x["name"]))
    return out


def _utc_isoformat(dt):
    """An ISO timestamp a browser will read as UTC.

    `nfl_schedule.kickoff` is a naive TIMESTAMP holding UTC wall time.
    `new Date("2026-09-14T00:15:00")` -- no offset -- is LOCAL time by
    the ECMAScript spec, so handing the client a bare isoformat() means
    it never converts and every late kickoff lands a day late."""
    if not dt:
        return None
    if getattr(dt, "tzinfo", None) is None:
        return dt.replace(tzinfo=timezone.utc).isoformat()
    return dt.astimezone(timezone.utc).isoformat()


def get_season_game_days(season, season_type=2, cache={}):
    """Every date the season has games on, as
    [{date, week, kickoff_utc}, ...] in order.

    Read from nfl_schedule rather than ESPN, because the date strip needs
    the WHOLE season at once and fetching 18 weeks from ESPN on every
    page load to build a list of tab labels would be absurd. One indexed
    query gives the entire grid.

    The dates here are UTC calendar days, used only to enumerate which
    tabs should exist -- the client still derives each tab's real local
    day from the kickoff timestamp, since a Sunday night game is already
    Monday in UTC for anyone west of the UK.

    Which is why every kickoff goes out explicitly marked as UTC. The
    column is a naive TIMESTAMP holding UTC wall time, and an ISO string
    with no offset is parsed by browsers as LOCAL time -- so without the
    marker the conversion never happens and Thursday Night Football shows
    up as a Friday tab, Monday night as a Tuesday one."""
    season, season_type = _safe_int(season, int(SEASON)), _safe_int(season_type, 2)
    key = (season, season_type)
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < 3600:
        return entry["data"]
    if not DATABASE_URL:
        return []
    conn = get_db()
    try:
        with conn.cursor() as cur:
            cur.execute(
                """SELECT week, MIN(kickoff) AS first_kick
                   FROM nfl_schedule
                   WHERE season = %s AND season_type = %s AND kickoff IS NOT NULL
                   GROUP BY week, DATE(kickoff)
                   ORDER BY first_kick""",
                (season, season_type),
            )
            rows = cur.fetchall()
    except Exception:
        rows = []
    finally:
        conn.close()
    days = [{"week": r["week"], "kickoff": _utc_isoformat(r["first_kick"])}
            for r in rows if r.get("first_kick")]
    cache[key] = {"data": days, "time": now}
    _cache_trim(cache, CACHE_LIMIT_BOARDS)
    return days


def _nearby_weeks_games(season, week, season_type=2):
    """The requested week plus the week before and after, fetched in
    parallel -- gives the date strip several confirmed game-day tabs to
    slide through right away instead of just the ~3 days in one ESPN
    week, without eagerly pulling the whole season. Weeks below 1 are
    skipped rather than sent to ESPN (which would just 400/empty)."""
    weeks_to_fetch = [w for w in (week - 1, week, week + 1) if w >= 1]
    games = []
    with ThreadPoolExecutor(max_workers=len(weeks_to_fetch)) as executor:
        futures = [executor.submit(_week_games, season, w, season_type) for w in weeks_to_fetch]
        for f in futures:
            games.extend(f.result()[0])
    return games


def _safe_feed(fn):
    """Run a decoration feed, or give up on it quietly.

    Belt as well as braces: the feeds guard their own inputs, and this
    guards the route against anything they did not anticipate. The
    scoreboard is the page; Injuries and Birthdays are not worth it."""
    try:
        return fn() or []
    except Exception:
        return []


# The Scores page, rendered once and shared.
#
# On a Sunday at one o'clock everybody opens this page in the same two
# minutes, and until now every one of them got their own render. The
# data behind it was already cached; the render itself, some thirty
# milliseconds of template work, was not -- and five hundred of those
# arriving together is more than half a core can do in the time
# people are willing to wait.
#
# The page is the same for everyone except two things: the banner that
# names the reader and the list of which of the reader's own players
# are on each club. Both are rendered per request and substituted into
# the shared HTML at two markers. Everything else -- the games, the
# performers, the power board, the feeds, the theme -- is rendered once
# every SCORES_PAGE_TTL_S seconds per (week, theme, signed-in) and handed
# to everyone. Nothing about one reader can reach another because
# nothing about any reader is in the shared copy.
#
# One lock, so a burst of arrivals on an expired copy does one render
# and waits for it, not five hundred renders at once.
SCORES_PAGE_TTL_S = 5
_scores_page_cache = {}
_scores_page_lock = threading.Lock()

_SCORES_BANNER_SYNCED = """<div class="sc-sync-banner">
    <span>Showing how many of <strong style="color:var(--sc-text);">{{ username }}</strong>'s players are in each game.</span>
    <span style="display:flex; gap:14px;"><a href="/matchup">Your matchup &rsaquo;</a><a href="/league-manager">Manage synced leagues</a></span>
  </div>"""
_SCORES_BANNER_OPEN = "<!--__SCORES_BANNER__-->"
_SCORES_BANNER_CLOSE = "<!--/__SCORES_BANNER__-->"
_MY_PLAYERS_TOKEN = "/*__MY_PLAYERS__*/{}"


def _scores_shared_html(season, week, season_type, info, cache=_scores_page_cache):
    """The Scores page with the two personal markers still in it, from
    the cache when it is fresh, rendered once otherwise. Returns
    (html, hit)."""
    ctx = _theme_context()
    key = (season, week, season_type, date.today().isoformat(),
           ctx["site_theme"], ctx["site_accent"], ctx["site_signed_in"])
    now = time.time()
    entry = cache.get(key)
    if entry and now - entry["time"] < SCORES_PAGE_TTL_S:
        return entry["html"], True
    with _scores_page_lock:
        # Whoever held the lock may have rendered it while we waited.
        entry = cache.get(key)
        if entry and time.time() - entry["time"] < SCORES_PAGE_TTL_S:
            return entry["html"], True
        games = _nearby_weeks_games(season, week, season_type)
        # The whole week's board is baked in, and the client filters it
        # to the teams that played on the selected date -- see
        # get_week_performers for why the date split has to happen there.
        performers = get_week_performers(season, week, allow_fetch=False)
        # Every game day in the season, so the strip scrolls straight
        # through to any week instead of dead-ending at the fetched
        # window. Games for a day outside that window load on demand.
        season_days = get_season_game_days(season, season_type)
        html_out = render_template_string(
            SCORES_HTML, games=games, season=season, week=week, season_type=season_type,
            score_mark=SCORE_MARK_SVG, season_days=season_days,
            current_season=info["season"], current_week=info["week"],
            today_key=date.today().isoformat(), load_error=None,
            performers=performers, power=get_power_board(season, season_type),
            perf_groups=PERFORMER_GROUPS,
            injuries=_safe_feed(get_injury_changes),
            moves=_safe_feed(get_moves_today),
            birthdays=_safe_feed(get_birthdays_today),
        )
        # One week of the page at a time. A week nobody is looking at
        # any more is not worth the memory, and the key already carries
        # everything a copy depends on.
        cache.clear()
        cache[key] = {"html": html_out, "time": time.time()}
        return html_out, False


def _scores_personal(shared_html, username):
    """The shared page made this reader's: their banner in place of the
    guest one, their players in place of the empty default. A guest gets
    the page back with only the markers removed.

    This must never raise. It runs on the error path too -- the page the
    route falls back to when something upstream broke -- so an exception
    escaping here turns a page that was going to explain itself into a
    bare 500. Reading the synced-league list is a database call, and a
    database having a bad second is exactly when the error path runs.
    The whole of it degrades to the guest version instead."""
    league_ids = None
    try:
        if current_user.is_authenticated:
            league_ids = get_synced_league_ids(current_user.id)
    except Exception:
        app.logger.warning("scores: could not read synced leagues", exc_info=True)
    has_synced = bool(league_ids)
    by_team = {}
    if has_synced and username:
        try:
            by_team = get_my_players_by_team(username, league_ids) or {}
        except Exception:
            by_team = {}
    start = shared_html.find(_SCORES_BANNER_OPEN)
    end = shared_html.find(_SCORES_BANNER_CLOSE)
    if start != -1 and end != -1:
        if has_synced:
            banner = render_template_string(_SCORES_BANNER_SYNCED, username=username)
        else:
            banner = shared_html[start + len(_SCORES_BANNER_OPEN):end]
        shared_html = shared_html[:start] + banner + shared_html[end + len(_SCORES_BANNER_CLOSE):]
    return shared_html.replace(_MY_PLAYERS_TOKEN, json.dumps(by_team, sort_keys=True), 1)


@app.route("/scores")
def scores_page():
    username = _resolve_scores_username()
    try:
        info = get_current_week_info()
        # The three pages built on nfl_schedule are the ones that have to
        # keep it current. This used to hang off the matchup-grade paths
        # only, so a visitor who went straight to Scores, Standings or a
        # team page never triggered a refresh and sat looking at games
        # frozen at their pre-kickoff state.
        refresh_open_schedule_weeks(info["season"])
        season = request.args.get("season", default=info["season"], type=int)
        week = request.args.get("week", default=info["week"], type=int)
        season_type = request.args.get("seasontype", default=info["season_type"], type=int)
        shared, hit = _scores_shared_html(season, week, season_type, info)
        resp = make_response(_scores_personal(shared, username))
        # Says whether this copy was rendered for this request or shared
        # from an earlier one, so a wrong-looking number can be traced.
        resp.headers["X-Scores-Cache"] = "hit" if hit else "miss"
        return resp
    except Exception as e:
        # ESPN's API is unofficial and unverified against a live response
        # from this environment -- surface the real error on the page
        # instead of a bare 500, so a shape mismatch is diagnosable from
        # a screenshot alone rather than looking like the page is dead.
        # Never cached: an error page is not a page anyone else should
        # be handed.
        page = render_template_string(
            SCORES_HTML, games=[], season=int(SEASON), week=1, season_type=2,
            score_mark=SCORE_MARK_SVG, season_days=[],
            current_season=int(SEASON), current_week=1, today_key=date.today().isoformat(),
            load_error=str(e),
            performers=[], power=[], perf_groups=PERFORMER_GROUPS,
            injuries=[], moves=[], birthdays=[],
        )
        # Belt as well as braces. _scores_personal is written not to
        # raise; if it ever does, the reader still gets the page that
        # says what went wrong rather than nothing at all.
        try:
            return _scores_personal(page, username)
        except Exception:
            app.logger.exception("scores: personalising the error page failed")
            return page


