# The two halves of the site, and what lives in each.
#
# Six links in one flat row said nothing about how the site is actually
# organised: Scores is the live NFL, everything else is the reader's own
# fantasy team, and the row gave a stranger no way to tell which was
# which. Grouping them names the split.
#
# Each entry is (active-key, href, label, one-line description).
# Live is one tap, not a menu. Everything that used to be listed under
# it -- Standings, Performances, Injuries -- is already a heading with
# its own "View all" on the scores board itself, so the dropdown was a
# second way to reach pages the destination page already links to, at
# the cost of making the live side of the site harder to get to than the
# fantasy side. Its `active` keys still exist and still light the link
# (see NAV_LIVE_KEYS), so a standings or performance page reads as
# current without being listed.
NAV_LIVE = ("live", "/scores", "Live")
# Streaks sits beside Live rather than ninth inside a dropdown. It is
# what the site is named for, and a menu is where a feature goes to
# stay undiscovered.
NAV_STREAKS = ("streaks", "/streaks", "Streaks")
NAV_STREAKS_KEYS = ("streaks",)

NAV_LIVE_KEYS = ("live", "scores", "standings", "performances",
                 "injuries", "moves", "birthdays")

# The top bar and the phone's bottom bar are now the same four
# destinations, in the same order, drawn with the same icons -- read
# out of TABBAR_SECTIONS rather than written twice, which is how the
# two drifted into calling one page "Live" and "Scores" at once.
#
# "You" is not here: on desktop it is the account menu at the end of
# the row, which holds more than a tab ever could.
NAV_TOP_KEYS = ("streaks", "scores", "rankings", "matchups")
NAV_ACTIVE_FOR = {
    "scores": NAV_LIVE_KEYS,
    "streaks": NAV_STREAKS_KEYS,
    "rankings": ("rankings", "player", "trade", "sbc", "kickers"),
    "matchups": ("matchups", "lineup", "waivers"),
}


def nav_top_sections():
    """(key, label, href, icon) for each primary destination, in the
    order the bar shows them."""
    by_key = {k: (k, label, href, icon) for k, label, href, icon in TABBAR_SECTIONS}
    return [by_key[k] for k in NAV_TOP_KEYS if k in by_key]

# Fantasy stays a menu, and now holds only what the top row does not:
# Rankings and Matchups moved up to be destinations in their own right,
# so listing them twice would just be two doors into one room.
NAV_GROUPS = [
    ("mycalc", "Fantasy", [
        # Free tools first, the StreakPros+ ones (see PLUS_KEYS) last.
        ("league", "/league-manager", "League Manager", "Your synced leagues and rosters"),
        ("matchup", "/matchup", "Your Matchup", "Live score and win odds in your league"),
        ("trade", "/trade-calculator", "Trade Calculator", "Weigh any trade both ways"),
        ("sbc", "/start-bench-cut", "Start/Bench/Cut", "Help keep the rankings sharp"),
        ("lineup", "/lineup", "Lineup", "Who to start this week, and why"),
        ("waivers", "/waivers", "Waiver Targets", "The best free agents in your league"),
        ("plus", "/plus", "StreakPros+", "Every tier, every list, every grade"),
    ]),
]


def make_header(active=""):
    def cls(name):
        return "active" if name == active else ""

    # A group reads as current when the page you are on is one of its
    # own, so the header still answers "where am I" at a glance now that
    # the links themselves are a tap away.
    groups = []
    for key, label, items in NAV_GROUPS:
        here = active == key or any(item[0] == active for item in items)
        links = "".join(
            f'''<a class="{cls(k)}" href="{href}">
               <span class="navgrp-lab">{text}{PLUS_MARK_SVG if k in PLUS_KEYS else ""}</span>
               <span class="navgrp-desc">{desc}</span>
             </a>'''
            for k, href, text, desc in items
        )
        groups.append(f'''
    <details class="navgrp" data-nav="{key}">
      <summary class="{"on" if here else ""}">
        <span>{label}</span><span class="navgrp-caret">&#9660;</span>
      </summary>
      <div class="navgrp-menu">{links}</div>
    </details>''')
    nav_groups = "".join(groups)

    # Live is a plain link, and reads as current on any of the live-side
    # pages -- including the ones it no longer lists.
    top_links = "".join(
        f'<a class="navtop {"active" if active in NAV_ACTIVE_FOR.get(key, (key,)) else ""}" '
        f'href="{href}">{icon}<span>{label}</span>'
        f'{PLUS_MARK_SVG if key in PLUS_KEYS else ""}</a>'
        for key, label, href, icon in nav_top_sections())

    return f"""
<header class="site"><div class="wrap nav-row">
  <a class="wordmark" href="/">{LOGO_SVG}<span>StreakPros</span></a>
  <input type="checkbox" id="navToggle" class="nav-toggle-checkbox">
  <label for="navToggle" class="nav-toggle-btn" aria-label="Menu">&#9776;</label>
  <nav class="links">{top_links}{nav_groups}
    {{% if current_user.is_authenticated %}}
      <details class="acct">
        <summary aria-label="Account menu">
          {{% if current_user.avatar_version %}}
          <img class="acct-disc acct-photo"
               src="/avatar/{{{{ current_user.id }}}}?v={{{{ current_user.avatar_version }}}}" alt="">
          {{% else %}}
          <span class="acct-disc">{{{{ (current_user.username or '?')[:2] }}}}</span>
          {{% endif %}}
          <span class="acct-caret">&#9660;</span>
        </summary>
        <div class="acct-menu">
          <div class="acct-who">
            <b>{{{{ current_user.username }}}}</b>
            <span>{{{{ current_user.email or 'Signed in' }}}}</span>
          </div>
          <a href="/settings"><span class="ico">&#9881;</span>Settings</a>
          <a href="/league-manager"><span class="ico">&#9776;</span>My Leagues</a>
          <div class="sep"></div>
          <a class="out" href="/logout"><span class="ico">&#8677;</span>Log Out</a>
        </div>
      </details>
    {{% else %}}
      <a href="/login">Sign In</a><a href="/signup">Create Account</a>
    {{% endif %}}
  </nav>
</div></header>
"""

# A feed's day rules, drawn in the browser. Each row carries the
# instant it happened (data-ts) or, for a birthday, its calendar day
# (data-day). On a full "View all" page (.fd-list) the page groups rows
# by the reader's local day, writes a rule above the first row of each
# day already behind them, and none for today -- and redraws at their
# next midnight, so a list left open overnight files yesterday's rows
# under yesterday on its own. The short lists on the scores page
# (.sc-feed) get no rules at all; they still hide a birthday the
# reader's clock has not reached and stamp today's from their midnight.
FEED_DAYS_JS = """
<style>
  /* A row the script hides stays hidden: the rows' own display:flex
     would otherwise beat the attribute, and tomorrow's birthday would
     show up a day early. */
  .sc-feed-row[hidden], .fd-row[hidden]{ display:none !important; }
</style>
<script>
(function(){
  function key(d){ return d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate(); }
  function dayOf(row){
    var ts = row.getAttribute('data-ts'), day = row.getAttribute('data-day');
    if (ts) return new Date(parseInt(ts, 10) * 1000);
    if (day) { var p = day.split('-'); return new Date(+p[0], +p[1]-1, +p[2]); }
    return null;
  }
  function label(d){
    try { return d.toLocaleDateString(undefined, {month:'short', day:'numeric', year:'numeric'}); }
    catch (e) { return d.toDateString(); }
  }
  function ago(d, now, isDay){
    // A calendar day's age is measured from the reader's own midnight;
    // a moment's from now. "1m" at the least, the way the feed writes it.
    var start = isDay ? d : d, secs = Math.max(0, Math.floor((now - start) / 1000));
    if (isDay){
      var mid = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      if (key(d) === key(now)) secs = Math.max(0, Math.floor((now - mid) / 1000));
      else return Math.max(1, Math.round((mid - d) / 86400000)) + 'd';
    }
    if (secs < 3600) return Math.max(1, Math.floor(secs / 60)) + 'm';
    if (secs < 86400) return Math.floor(secs / 3600) + 'h';
    return Math.floor(secs / 86400) + 'd';
  }
  function draw(){
    var now = new Date(), today = key(now);
    var midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    document.querySelectorAll('.fd-list, .sc-feed').forEach(function(list){
      list.querySelectorAll('.feed-day, .feed-quiet').forEach(function(n){ n.remove(); });
      var fd = list.classList.contains('fd-list');
      var cls = fd ? 'fd-day' : 'sc-day', last = null, shown = 0;
      Array.prototype.slice.call(list.children).forEach(function(row){   // a copy: inserting rules must not shift the walk
        var d = dayOf(row); if (!d) return;
        var isDay = row.hasAttribute('data-day');
        // A birthday the reader's clock has not reached yet waits for it.
        if (isDay && d > midnight){ row.hidden = true; row.style.display = 'none'; return; }
        row.hidden = false; row.style.display = ''; shown++;
        var stamp = row.querySelector('.feed-ago');
        if (stamp && isDay) stamp.textContent = ago(d, now, true);
        var k = key(d);
        if (k === today || !fd) { last = k; return; }
        if (k !== last){
          var rule = document.createElement('div');
          rule.className = cls + ' feed-day'; rule.textContent = label(d);
          list.insertBefore(rule, row);
        }
        last = k;
      });
      if (!shown && list.querySelector('[data-day]')){
        var q = document.createElement('div');
        q.className = (fd ? 'fd-empty' : 'sc-feed-quiet') + ' feed-quiet';
        q.textContent = 'No birthdays yet today.';
        list.appendChild(q);
      }
    });
  }
  function armMidnight(){
    var now = new Date(), next = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 0, 0, 2);
    setTimeout(function(){ draw(); armMidnight(); }, next - now);
  }
  function init(){
    draw(); armMidnight();
    document.addEventListener('visibilitychange', function(){ if (!document.hidden) draw(); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
</script>
"""

